  const ESC = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  function renderLocationHierarchyOptions(selectedId = '', placeholder = 'Pilih Lokasi', includeAllOption = false) {
    const locations = state.masters?.locations || [];
    let html = includeAllOption ? `<option value="">${ESC(placeholder)}</option>` : (placeholder ? `<option value="">${ESC(placeholder)}</option>` : '');

    const parents = locations.filter(l => !l.parent_id);
    const childrenMap = new Map();
    locations.forEach(l => {
      if (l.parent_id) {
        if (!childrenMap.has(l.parent_id)) childrenMap.set(l.parent_id, []);
        childrenMap.get(l.parent_id).push(l);
      }
    });

    parents.forEach(p => {
      const subs = childrenMap.get(p.id) || [];
      if (subs.length > 0) {
        html += `<optgroup label="📍 ${ESC(p.name)} (${ESC(p.code)})">`;
        html += `<option value="${p.id}" ${String(selectedId) === String(p.id) ? 'selected' : ''}>${ESC(p.name)} (Seluruh Area Induk)</option>`;
        subs.forEach(s => {
          html += `<option value="${s.id}" ${String(selectedId) === String(s.id) ? 'selected' : ''}>&nbsp;&nbsp;↳ ${ESC(s.name)} [${ESC(s.code)}]</option>`;
        });
        html += `</optgroup>`;
      } else {
        html += `<option value="${p.id}" ${String(selectedId) === String(p.id) ? 'selected' : ''}>📍 ${ESC(p.name)} [${ESC(p.code)}]</option>`;
      }
    });

    const orphanSubs = locations.filter(l => l.parent_id && !parents.some(p => p.id === l.parent_id));
    if (orphanSubs.length > 0) {
      html += `<optgroup label="Sub-Area Lainnya">`;
      orphanSubs.forEach(s => {
        html += `<option value="${s.id}" ${String(selectedId) === String(s.id) ? 'selected' : ''}>&nbsp;&nbsp;↳ ${ESC(s.name)} [${ESC(s.code)}]</option>`;
      });
      html += `</optgroup>`;
    }

    return html;
  }

  function getBaseUrl() {
    return typeof global.getApiBaseUrl === 'function' ? global.getApiBaseUrl() : '';
  }

  async function api(path, options = {}) {
    const base = getBaseUrl();
    const token = localStorage.getItem('admin_token') || global.state?.token || '';
    const res = await fetch(`${base}/api/hse${path}`, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        ...(options.headers || {}),
      },
      ...(options.body ? { body: typeof options.body === 'string' ? options.body : JSON.stringify(options.body) } : {}),
    });

    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      const err = new Error(data.error || `HTTP ${res.status}`);
      err.status = res.status;
      throw err;
    }
    return data;
  }

