  async function loadData() {
    try {
      const [overviewData, mastersData] = await Promise.all([
        api('/overview').catch(() => null),
        api('/masters').catch(() => ({ locations: [], categories: [], riskMatrix: [], employees: [] })),
      ]);
      state.overview = overviewData;
      state.masters = mastersData;
      if (state.view === 'hazard') {
        if (state.hazardSubTab === 'inspection') {
          await loadInspectionData();
        } else if (state.hazardSubTab === 'ibpr') {
          await loadRiskRegisterData();
        } else if (state.hazardSubTab === 'p5m') {
          await loadHseEvents('p5m');
        } else if (state.hazardSubTab === 'safetytalk') {
          await loadHseEvents('safetytalk');
        } else {
          await loadHazardsAndActions();
        }
      } else if (state.view === 'incident') {
        await loadIncidents();
      } else if (state.view === 'reports') {
        await loadSafetyReports();
      } else if (state.view === 'competency') {
        await loadCompetencyData();
      } else if (state.view === 'ptw') {
        await loadPtwData();
      } else if (state.view === 'occ-health') {
        await loadOccHealthData();
      } else if (state.view === 'emergency') {
        await loadEmergencyData();
      } else if (state.view === 'ppe') {
        await loadPpeData();
      } else if (state.view === 'contractor') {
        await loadContractorData();
      } else if (state.view === 'environment') {
        await loadEnvironmentData();
      } else if (state.view === 'audit') {
        await loadAuditData();
      } else if (state.view === 'documents') {
        await loadDocumentsData();
      } else if (state.view === 'setup') {
        if (state.setupTab === 'inspections') {
          await loadSetupInspectionsData();
        } else if (state.setupTab === 'hazard') {
          await loadSetupHazardData();
        } else if (state.setupTab === 'p5m') {
          await loadSetupP5mData();
        } else if (state.setupTab === 'safetytalk') {
          await loadSetupStData();
        } else if (state.setupTab === 'workhours') {
          await loadSetupWorkhoursData();
        } else if (state.setupTab === 'ai') {
          await global.OMOSHseAi?.loadSetup(api);
        } else if (state.setupTab === 'delegators') {
          await global.OMOSHseDelegators?.loadSetup(api);
        } else {
          await loadSetupLocations();
        }
      }
    } catch (err) {
      console.error('Gagal memuat data HSE:', err);
    }
  }

