  async function loadSetupLocations() {
    try {
      const res = await api('/locations/tree').catch(() => ({ items: [] }));
      state.setupLocations = Array.isArray(res.items) ? res.items : [];
      if (!state.selectedParentLocationId && state.setupLocations.length > 0) {
        state.selectedParentLocationId = state.setupLocations[0].id;
      } else if (state.selectedParentLocationId) {
        const found = state.setupLocations.some(l => l.id === state.selectedParentLocationId);
        if (!found && state.setupLocations.length > 0) {
          state.selectedParentLocationId = state.setupLocations[0].id;
        }
      }
      const mastersRes = await api('/masters').catch(() => null);
      if (mastersRes?.locations) {
        state.masters.locations = mastersRes.locations;
      }
    } catch (err) {
      console.error('Gagal memuat master lokasi setup:', err);
      state.setupLocations = [];
    }
  }

  async function loadSetupInspectionsData() {
    try {
      const mastersRes = await api('/masters').catch(() => null);
      if (mastersRes) {
        if (mastersRes.locations) state.masters.locations = mastersRes.locations;
        if (mastersRes.employees) state.masters.employees = mastersRes.employees;
        if (mastersRes.positions) state.masters.positions = mastersRes.positions;
        if (mastersRes.departments) state.masters.departments = mastersRes.departments;
      }

      if (state.setupInspectionSubTab === 'templates') {
        const query = {};
        if (state.setupInspFilterType) query.inspection_type = state.setupInspFilterType;
        if (state.setupInspFilterCycle) query.schedule_cycle = state.setupInspFilterCycle;
        if (state.setupInspFilterSearch) query.search = state.setupInspFilterSearch;
        const qStr = new URLSearchParams(query).toString();
        const res = await api(`/inspections/templates${qStr ? '?' + qStr : ''}`).catch(() => []);
        state.setupInspectionTemplates = Array.isArray(res) ? res : [];
      } else if (state.setupInspectionSubTab === 'mandates') {
        const query = {};
        if (state.setupMandateFilterDept) query.department = state.setupMandateFilterDept;
        if (state.setupMandateFilterStatus) query.status = state.setupMandateFilterStatus;
        if (state.setupMandateSearch) query.search = state.setupMandateSearch;
        const qStr = new URLSearchParams(query).toString();
        const res = await api(`/inspections/mandates/overview${qStr ? '?' + qStr : ''}`).catch(() => null);
        state.setupInspectionMandateOverview = res;
      } else if (state.setupInspectionSubTab === 'schedules') {
        const query = {};
        if (state.setupSchedSearch) query.search = state.setupSchedSearch;
        const qStr = new URLSearchParams(query).toString();
        const res = await api(`/inspections/schedules${qStr ? '?' + qStr : ''}`).catch(() => []);
        state.setupInspectionSchedules = Array.isArray(res) ? res : [];
      }

      // Pastikan master templat selalu terisi untuk modal di seluruh subtab
      if ((!state.setupInspectionTemplates || state.setupInspectionTemplates.length === 0) && state.setupInspectionSubTab !== 'templates') {
        const tmpls = await api('/inspections/templates').catch(() => []);
        if (Array.isArray(tmpls)) state.setupInspectionTemplates = tmpls;
      }
    } catch (err) {
      console.error('Gagal memuat data setup inspeksi:', err);
    }
  }

