  function hseEventBase(kind) {
    return kind === 'p5m' ? '/p5m' : '/safetytalk';
  }

  function hseEventFilters(kind) {
    return kind === 'p5m' ? state.p5mEventFilters : state.stEventFilters;
  }

  async function loadHseEvents(kind) {
    try {
      const filters = hseEventFilters(kind);
      const q = new URLSearchParams();
      Object.entries(filters || {}).forEach(([k, v]) => { if (v) q.set(k, v); });
      const [eventsData, overview] = await Promise.all([
        api(`${hseEventBase(kind)}/events?${q.toString()}`).catch(() => []),
        api(`${hseEventBase(kind)}/mandates/overview?status=WAJIB`).catch(() => null),
      ]);
      const rows = Array.isArray(eventsData) ? eventsData : [];
      const wajib = ((overview && Array.isArray(overview.items)) ? overview.items : [])
        .filter(e => e && e.quota_status === 'WAJIB');
      if (kind === 'p5m') {
        state.p5mEvents = rows;
        state.p5mWajib = wajib;
      } else {
        state.stEvents = rows;
        state.stWajib = wajib;
      }
    } catch (err) {
      console.error('Gagal memuat list event HSE:', err);
    }
  }

