  function renderSidebar() {
    const groups = [
      { name: 'Pantau', items: ['overview', 'reports'] },
      { name: 'Risiko dan insiden', items: ['hazard', 'incident', 'ptw'] },
      { name: 'Manusia', items: ['competency', 'occ-health', 'contractor'] },
      { name: 'Lingkungan dan darurat', items: ['environment', 'emergency', 'ppe'] },
      { name: 'Kepatuhan', items: ['audit', 'documents'] },
      { name: 'Konfigurasi', items: ['setup'] },
    ];

    return `
      <div class="hse-sidebar">
        ${groups.map(grp => `
          <div class="hse-sidebar-group">${ESC(grp.name)}</div>
          ${grp.items.map(key => {
            const item = SUBPAGE_METADATA[key];
            const isActive = state.view === key ? 'is-active' : '';
            const badge = (key === 'hazard' && state.overview?.kpi?.hazardOpen)
              ? `<span class="hse-sidebar-badge">${state.overview.kpi.hazardOpen}</span>`
              : (key === 'overview' && state.overview?.actionItems?.length ? '' : '');
            return `
              <button type="button" class="hse-sidebar-item ${isActive}" data-subpage="${key}">
                <span class="hse-sidebar-label">
                  <i class="ti ${item.icon}" aria-hidden="true"></i> ${ESC(item.label)}
                </span>
                ${badge}
              </button>
            `;
          }).join('')}
        `).join('')}
      </div>
    `;
  }

