  function hseMsTriggerHtml(id, placeholder) {
    return `
      <div class="hse-ms" style="position:relative;">
        <button type="button" class="hse-form-select hse-ms-trigger" id="${id}" style="display:flex;align-items:center;justify-content:space-between;width:100%;cursor:pointer;text-align:left;">
          <span class="hse-ms-chip" data-ms-chip style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${ESC(placeholder)}</span>
          <i class="ti ti-chevron-down" style="font-size:12px;opacity:.6;margin-left:6px;"></i>
        </button>
      </div>`;
  }

  function bindHseMultiSelect(opts) {
    const { triggerId, options = [], selected = [], allNone = null, placeholder = '-- Pilih --', searchPlaceholder = 'Cari...', chipMax = 2 } = opts || {};
    const trigger = rootEl.querySelector(`#${triggerId}`);
    const host = trigger ? trigger.parentElement : null;
    if (!trigger || !host) return { getSelected: () => [], isAllNone: () => false };

    const sel = new Set((selected || []).map(v => String(v)));
    let allNoneOn = Boolean(allNone && sel.has(String(allNone.value)));
    if (allNoneOn) sel.clear();

    const panel = document.createElement('div');
    panel.className = 'hse-ms-panel';
    panel.hidden = true;
    panel.style.cssText = 'position:absolute;z-index:70;left:0;right:0;margin-top:4px;background:var(--hse-surface-2, #fff);border:1px solid var(--hse-border, rgba(0,0,0,.12));border-radius:6px;box-shadow:0 10px 28px rgba(0,0,0,.18);padding:8px;max-height:280px;display:flex;flex-direction:column;gap:6px;';
    panel.innerHTML = `
      <input type="text" class="hse-form-input hse-ms-search" placeholder="${ESC(searchPlaceholder)}" style="padding:4px 8px;font-size:11px;">
      <div style="display:flex;gap:6px;">
        <button type="button" class="hse-btn hse-ms-all" style="flex:1;padding:2px 6px;font-size:10px;">Pilih Semua</button>
        <button type="button" class="hse-btn hse-ms-none" style="flex:1;padding:2px 6px;font-size:10px;">Kosongkan</button>
      </div>
      <div class="hse-ms-list" style="overflow-y:auto;max-height:180px;display:flex;flex-direction:column;gap:2px;">
        ${allNone ? `<label class="hse-ms-row" style="display:flex;align-items:center;gap:6px;font-size:11px;padding:3px 4px;border-radius:4px;cursor:pointer;font-weight:600;"><input type="checkbox" class="hse-ms-allnone" ${allNoneOn ? 'checked' : ''} style="accent-color:var(--hse-accent, #1c5fb8);"><span>${ESC(allNone.label)}</span></label>` : ''}
        ${options.map(o => `
          <label class="hse-ms-row" data-label="${ESC(String(o.label || '').toLowerCase())}" style="display:flex;align-items:center;gap:6px;font-size:11px;padding:3px 4px;border-radius:4px;cursor:pointer;">
            <input type="checkbox" class="hse-ms-cb" value="${ESC(String(o.value))}" ${sel.has(String(o.value)) ? 'checked' : ''} style="accent-color:var(--hse-accent, #1c5fb8);">
            <span style="flex:1;">${ESC(o.label)}</span>
          </label>`).join('')}
      </div>`;
    host.appendChild(panel);

    const chip = trigger.querySelector('[data-ms-chip]');
    const labelOf = new Map(options.map(o => [String(o.value), o.label]));
    const listCbs = () => panel.querySelectorAll('.hse-ms-cb');
    const allNoneCb = () => panel.querySelector('.hse-ms-allnone');

    function updateChip() {
      if (!chip) return;
      if (allNoneOn) {
        chip.textContent = allNone.label;
        return;
      }
      const vals = [...sel];
      if (!vals.length) {
        chip.textContent = placeholder;
        return;
      }
      const names = vals.slice(0, chipMax).map(v => labelOf.get(v) || v);
      chip.textContent = vals.length > chipMax ? `${names.join(', ')} +${vals.length - chipMax}` : names.join(', ');
    }

    panel.addEventListener('change', (e) => {
      const t = e.target;
      if (!(t instanceof HTMLInputElement)) return;
      if (t.classList.contains('hse-ms-allnone')) {
        allNoneOn = t.checked;
        if (allNoneOn) {
          sel.clear();
          listCbs().forEach(cb => { cb.checked = false; });
        }
      } else if (t.classList.contains('hse-ms-cb')) {
        if (t.checked) sel.add(t.value); else sel.delete(t.value);
        if (sel.size && allNoneCb()) {
          allNoneOn = false;
          allNoneCb().checked = false;
        }
      }
      updateChip();
    });

    panel.querySelector('.hse-ms-all').addEventListener('click', () => {
      const q = (panel.querySelector('.hse-ms-search')?.value || '').trim().toLowerCase();
      listCbs().forEach(cb => {
        const row = cb.closest('.hse-ms-row');
        const lb = row ? row.dataset.label : null;
        if (q && lb && !lb.includes(q)) return;
        cb.checked = true;
        sel.add(cb.value);
      });
      if (allNoneCb()) {
        allNoneOn = false;
        allNoneCb().checked = false;
      }
      updateChip();
    });

    panel.querySelector('.hse-ms-none').addEventListener('click', () => {
      sel.clear();
      listCbs().forEach(cb => { cb.checked = false; });
      if (allNoneCb()) {
        allNoneOn = false;
        allNoneCb().checked = false;
      }
      updateChip();
    });

    panel.querySelector('.hse-ms-search').addEventListener('input', (e) => {
      const q = (e.target.value || '').trim().toLowerCase();
      panel.querySelectorAll('.hse-ms-row').forEach(row => {
        const lb = row.dataset.label;
        row.style.display = (!q || !lb || lb.includes(q)) ? '' : 'none';
      });
    });

    trigger.addEventListener('click', (e) => {
      e.stopPropagation();
      panel.hidden = !panel.hidden;
    });

    const onDocClick = (e) => {
      if (panel.hidden) {
        document.removeEventListener('click', onDocClick);
        return;
      }
      if (!host.contains(e.target)) {
        panel.hidden = true;
        document.removeEventListener('click', onDocClick);
      }
    };
    document.addEventListener('click', onDocClick);

    updateChip();
    return {
      getSelected: () => [...sel],
      isAllNone: () => Boolean(allNoneOn)
    };
  }

  async function saveHseMandateBatch(endpoint, items, describeItem) {
    const created = [];
    for (const item of items) {
      try {
        const res = await api(endpoint, { method: 'POST', body: item });
        if (res && res.id) created.push(res.id);
      } catch (err) {
        let failedComp = 0;
        for (const id of created) {
          try {
            await api(`${endpoint}/${id}`, { method: 'DELETE' });
          } catch {
            failedComp += 1;
          }
        }
        const cleanupNote = failedComp > 0
          ? ` (${failedComp} baris sebelumnya mungkin masih tersimpan — periksa matriks)`
          : '';
        throw new Error(`Tidak ada aturan tersimpan — konflik di ${describeItem(item)}: ${err.message}${cleanupNote}`);
      }
    }
    return created.length;
  }

  function openHseRoleMandateModalShared(tabKey) {
    const cfg = HSE_MANDATE_TABS[tabKey];
    if (!cfg) return;
    const departments = state.masters?.departments || [];
    const positions = state.masters?.positions || [];
    const templates = cfg.hasTemplate ? (state.setupInspectionTemplates || []) : [];
    const p = cfg.idp;

    state.activeModal = `
      <div class="hse-modal-header">
        <strong style="font-size:14px;">
          <i class="ti ti-users"></i> ${cfg.titleRole}
        </strong>
        <button type="button" class="hse-btn" id="btnHseCloseModal">✕</button>
      </div>
      <form id="${cfg.formId}">
        <div class="hse-form-group">
          <label class="hse-form-label">Departemen (boleh pilih lebih dari satu)</label>
          ${hseMsTriggerHtml(`${p}Dept`, '-- Semua Departemen --')}
          <small style="color:var(--hse-text-muted);font-size:10px;">Centang satu/lebih departemen; tanpa centang = aturan berlaku di semua departemen.</small>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Jabatan * (boleh pilih lebih dari satu)</label>
          ${hseMsTriggerHtml(`${p}Position`, '-- Pilih Jabatan --')}
        </div>

        ${cfg.hasTemplate ? `
        <div class="hse-form-group">
          <label class="hse-form-label">Jenis Inspeksi</label>
          <select class="hse-form-select" id="${p}Template">
            <option value="">Semua Jenis Inspeksi</option>
            ${templates.map(t => `<option value="${t.root_id || t.id}">${ESC(t.name)} (${ESC(t.code)})</option>`).join('')}
          </select>
        </div>` : ''}

        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;" class="hse-form-group">
          <div>
            <label class="hse-form-label">Siklus Evaluasi *</label>
            <select class="hse-form-select" id="${p}Cycle" required>
              <option value="MONTHLY" selected>Bulanan (Monthly)</option>
              <option value="WEEKLY">Mingguan (Weekly)</option>
              <option value="DAILY">Harian (Daily)</option>
            </select>
          </div>
          <div>
            <label class="hse-form-label">Target Kuota *</label>
            <input type="number" min="0" class="hse-form-input" id="${p}Quota" value="${cfg.quotaDefault}" required>
            <small style="color:var(--hse-text-muted);font-size:10px;">Isi 0 untuk Bebas Kewajiban. Berlaku untuk seluruh kombinasi terpilih.</small>
          </div>
        </div>

        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;" class="hse-form-group">
          <div>
            <label class="hse-form-label">Berlaku Dari *</label>
            <input type="date" class="hse-form-input" id="${p}From" value="${new Date().toISOString().slice(0, 10)}" required>
          </div>
          <div>
            <label class="hse-form-label">Berlaku Sampai (Opsional)</label>
            <input type="date" class="hse-form-input" id="${p}To" placeholder="Kosong = Tanpa Batas">
          </div>
        </div>

        <div class="hse-form-group">
          <label style="font-size:11px;display:flex;align-items:center;gap:6px;cursor:pointer;">
            <input type="checkbox" id="${p}Proration">
            <span>Prorata otomatis berdasarkan kehadiran (absensi / roster rotasi)</span>
          </label>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Dasar Acuan / SOP</label>
          <input type="text" class="hse-form-input" id="${p}Notes" placeholder="${ESC(cfg.notesPlaceholder)}">
        </div>

        <div class="hse-form-group" style="background:var(--hse-surface-1);padding:8px 10px;border-radius:6px;">
          <label style="font-size:11px;display:flex;align-items:center;gap:6px;cursor:pointer;">
            <input type="checkbox" id="${p}CloseOverlap" checked>
            <span>Tutup otomatis aturan aktif sebelumnya jika tanggal bertabrakan (berlaku per kombinasi)</span>
          </label>
        </div>

        <div id="${p}BatchErr" style="display:none;color:#e5484d;font-size:11px;white-space:pre-wrap;margin-top:8px;"></div>

        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px;">
          <button type="button" class="hse-btn" id="btnHseCancelModal">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary">
            <i class="ti ti-check"></i> Simpan Target Jabatan
          </button>
        </div>
      </form>
    `;
    render();

    const posMs = bindHseMultiSelect({
      triggerId: `${p}Position`,
      options: positions.map(x => ({ value: x.id, label: x.name })),
      placeholder: '-- Pilih Jabatan --',
      searchPlaceholder: 'Cari jabatan...'
    });
    const deptMs = bindHseMultiSelect({
      triggerId: `${p}Dept`,
      options: departments.map(x => ({ value: x.id, label: x.name })),
      placeholder: '-- Semua Departemen --',
      searchPlaceholder: 'Cari departemen...',
      allNone: { value: '__ALL__', label: 'Semua Departemen' }
    });

    const form = rootEl.querySelector(`#${cfg.formId}`);
    if (!form) return;
    const errEl = rootEl.querySelector(`#${p}BatchErr`);

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      if (errEl) {
        errEl.style.display = 'none';
        errEl.textContent = '';
      }

      const posIds = posMs.getSelected();
      if (!posIds.length) {
        if (errEl) {
          errEl.textContent = 'Pilih minimal satu jabatan.';
          errEl.style.display = 'block';
        }
        return;
      }
      const deptIds = deptMs.isAllNone() ? [] : deptMs.getSelected();
      const deptValues = deptIds.length ? deptIds : [null];
      const combos = posIds.flatMap(pid => deptValues.map(did => ({ position_id: pid, department_id: did })));

      if (combos.length > 1) {
        const posNames = posIds.map(id => positions.find(x => x.id === id)?.name || id);
        const deptNames = deptIds.length
          ? deptIds.map(id => departments.find(x => x.id === id)?.name || id)
          : ['Semua Departemen'];
        const ok = window.confirm(
          `Simpan ${combos.length} aturan sekaligus?\n\n` +
          `Jabatan: ${posNames.join(', ')}\n` +
          `Departemen: ${deptNames.join(', ')}\n\n` +
          `Siklus, kuota, tanggal, prorata, dan opsi lainnya berlaku untuk seluruh kombinasi.`
        );
        if (!ok) return;
      }

      const shared = {
        template_root_id: cfg.hasTemplate ? (rootEl.querySelector(`#${p}Template`)?.value || null) : null,
        cycle: rootEl.querySelector(`#${p}Cycle`)?.value || 'MONTHLY',
        target_quota: Number(rootEl.querySelector(`#${p}Quota`)?.value || 0),
        effective_from: rootEl.querySelector(`#${p}From`)?.value,
        effective_to: rootEl.querySelector(`#${p}To`)?.value || null,
        proration_mode: rootEl.querySelector(`#${p}Proration`)?.checked ? 'BY_ATTENDANCE' : 'NONE',
        notes: rootEl.querySelector(`#${p}Notes`)?.value.trim() || null,
        close_overlapping: rootEl.querySelector(`#${p}CloseOverlap`)?.checked
      };
      const posName = (id) => positions.find(x => x.id === id)?.name || id;
      const deptName = (id) => (id ? (departments.find(x => x.id === id)?.name || id) : 'Semua Departemen');
      const items = combos.map(combo => ({
        target_type: 'BY_ROLE',
        position_id: combo.position_id,
        department_id: combo.department_id,
        ...shared
      }));

      try {
        await runHseActionFeedback(form, async () => {
          await saveHseMandateBatch(cfg.endpoint, items, (item) => `${posName(item.position_id)} @ ${deptName(item.department_id)}`);
          state.activeModal = null;
          await cfg.reload();
          render();
        }, {
          loadingText: `Menyimpan ${combos.length} aturan...`,
          successText: combos.length > 1 ? `${combos.length} aturan tersimpan` : 'Target tersimpan'
        });
      } catch (err) {
        if (errEl) {
          errEl.textContent = err?.message || 'Gagal menyimpan aturan.';
          errEl.style.display = 'block';
        }
      }
    });
  }

