  function bindCreateIncidentEvents() {
    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const chkPerson = document.getElementById('chkIncHasPerson');
    const wrapPerson = document.getElementById('wrapIncPersonFields');
    if (chkPerson && wrapPerson) {
      chkPerson.addEventListener('change', () => {
        wrapPerson.style.display = chkPerson.checked ? 'block' : 'none';
      });
    }

    const chkAsset = document.getElementById('chkIncHasAsset');
    const wrapAsset = document.getElementById('wrapIncAssetFields');
    if (chkAsset && wrapAsset) {
      chkAsset.addEventListener('change', () => {
        wrapAsset.style.display = chkAsset.checked ? 'block' : 'none';
      });
    }

    const form = document.getElementById('formHseCreateIncident');
    const submitBtn = document.getElementById('btnSubmitHseIncident');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseIncFormError');
        if (errEl) errEl.hidden = true;

        const persons = [];
        if (chkPerson && chkPerson.checked && document.getElementById('inIncPersonName')?.value.trim()) {
          persons.push({
            person_name: document.getElementById('inIncPersonName').value.trim(),
            role_in_incident: document.getElementById('inIncPersonRole')?.value || 'INJURED',
            injury_type: document.getElementById('inIncPersonInjury')?.value.trim() || null,
            body_part: document.getElementById('inIncPersonPart')?.value.trim() || null,
            treatment: document.getElementById('inIncPersonTreatment')?.value || 'NONE',
            lost_days: parseInt(document.getElementById('inIncPersonLostDays')?.value, 10) || 0,
          });
        }

        const assets = [];
        if (chkAsset && chkAsset.checked && document.getElementById('inIncAssetCode')?.value.trim()) {
          assets.push({
            asset_code: document.getElementById('inIncAssetCode').value.trim(),
            asset_name: document.getElementById('inIncAssetName')?.value.trim() || null,
            damage_description: document.getElementById('inIncAssetDamage')?.value.trim() || null,
            repair_cost: Number(document.getElementById('inIncAssetCost')?.value) || 0,
          });
        }

        const payload = {
          incident_type: document.getElementById('inIncType')?.value,
          occurred_at: document.getElementById('inIncOccurredAt')?.value,
          location_id: document.getElementById('inIncLocation')?.value || null,
          department_name: document.getElementById('inIncDept')?.value.trim() || null,
          description: document.getElementById('inIncDescription')?.value.trim(),
          actual_severity: document.getElementById('inIncActualSeverity')?.value || 'MINOR',
          potential_severity: document.getElementById('inIncPotentialSeverity')?.value || 'MODERATE',
          estimated_loss: Number(document.getElementById('inIncLoss')?.value) || 0,
          external_report_required: Boolean(document.getElementById('inIncExternalReport')?.checked),
          persons,
          assets,
        };

        const work = async () => {
          await api('/incidents', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

  async function openInputManhoursModal() {
    const currentMonth = new Date().toISOString().slice(0, 7);
    let contractors = [];
    try {
      const rows = await api('/contractors');
      contractors = (Array.isArray(rows) ? rows : []).filter(c => c.company_name);
    } catch (err) {
      contractors = [];
    }

    state.activeModal = `
      <div class="hse-modal-header">
        <strong style="font-size:14px;"><i class="ti ti-clock" aria-hidden="true"></i> Input Jam Kerja Kontraktor</strong>
        <button type="button" class="hse-btn" id="btnHseCloseModal">✕</button>
      </div>
      <div class="hse-wh-preview" style="margin-bottom:10px;"><i class="ti ti-info-circle"></i><span>Jam kerja karyawan internal dihitung otomatis dari Setup master → Jam kerja karyawan. Form ini hanya untuk kontraktor yang terdaftar di HSE → Kontraktor.</span></div>
      ${contractors.length === 0 ? `
        <div class="hse-wh-notice"><div class="hse-wh-notice-t"><i class="ti ti-alert-triangle"></i><span>Belum ada kontraktor terdaftar. Tambahkan kontraktor di HSE → Kontraktor terlebih dahulu.</span></div></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;"><button type="button" class="hse-btn" id="btnHseCloseModal2">Tutup</button></div>
      ` : `
      <form id="formHseSaveManhours">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;" class="hse-form-group">
          <div>
            <label class="hse-form-label">Periode Bulan *</label>
            <input type="month" class="hse-form-input" id="inMhMonth" value="${currentMonth}" required>
          </div>
          <div>
            <label class="hse-form-label">Total Jam Kerja (Man-hours) *</label>
            <input type="number" class="hse-form-input" id="inMhHours" placeholder="Mis. 12000" min="0" step="0.5" required>
          </div>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;" class="hse-form-group">
          <div>
            <label class="hse-form-label">Kontraktor *</label>
            <select class="hse-form-select" id="inMhCompany" required>
              ${contractors.map(c => `<option value="${ESC(c.company_name)}">${ESC(c.company_name)}${c.is_active === false ? ' (nonaktif)' : ''}</option>`).join('')}
            </select>
          </div>
          <div>
            <label class="hse-form-label">Departemen / Lingkup</label>
            <input type="text" class="hse-form-input" id="inMhDept" value="Semua departemen" placeholder="Departemen">
          </div>
        </div>
        <div id="hseManhoursFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitHseManhours">Simpan Jam Kerja</button>
        </div>
      </form>`}
    `;
    render();
    bindManhoursEvents();
  }

  function bindManhoursEvents() {
    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const form = document.getElementById('formHseSaveManhours');
    const submitBtn = document.getElementById('btnSubmitHseManhours');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseManhoursFormError');
        if (errEl) errEl.hidden = true;

        const monthVal = document.getElementById('inMhMonth')?.value || '';
        const payload = {
          period_month: monthVal.length === 7 ? `${monthVal}-01` : monthVal,
          hours: Number(document.getElementById('inMhHours')?.value),
          company_name: document.getElementById('inMhCompany')?.value || '',
          department_name: document.getElementById('inMhDept')?.value.trim() || 'Semua departemen',
        };

        const work = async () => {
          await api('/manhours', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadData();
          if (state.view === 'reports') await loadSafetyReports();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

  // -------------------------------------------------------------
  // EVENT P5M & SAFETY TALK (tab Hazard dan Inspeksi): MODALS
  // -------------------------------------------------------------

  async function openHseEventDetailModal(kind, id) {
    if (!id) return;
    let detail = null;
    try {
      detail = await api(`${hseEventBase(kind)}/events/${id}`);
    } catch (err) {
      window.alert('Gagal memuat detail event: ' + err.message);
      return;
    }
    const label = kind === 'p5m' ? 'P5M' : 'Safety Talk';
    const topics = Array.isArray(detail.topics) ? detail.topics : [];
    const attendees = Array.isArray(detail.attendees) ? detail.attendees : [];
    const ledByNames = Array.isArray(detail.led_by_names) ? detail.led_by_names.filter(Boolean) : [];
    const photos = Array.isArray(detail.photos) ? detail.photos.filter(Boolean) : [];

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">Detail Sesi ${label} ${detail.event_no ? `#${ESC(detail.event_no)}` : ''}</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-top:12px;">
        <div class="hse-form-group" style="margin-bottom:0;">
          <label class="hse-form-label">Tanggal &amp; Shift</label>
          <div style="font-size:13px;font-weight:600;">${ESC(String(detail.event_date).slice(0, 10))}</div>
          <span class="hse-badge hse-badge--accent" style="margin-top:4px;">${ESC(detail.shift_name || '-')}</span>
        </div>
        <div class="hse-form-group" style="margin-bottom:0;">
          <label class="hse-form-label">Area / Lokasi</label>
          <div style="font-size:13px;font-weight:600;">${ESC(detail.location_name || '-')}</div>
        </div>
        <div class="hse-form-group" style="margin-bottom:0;">
          <label class="hse-form-label">Pemateri / Pemimpin</label>
          <div>${ledByNames.length ? ledByNames.map(n => `<span class="hse-badge hse-badge--medium" style="margin:2px 4px 2px 0;">${ESC(n)}</span>`).join('') : '<span style="color:var(--hse-text-muted);">-</span>'}</div>
        </div>
        <div class="hse-form-group" style="margin-bottom:0;grid-column:1 / -1;">
          <label class="hse-form-label">Topik</label>
          <div>${topics.length ? topics.map(t => `<span class="hse-badge hse-badge--new" style="margin:2px 4px 2px 0;">${ESC(t)}</span>`).join('') : '<span style="color:var(--hse-text-muted);">-</span>'}</div>
        </div>
        <div class="hse-form-group" style="margin-bottom:0;grid-column:1 / -1;">
          <label class="hse-form-label">Peserta (${attendees.length} orang)</label>
          <div style="max-height:180px;overflow:auto;border:1px solid var(--hse-border);border-radius:6px;">
            ${attendees.length ? `
              <table class="hse-table">
                <thead><tr><th>Nama</th><th>NIK</th><th>Jabatan</th></tr></thead>
                <tbody>
                  ${attendees.map(a => `
                    <tr>
                      <td>${ESC(a.nama || '-')}</td>
                      <td>${ESC(a.employee_no || '-')}</td>
                      <td>${ESC(a.jabatan || '-')}</td>
                    </tr>
                  `).join('')}
                </tbody>
              </table>
            ` : '<div style="padding:12px;color:var(--hse-text-muted);font-size:11px;">Tidak ada peserta tercatat.</div>'}
          </div>
        </div>
        <div class="hse-form-group" style="margin-bottom:0;grid-column:1 / -1;">
          <label class="hse-form-label">Foto (${photos.length})</label>
          ${photos.length ? `
            ${photoThumbsHtml(`ev:${detail.id}`, photos, `${detail.event_no || 'Kegiatan'} · foto sesi`)}
          ` : '<div style="color:var(--hse-text-muted);font-size:11px;">Tidak ada foto lampiran.</div>'}
        </div>
      </div>
      <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px;">
        <button type="button" class="hse-btn" id="btnHseCloseModal2">Tutup</button>
        <button type="button" class="hse-btn" id="btnHseEvDetailEdit" style="color:#2563eb;border-color:rgba(37,99,235,0.35);">✏️ Edit</button>
        <button type="button" class="hse-btn" id="btnHseEvDetailDelete" style="color:#dc2626;border-color:rgba(220,38,38,0.35);">🗑️ Hapus</button>
      </div>
    `;
    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });
    document.getElementById('btnHseEvDetailEdit')?.addEventListener('click', () => {
      openHseEventFormModal(kind, id);
    });
    document.getElementById('btnHseEvDetailDelete')?.addEventListener('click', (e) => {
      deleteHseEventAction(e.currentTarget, kind, id, detail.event_no || '');
    });
  }

  async function openHseEventFormModal(kind, id = null) {
    const isEdit = Boolean(id);
    const label = kind === 'p5m' ? 'P5M' : 'Safety Talk';
    const wajib = kind === 'p5m' ? state.p5mWajib : state.stWajib;

    if (!wajib.length) {
      state.activeModal = `
        <div class="hse-modal-header">
          <div class="hse-modal-title">Pencatatan Sesi ${label}</div>
          <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
        </div>
        <div style="padding:14px 0;font-size:12px;color:var(--hse-text-secondary);line-height:1.6;">
          <strong style="color:#b45309;">Tidak dapat mencatat sesi ${label}.</strong><br>
          Belum ada karyawan berstatus <strong>WAJIB</strong> untuk ${label}. Atur kewajiban karyawan terlebih dahulu di Setup Master.
        </div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:12px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Tutup</button>
          <button type="button" class="hse-btn hse-btn--primary" id="btnHseEvGoSetup">Buka Setup Master ${label}</button>
        </div>
      `;
      render();
      document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => { state.activeModal = null; render(); });
      document.getElementById('btnHseEvGoSetup')?.addEventListener('click', async () => {
        state.activeModal = null;
        state.view = 'setup';
        state.setupTab = kind === 'p5m' ? 'p5m' : 'safetytalk';
        if (kind === 'p5m') await loadSetupP5mData();
        else await loadSetupStData();
        render();
      });
      return;
    }

    let detail = null;
    if (isEdit) {
      try {
        detail = await api(`${hseEventBase(kind)}/events/${id}`);
      } catch (err) {
        window.alert('Gagal memuat data event: ' + err.message);
        return;
      }
    }

    const shifts = state.masters.shifts || [];
    const employees = state.masters.employees || [];
    const selected = new Set(
      (detail && Array.isArray(detail.attendees) ? detail.attendees : [])
        .map(a => (a.employee_id ? String(a.employee_id) : null))
        .filter(Boolean)
    );
    const defaultDate = (detail && detail.event_date)
      ? String(detail.event_date).slice(0, 10)
      : new Date().toISOString().slice(0, 10);
    const defaultShift = detail ? String(detail.shift_id || '') : (shifts[0] ? String(shifts[0].id) : '');

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">${isEdit ? 'Edit' : 'Catat'} Sesi ${label}${detail && detail.event_no ? ` — #${ESC(detail.event_no)}` : ''}</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseSaveHseEvent" style="margin-top:12px;">
        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tanggal Pelaksanaan *</label>
            <input type="date" class="hse-form-input" id="inEvDate" value="${ESC(defaultDate)}" required>
          </div>
          <div>
            <label class="hse-form-label">Shift *</label>
            <select class="hse-form-select" id="inEvShift" required>
              <option value="">Pilih Shift...</option>
              ${shifts.map(s => `<option value="${ESC(s.id)}" ${String(s.id) === defaultShift ? 'selected' : ''}>${ESC(s.nama_shift)}</option>`).join('')}
            </select>
          </div>
        </div>
        <div class="hse-form-group">
          <label class="hse-form-label">Area / Lokasi *</label>
          <select class="hse-form-select" id="inEvLocation" required>
            ${renderLocationHierarchyOptions(detail ? String(detail.location_id || '') : '', 'Pilih Area / Sub-Area...')}
          </select>
        </div>
        <div class="hse-form-group">
          <label class="hse-form-label">Topik * <span style="font-weight:400;color:var(--hse-text-muted);">(satu topik per baris)</span></label>
          <textarea class="hse-form-textarea" id="inEvTopics" rows="2" placeholder="Mis.&#10;APD wajib di area produksi&#10;Semua orang adalah peninjau">${ESC((detail && Array.isArray(detail.topics) ? detail.topics : []).join('\n'))}</textarea>
        </div>
        <div class="hse-form-group">
          <label class="hse-form-label">Peserta Wajib * <span style="font-weight:400;color:var(--hse-text-muted);">(<span id="inEvPesertaCount">${selected.size}</span> terpilih — hanya karyawan berstatus WAJIB)</span></label>
          <input type="text" class="hse-form-input" id="inEvPesertaSearch" placeholder="Cari nama / NIK / jabatan..." style="margin-bottom:6px;">
          <div id="inEvPesertaList" style="max-height:190px;overflow:auto;border:1px solid var(--hse-border);border-radius:6px;"></div>
        </div>
        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Pemateri / Pemimpin Sesi</label>
            <select class="hse-form-select" id="inEvLedBy">
              <option value="">— Pilih pemateri (opsional) —</option>
              ${employees.map(e => {
                const ledIds = detail && Array.isArray(detail.led_by_ids) ? detail.led_by_ids.map(String) : [];
                return `<option value="${ESC(e.id)}" ${ledIds.includes(String(e.id)) ? 'selected' : ''}>${ESC(e.nama)}${e.jabatan ? ` — ${ESC(e.jabatan)}` : ''}</option>`;
              }).join('')}
            </select>
          </div>
          <div>
            <label class="hse-form-label">Foto Lampiran <span style="font-weight:400;color:var(--hse-text-muted);">(Maks. 3, otomatis dikompresi)</span></label>
            <input type="file" class="hse-form-input" id="inEvPhotos" accept="image/*" multiple>
            <div id="inEvPhotoPreviewList"></div>
          </div>
        </div>
        <div id="hseEvFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitHseEvent">${isEdit ? 'Simpan Perubahan' : 'Simpan Sesi'}</button>
        </div>
      </form>
    `;
    render();

    const photoCtrl = bindPhotoAttachmentController('inEvPhotos', 'inEvPhotoPreviewList', (detail && Array.isArray(detail.photos)) ? detail.photos : []);

    const pesertaSearch = document.getElementById('inEvPesertaSearch');
    const pesertaListEl = document.getElementById('inEvPesertaList');
    const pesertaCountEl = document.getElementById('inEvPesertaCount');

    const updatePesertaCount = () => {
      if (pesertaCountEl) pesertaCountEl.textContent = String(selected.size);
    };

    const renderPesertaList = () => {
      if (!pesertaListEl) return;
      const q = ((pesertaSearch && pesertaSearch.value) || '').toLowerCase().trim();
      const rows = wajib.filter(e => !q
        || String(e.nama || '').toLowerCase().includes(q)
        || String(e.employee_id || '').toLowerCase().includes(q)
        || String(e.jabatan || '').toLowerCase().includes(q));
      if (!rows.length) {
        pesertaListEl.innerHTML = `<div style="padding:10px;font-size:11px;color:var(--hse-text-muted);">Tidak ada karyawan WAJIB yang cocok.</div>`;
        return;
      }
      pesertaListEl.innerHTML = rows.map(e => `
        <label style="display:flex;gap:8px;align-items:flex-start;padding:5px 8px;border-bottom:1px solid var(--hse-border);cursor:pointer;font-size:11.5px;">
          <input type="checkbox" data-ev-peserta="${ESC(e.id)}" ${selected.has(String(e.id)) ? 'checked' : ''} style="margin-top:2px;">
          <span style="flex:1;min-width:0;">
            <strong>${ESC(e.nama)}</strong>
            <span style="color:var(--hse-text-muted);"> — ${ESC(e.jabatan || e.departemen || '-')}</span>
            <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(e.employee_id || '')}</div>
          </span>
        </label>
      `).join('');
      pesertaListEl.querySelectorAll('[data-ev-peserta]').forEach(cb => {
        cb.addEventListener('change', () => {
          const empKey = String(cb.dataset.evPeserta);
          if (cb.checked) selected.add(empKey);
          else selected.delete(empKey);
          updatePesertaCount();
        });
      });
    };
    renderPesertaList();
    if (pesertaSearch) pesertaSearch.addEventListener('input', renderPesertaList);

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const form = document.getElementById('formHseSaveHseEvent');
    const submitBtn = document.getElementById('btnSubmitHseEvent');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseEvFormError');
        const showErr = msg => {
          if (errEl) { errEl.textContent = msg; errEl.hidden = false; }
        };
        if (errEl) errEl.hidden = true;

        const topics = (document.getElementById('inEvTopics')?.value || '')
          .split('\n').map(t => t.trim()).filter(Boolean);
        const participant_ids = Array.from(selected);
        const ledBy = document.getElementById('inEvLedBy')?.value || '';
        const payload = {
          event_date: document.getElementById('inEvDate')?.value || '',
          shift_id: document.getElementById('inEvShift')?.value || '',
          location_id: document.getElementById('inEvLocation')?.value || '',
          topics,
          participant_ids,
          led_by_ids: ledBy ? [ledBy] : [],
          photos: photoCtrl.getPhotos(),
        };

        if (!payload.event_date) return showErr('Tanggal wajib diisi');
        if (!payload.shift_id) return showErr('Shift wajib dipilih');
        if (!payload.location_id) return showErr('Area / Lokasi wajib dipilih');
        if (!topics.length) return showErr('Minimal 1 topik wajib diisi (satu topik per baris)');
        if (!participant_ids.length) return showErr('Minimal 1 peserta wajib dipilih');

        const work = async () => {
          await api(`${hseEventBase(kind)}/events${isEdit ? '/' + id : ''}`, {
            method: isEdit ? 'PUT' : 'POST',
            body: payload,
          });
          state.activeModal = null;
          await loadHseEvents(kind);
          render();
        };

        await runHseActionFeedback(submitBtn, work).catch(err => {
          showErr(err.message);
        });
      });
    }
  }

  function openHseEventMergeModal(kind, targetId) {
    const events = kind === 'p5m' ? state.p5mEvents : state.stEvents;
    const label = kind === 'p5m' ? 'P5M' : 'Safety Talk';
    const target = events.find(e => String(e.id) === String(targetId));
    if (!target) return;

    const candidates = events.filter(e =>
      String(e.id) !== String(targetId)
      && String(e.location_id) === String(target.location_id)
      && String(e.event_date) === String(target.event_date)
      && String(e.shift_id) === String(target.shift_id)
    );
    if (!candidates.length) {
      window.alert('Tidak ada data lain dengan Area, Tanggal, dan Shift yang sama untuk digabungkan.');
      return;
    }

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">Gabungkan Duplikat Sesi ${label}</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <div style="font-size:11.5px;color:var(--hse-text-secondary);line-height:1.6;margin-top:10px;">
        Sistem mendeteksi <strong>${candidates.length + 1} sesi ${label}</strong> dengan <strong>Area, Tanggal, dan Shift sama</strong>:
        <div style="background:var(--hse-surface-1);border:1px solid var(--hse-border);border-radius:6px;padding:8px 10px;margin-top:6px;">
          <strong>#${ESC(target.event_no || '-')}</strong> — ${ESC(String(target.event_date).slice(0, 10))} · ${ESC(target.location_name || '-')} (utama)
        </div>
      </div>
      <form id="formHseMergeEvent" style="margin-top:10px;">
        <label class="hse-form-label">Pilih data yang digabungkan ke sesi utama:</label>
        <div style="max-height:200px;overflow:auto;border:1px solid var(--hse-border);border-radius:6px;">
          ${candidates.map(c => `
            <label style="display:flex;gap:8px;align-items:flex-start;padding:7px 10px;border-bottom:1px solid var(--hse-border);cursor:pointer;font-size:11.5px;">
              <input type="checkbox" data-ev-merge-src="${ESC(c.id)}" checked style="margin-top:2px;">
              <span style="flex:1;min-width:0;">
                <strong>#${ESC(c.event_no || '-')}</strong>
                <span style="color:var(--hse-text-muted);"> — ${(Array.isArray(c.attendee_names) ? c.attendee_names.length : Number(c.attendee_count) || 0)} peserta · topik: ${ESC((Array.isArray(c.topics) ? c.topics : []).join(', ') || '-')}</span>
              </span>
            </label>
          `).join('')}
        </div>
        <div style="margin-top:8px;font-size:11px;color:#059669;">
          ✓ Peserta, topik, foto, dan pemateri digabung (tanpa duplikat) ke sesi utama; data sumber disembunyikan dari daftar dan ditandai <strong>Tergabung</strong> untuk catatan administrasi.
        </div>
        <div id="hseMergeFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitHseEventMerge">🔗 Gabungkan</button>
        </div>
      </form>
    `;
    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const form = document.getElementById('formHseMergeEvent');
    const submitBtn = document.getElementById('btnSubmitHseEventMerge');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseMergeFormError');
        const showErr = msg => {
          if (errEl) { errEl.textContent = msg; errEl.hidden = false; }
        };
        if (errEl) errEl.hidden = true;

        const source_ids = Array.from(document.querySelectorAll('[data-ev-merge-src]'))
          .filter(cb => cb.checked)
          .map(cb => cb.dataset.evMergeSrc);
        if (!source_ids.length) return showErr('Pilih minimal 1 data untuk digabungkan');

        const work = async () => {
          await api(`${hseEventBase(kind)}/events/${targetId}/merge`, {
            method: 'POST',
            body: { source_ids },
          });
          state.activeModal = null;
          await loadHseEvents(kind);
          render();
        };

        await runHseActionFeedback(submitBtn, work).catch(err => {
          showErr(err.message);
        });
      });
    }
  }

  async function deleteHseEventAction(btnEl, kind, id, eventNo = '') {
    if (!id) return;
    const label = kind === 'p5m' ? 'P5M' : 'Safety Talk';
    const tag = eventNo ? `#${eventNo}` : id;
    const confirmed = window.confirm(
      `Hapus permanen sesi ${label} ${tag}?\n\nSeluruh peserta, topik, foto lampiran, serta data duplikat yang digabung ke sesi ini akan terhapus permanen dari sistem.`
    );
    if (!confirmed) return;

    const work = async () => {
      await api(`${hseEventBase(kind)}/events/${id}`, { method: 'DELETE' });
      state.activeModal = null;
      await loadHseEvents(kind);
      render();
    };

    if (btnEl && global.OMOSActionFeedback?.run) {
      await global.OMOSActionFeedback.run(btnEl, work).catch(err => {
        window.alert('Gagal menghapus sesi: ' + err.message);
      });
    } else {
      try {
        await work();
      } catch (err) {
        window.alert('Gagal menghapus sesi: ' + err.message);
      }
    }
  }

  // -------------------------------------------------------------
  // FASE 3: KOMPETENSI (LISENSI/SIMPER, MATRIKS, INDUKSI, P5M)
