  function openCreateInductionModal() {
    const employees = state.masters.employees || [];

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">Catat Induksi Keselamatan Baru</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseSaveInduction" style="margin-top:12px;">
        <div class="hse-form-group">
          <label class="hse-form-label">Tipe Peserta *</label>
          <select class="hse-form-select" id="inIndType" required>
            <option value="EMPLOYEE">Karyawan Internal</option>
            <option value="CONTRACTOR">Kontraktor / Rekanan</option>
            <option value="VISITOR">Tamu / Visitor Tambang</option>
          </select>
        </div>
        <div id="wrapIndEmployee" class="hse-form-group">
          <label class="hse-form-label">Pilih Karyawan</label>
          <select class="hse-form-select" id="inIndEmpId">
            <option value="">Pilih Karyawan</option>
            ${employees.map(e => `
              <option value="${e.id}">${ESC(e.nama)} (${ESC(e.jabatan || 'Karyawan')})</option>
            `).join('')}
          </select>
        </div>
        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Nama Lengkap Peserta *</label>
            <input type="text" class="hse-form-input" id="inIndName" placeholder="Nama Peserta" required>
          </div>
          <div>
            <label class="hse-form-label">Perusahaan / Instansi</label>
            <input type="text" class="hse-form-input" id="inIndCompany" placeholder="Mis. PT Pamapersada / Dinas ESDM">
          </div>
        </div>
        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">No. KTP / Paspor / SIM</label>
            <input type="text" class="hse-form-input" id="inIndIdNo" placeholder="No. Identitas">
          </div>
          <div>
            <label class="hse-form-label">Tanggal Induksi *</label>
            <input type="date" class="hse-form-input" id="inIndDate" value="${new Date().toISOString().slice(0, 10)}" required>
          </div>
        </div>
        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Nilai Ujian / Evaluasi (0-100)</label>
            <input type="number" class="hse-form-input" id="inIndScore" min="0" max="100" value="100">
          </div>
          <div>
            <label class="hse-form-label">Hasil Induksi *</label>
            <select class="hse-form-select" id="inIndResult" required>
              <option value="PASSED" selected>LULUS (Passed)</option>
              <option value="FAILED">TIDAK LULUS (Failed)</option>
            </select>
          </div>
        </div>
        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Berlaku Sampai</label>
            <input type="date" class="hse-form-input" id="inIndValidUntil">
          </div>
          <div>
            <label class="hse-form-label">Pembawa Materi (Inductor)</label>
            <input type="text" class="hse-form-input" id="inIndInductor" placeholder="Nama HSE Trainer">
          </div>
        </div>
        <div class="hse-form-group">
          <label class="hse-form-label">Catatan Tambahan</label>
          <textarea class="hse-form-textarea" id="inIndNotes" placeholder="Catatan brief keselamatan..."></textarea>
        </div>
        <div id="hseIndFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitHseInduction">Simpan Induksi</button>
        </div>
      </form>
    `;
    render();

    const tSelect = document.getElementById('inIndType');
    const wrapEmp = document.getElementById('wrapIndEmployee');
    const nameInp = document.getElementById('inIndName');
    const empSelect = document.getElementById('inIndEmpId');

    if (tSelect && wrapEmp) {
      tSelect.addEventListener('change', () => {
        wrapEmp.style.display = tSelect.value === 'EMPLOYEE' ? 'block' : 'none';
      });
    }
    if (empSelect && nameInp) {
      empSelect.addEventListener('change', () => {
        const selected = employees.find(e => e.id === empSelect.value);
        if (selected) nameInp.value = selected.nama;
      });
    }

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const form = document.getElementById('formHseSaveInduction');
    const submitBtn = document.getElementById('btnSubmitHseInduction');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseIndFormError');
        if (errEl) errEl.hidden = true;

        const pType = document.getElementById('inIndType')?.value;
        const payload = {
          person_type: pType,
          employee_id: pType === 'EMPLOYEE' ? (document.getElementById('inIndEmpId')?.value || null) : null,
          person_name: document.getElementById('inIndName')?.value.trim(),
          company_name: document.getElementById('inIndCompany')?.value.trim() || null,
          id_no: document.getElementById('inIndIdNo')?.value.trim() || null,
          induction_date: document.getElementById('inIndDate')?.value,
          test_score: document.getElementById('inIndScore')?.value ? Number(document.getElementById('inIndScore')?.value) : null,
          result: document.getElementById('inIndResult')?.value || 'PASSED',
          valid_until: document.getElementById('inIndValidUntil')?.value || null,
          inductor_name: document.getElementById('inIndInductor')?.value.trim() || null,
          notes: document.getElementById('inIndNotes')?.value.trim() || null,
        };

        const work = async () => {
          await api('/competency/inductions', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadCompetencyData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

  // -------------------------------------------------------------
  // FASE 4: INSPEKSI KESELAMATAN (INSPECTION) VIEW & MODALS
  // -------------------------------------------------------------

  function renderInspectionTab() {
    const viewMode = state.inspectionViewMode || 'list';
    const dueTasks = (state.inspectionDueSchedules || []).filter(s => s.due_status === 'TODAY' || s.due_status === 'OVERDUE');

    return `
      <!-- Toolbar Header & Segmented Subnav -->
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;">
        <div class="hse-segmented-control" style="max-width:540px;">
          <button type="button" class="hse-segmented-btn ${viewMode === 'list' ? 'is-active' : ''}" data-insp-view="list">
            <i class="ti ti-history"></i> Riwayat Pelaksanaan
          </button>
          <button type="button" class="hse-segmented-btn ${viewMode === 'tasks' ? 'is-active' : ''}" data-insp-view="tasks">
            <i class="ti ti-calendar-due"></i> Tugas Terjadwal ${dueTasks.length > 0 ? `<span class="hse-badge hse-badge--warning" style="font-size:9px;padding:1px 5px;margin-left:4px;">${dueTasks.length}</span>` : ''}
          </button>
          <button type="button" class="hse-segmented-btn ${viewMode === 'compliance' ? 'is-active' : ''}" data-insp-view="compliance">
            <i class="ti ti-chart-bar"></i> Kepatuhan & Kuota
          </button>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseOpenCreateInspection">
          <i class="ti ti-plus" aria-hidden="true"></i> Lakukan Inspeksi Baru
        </button>
      </div>

      ${viewMode === 'list' ? renderInspectionHistoryList() : (
        viewMode === 'tasks' ? renderInspectionDueTasksList() : renderInspectionComplianceTab()
      )}
    `;
  }

  function renderInspectionHistoryList() {
    const inspections = state.inspections || [];
    const templates = state.inspectionTemplates || [];

    return `
      <div class="hse-filter-bar">
        <input type="text" class="hse-input" id="hseInspectionSearch" placeholder="Cari no inspeksi, unit, auditor..." value="${ESC(state.inspectionFilters.search)}" style="min-width:200px;">
        <select class="hse-select" id="hseFilterInspectionTemplate">
          <option value="">Semua Checklist Template</option>
          ${templates.map(t => `<option value="${t.id}" ${state.inspectionFilters.template_id === t.id ? 'selected' : ''}>${ESC(t.name)}</option>`).join('')}
        </select>
        <select class="hse-select" id="hseFilterInspectionLocation">
          ${renderLocationHierarchyOptions(state.inspectionFilters.location_id, 'Semua Lokasi', true)}
        </select>
        <select class="hse-select" id="hseFilterInspectionStatus">
          <option value="">Semua Status</option>
          <option value="COMPLETED" ${state.inspectionFilters.status === 'COMPLETED' ? 'selected' : ''}>Selesai (COMPLETED)</option>
          <option value="IN_PROGRESS" ${state.inspectionFilters.status === 'IN_PROGRESS' ? 'selected' : ''}>Dalam Proses</option>
        </select>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>No Inspeksi</th>
              <th>Tanggal</th>
              <th>Checklist Template</th>
              <th>Lokasi / Tag Unit</th>
              <th>Auditor / PIC</th>
              <th>Hasil / Temuan</th>
              <th>Status</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${inspections.length === 0 ? `
              <tr>
                <td colspan="8" style="text-align:center;padding:24px;color:var(--hse-text-muted);">
                  Belum ada data pelaksanaan inspeksi yang tercatat.
                </td>
              </tr>
            ` : inspections.map(ins => {
              const passPct = ins.pass_rate_pct != null ? `${ins.pass_rate_pct}% Pass` : '-';
              const critCount = Number(ins.critical_findings_count) || (Number(ins.findings_count) || 0);
              return `
                <tr>
                  <td><strong>${ESC(ins.inspection_no)}</strong></td>
                  <td>${ESC(String(ins.inspected_at || ins.inspection_date || '').slice(0, 10))}</td>
                  <td>
                    <span class="hse-badge hse-badge--accent">${ESC(ins.template_code || '')}</span>
                    <span style="margin-left:4px;">${ESC(ins.template_name || '-')}</span>
                  </td>
                  <td>
                    <div>${ESC(ins.location_name || '-')}</div>
                    ${(ins.object_identifier || ins.equipment_tag) ? `<div style="font-size:11px;color:var(--hse-text-secondary);font-weight:600;">Unit: ${ESC(ins.object_identifier || ins.equipment_tag)}</div>` : ''}
                  </td>
                  <td>${ESC(ins.inspected_by_name || ins.inspector_name || '-')}</td>
                  <td>
                    ${critCount > 0 ? `<span class="hse-badge hse-badge--extreme" style="font-size:10px;">${critCount} Temuan</span>` : `<span class="hse-badge hse-badge--success" style="font-size:10px;">Sesuai Standar</span>`}
                  </td>
                  <td><span class="hse-badge hse-badge--${ins.status === 'COMPLETED' ? 'closed' : 'process'}">${ESC(ins.status)}</span></td>
                  <td>
                    <button type="button" class="hse-btn" data-btn-inspection-detail="${ins.id}" style="padding:2px 8px;font-size:11px;">
                      Lihat Detail
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderInspectionDueTasksList() {
    const schedules = state.inspectionDueSchedules || [];
    const todaySchedules = schedules.filter(s => s.due_status === 'TODAY');
    const overdueSchedules = schedules.filter(s => s.due_status === 'OVERDUE');
    const upcomingSchedules = schedules.filter(s => s.due_status === 'SCHEDULED');

    return `
      <div class="hse-stats-bar" style="margin-bottom:12px;">
        <div class="hse-stat-card">
          <div class="hse-stat-title">Jatuh Tempo Hari Ini</div>
          <div class="hse-stat-val" style="color:${todaySchedules.length > 0 ? 'var(--hse-text-accent)' : 'var(--hse-text-secondary)'};">
            ${todaySchedules.length}
          </div>
        </div>
        <div class="hse-stat-card">
          <div class="hse-stat-title">Terlambat (Overdue)</div>
          <div class="hse-stat-val" style="color:${overdueSchedules.length > 0 ? 'var(--hse-text-danger)' : 'var(--hse-text-muted)'};">
            ${overdueSchedules.length}
          </div>
        </div>
        <div class="hse-stat-card">
          <div class="hse-stat-title">Total Objek Terjadwal</div>
          <div class="hse-stat-val" style="color:var(--hse-text-secondary);">
            ${schedules.length}
          </div>
        </div>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Jenis Inspeksi</th>
              <th>Objek Pengawasan</th>
              <th>Penanggung Jawab</th>
              <th>Siklus</th>
              <th>Jatuh Tempo</th>
              <th>Status</th>
              <th style="text-align:right;">Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${schedules.length === 0 ? `
              <tr>
                <td colspan="7" style="text-align:center;padding:24px;color:var(--hse-text-muted);">
                  Tidak ada jadwal objek inspeksi yang terdaftar.
                </td>
              </tr>
            ` : schedules.map(s => {
              const assignee = s.assignee_type === 'EMPLOYEE' ? (s.assignee_employee_name || 'Karyawan') : `Jabatan: ${s.assignee_position_name || 'Pengawas'}`;
              let dueBadge = `<span class="hse-badge hse-badge--outline">Terjadwal</span>`;
              if (s.due_status === 'TODAY') dueBadge = `<span class="hse-badge hse-badge--low" style="background:#e0f2fe;color:#0369a1;font-weight:700;">HARI INI</span>`;
              else if (s.due_status === 'OVERDUE') dueBadge = `<span class="hse-badge hse-badge--danger">TERLAMBAT</span>`;

              return `
                <tr>
                  <td>
                    <div style="font-weight:600;color:var(--hse-text-primary);">${ESC(s.template_name)}</div>
                    <div style="font-size:10px;color:var(--hse-text-muted);font-family:monospace;">${ESC(s.template_code || '')}</div>
                  </td>
                  <td>${ESC(s.location_name || s.asset_id || '-')}</td>
                  <td><span style="color:var(--hse-text-secondary);">${ESC(assignee)}</span></td>
                  <td><span class="hse-badge hse-badge--outline">${ESC(s.schedule_cycle)}</span></td>
                  <td><strong>${ESC(String(s.next_due_date || '-').slice(0, 10))}</strong></td>
                  <td>${dueBadge}</td>
                  <td style="text-align:right;">
                    <button type="button" class="hse-btn hse-btn--primary btn-start-scheduled-inspection" data-start-schedule-id="${s.id}" style="padding:3px 8px;font-size:11px;">
                      <i class="ti ti-player-play"></i> Mulai Inspeksi
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderInspectionComplianceTab() {
    const rep = state.inspectionComplianceReport || { summary: {}, items: [] };
    const summary = rep.summary || {};
    const items = rep.items || [];
    const schedCov = summary.scheduleCoverage || {};

    const months = [
      'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
      'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
    ];
    const currentMonth = state.inspectionComplianceFilters?.month || (new Date().getMonth() + 1);
    const currentYear = state.inspectionComplianceFilters?.year || new Date().getFullYear();

    return `
      <!-- Toolbar Filter Bulan/Tahun -->
      <div style="background:#ffffff;border:0.5px solid var(--hse-border);border-radius:8px;padding:12px;margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;">
        <div style="display:flex;align-items:center;gap:8px;">
          <label style="font-size:11px;font-weight:600;color:var(--hse-text-secondary);">Periode Evaluasi:</label>
          <select class="hse-form-select" id="selHseComplianceMonth" style="width:auto;font-size:11px;padding:5px 8px;">
            ${months.map((m, idx) => `<option value="${idx + 1}" ${currentMonth === (idx + 1) ? 'selected' : ''}>${m}</option>`).join('')}
          </select>
          <select class="hse-form-select" id="selHseComplianceYear" style="width:auto;font-size:11px;padding:5px 8px;">
            <option value="2025" ${currentYear === 2025 ? 'selected' : ''}>2025</option>
            <option value="2026" ${currentYear === 2026 ? 'selected' : ''}>2026</option>
            <option value="2027" ${currentYear === 2027 ? 'selected' : ''}>2027</option>
          </select>
        </div>
        <div style="font-size:11px;color:var(--hse-text-muted);">
          Mengacu formula: <code>Kepatuhan Kuota = Pengawas Tercapai ÷ Pengawas Wajib × 100%</code>
        </div>
      </div>

      <!-- Stats Bar 3 Kartu -->
      <div class="hse-stats-bar" style="margin-bottom:12px;">
        <div class="hse-stat-card">
          <div class="hse-stat-title">Kepatuhan Kuota Pengawas</div>
          <div class="hse-stat-val" style="color:var(--hse-text-accent);">
            ${summary.complianceRate || 0}%
          </div>
          <div style="font-size:11px;color:var(--hse-text-muted);margin-top:2px;">
            ${summary.achievedCount || 0} dari ${summary.totalWajib || 0} pengawas memenuhi target
          </div>
        </div>
        <div class="hse-stat-card">
          <div class="hse-stat-title">Cakupan Jadwal Objek</div>
          <div class="hse-stat-val" style="color:${(schedCov.coverageRate || 0) >= 80 ? 'var(--hse-text-accent)' : 'var(--hse-text-warning, #d97706)'};">
            ${schedCov.coverageRate || 0}%
          </div>
          <div style="font-size:11px;color:var(--hse-text-muted);margin-top:2px;">
            ${schedCov.completedInPeriod || 0} dari ${schedCov.dueInPeriod || 0} jadwal selesai diinspeksi
          </div>
        </div>
        <div class="hse-stat-card">
          <div class="hse-stat-title">Jadwal Overdue</div>
          <div class="hse-stat-val" style="color:${(schedCov.overdueCount || 0) > 0 ? 'var(--hse-text-danger)' : 'var(--hse-text-muted)'};">
            ${schedCov.overdueCount || 0}
          </div>
          <div style="font-size:11px;color:var(--hse-text-muted);margin-top:2px;">
            Objek terlambat di luar tenggat siklus
          </div>
        </div>
      </div>

      <!-- Tabel Realisasi vs Target Kuota Pengawas -->
      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Pengawas / NRP</th>
              <th>Departemen</th>
              <th>Jabatan</th>
              <th style="text-align:center;">Target Kuota</th>
              <th style="text-align:center;">Realisasi Sah</th>
              <th style="width:180px;">Capaian (%)</th>
              <th style="text-align:right;">Status</th>
            </tr>
          </thead>
          <tbody>
            ${items.length === 0 ? `
              <tr>
                <td colspan="7" style="text-align:center;padding:28px;color:var(--hse-text-muted);">
                  Tidak ada pengawas dengan kewajiban inspeksi pada periode ini.
                </td>
              </tr>
            ` : items.map(emp => {
              const isAchieved = emp.status === 'TERCAPAI';
              const rate = emp.compliance_rate || 0;
              return `
                <tr>
                  <td>
                    <div style="font-weight:600;color:var(--hse-text-primary);">${ESC(emp.nama)}</div>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(emp.employee_nrp || '-')}</div>
                  </td>
                  <td>${ESC(emp.departemen || '-')}</td>
                  <td>${ESC(emp.jabatan || '-')}</td>
                  <td style="text-align:center;font-weight:600;">${emp.target_quota}x</td>
                  <td style="text-align:center;font-weight:700;color:${isAchieved ? 'var(--hse-text-accent)' : 'inherit'};">
                    ${emp.realization}x
                  </td>
                  <td>
                    <div style="display:flex;align-items:center;gap:8px;">
                      <div style="flex:1;background:var(--hse-surface-1);height:6px;border-radius:3px;overflow:hidden;border:0.5px solid var(--hse-border);">
                        <div style="width:${rate}%;background:${isAchieved ? 'var(--hse-text-accent)' : '#f59e0b'};height:100%;"></div>
                      </div>
                      <span style="font-size:11px;font-weight:600;min-width:34px;text-align:right;">${rate}%</span>
                    </div>
                  </td>
                  <td style="text-align:right;">
                    <span class="hse-badge ${isAchieved ? 'hse-badge--outline' : 'hse-badge--warning'}" style="${isAchieved ? 'color:var(--hse-text-accent);font-weight:700;' : ''}">
                      ${ESC(emp.status)}
                    </span>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  // -------------------------------------------------------------
  // FASE 4: IZIN KERJA (PTW, LOTO, SIMOPS) VIEW & MODALS
  // -------------------------------------------------------------

  function renderPtwView() {
    const permits = state.permits || [];
    const locations = state.masters.locations || [];
    const o = state.ptwOverview || {
      total: permits.length,
      active: permits.filter(p => p.status === 'ACTIVE').length,
      submitted: permits.filter(p => p.status === 'SUBMITTED').length,
      hseCheck: permits.filter(p => p.status === 'HSE_CHECK').length,
      approved: permits.filter(p => p.status === 'APPROVED').length,
      closed: permits.filter(p => p.status === 'CLOSED').length,
      expired: permits.filter(p => p.computed_status === 'EXPIRED').length,
      simopsCount: 0,
      simopsLocations: [],
    };

    const permitTypeBadges = {
      HOT_WORK: { label: 'Hot Work (Panas)', icon: 'ti-flame', cls: 'extreme' },
      WORK_AT_HEIGHT: { label: 'Ketinggian (WAH)', icon: 'ti-ladder', cls: 'high' },
      CONFINED_SPACE: { label: 'Ruang Terbatas', icon: 'ti-door', cls: 'extreme' },
      LOTO: { label: 'Isolasi Energi (LOTO)', icon: 'ti-lock', cls: 'high' },
      EXCAVATION: { label: 'Penggalian', icon: 'ti-shovel', cls: 'medium' },
      LIFTING: { label: 'Pengangkatan (Lifting)', icon: 'ti-crane', cls: 'medium' },
      ELECTRICAL: { label: 'Kelistrikan', icon: 'ti-bolt', cls: 'high' },
      CHEMICAL: { label: 'Bahan Kimia B3', icon: 'ti-flask', cls: 'high' },
    };

    return `
      <!-- TOP KPI SUMMARY -->
      <div class="hse-incident-stats" style="margin-bottom:12px;">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Permit</span>
          <span class="hse-stat-pill-val">${o.total || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Permit Aktif</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success); font-weight:700;">${o.active || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Menunggu Review</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);">${(o.submitted || 0) + (o.hseCheck || 0)}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-accent);">Disetujui</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-accent);">${o.approved || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Ditutup / Selesai</span>
          <span class="hse-stat-pill-val">${o.closed || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:${(o.simopsCount > 0) ? 'var(--hse-text-danger)' : 'var(--hse-text-muted)'};">Konflik SIMOPS</span>
          <span class="hse-stat-pill-val" style="color:${(o.simopsCount > 0) ? 'var(--hse-text-danger)' : 'inherit'}; font-weight:700;">
            ${o.simopsCount || 0}
          </span>
        </div>
      </div>

      ${o.simopsCount > 0 ? `
        <div class="hse-simops-alert">
          <i class="ti ti-alert-triangle" style="font-size:20px;flex-shrink:0;" aria-hidden="true"></i>
          <div>
            <strong>PERINGATAN SIMOPS (Operasi Bersamaan Terdeteksi!):</strong> Terdapat ${o.simopsCount} izin kerja aktif bersamaan di lokasi yang sama (${o.simopsLocations.map(l => l.name).join(', ')}). Pastikan koordinasi antar-pengawas tim kerja, batas isolasi, dan rambu keselamatan terpasang sebelum operasional dilanjutkan.
          </div>
        </div>
      ` : ''}

      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
        <div style="font-size:13px;color:var(--hse-text-secondary);">
          Sistem pengendalian Izin Kerja Risiko Tinggi (PTW), Isolasi Energi (LOTO), dan Pencegahan Konflik SIMOPS Site.
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseOpenCreatePermit">
          <i class="ti ti-plus" aria-hidden="true"></i> Ajukan Izin Baru
        </button>
      </div>

      <div class="hse-filter-bar">
        <input type="text" class="hse-input" id="hsePtwSearch" placeholder="Cari permit, pekerjaan, pemohon..." value="${ESC(state.ptwFilters.search)}" style="min-width:200px;">
        <select class="hse-select" id="hseFilterPtwType">
          <option value="">Semua Jenis Izin</option>
          <option value="HOT_WORK" ${state.ptwFilters.permit_type === 'HOT_WORK' ? 'selected' : ''}>Hot Work (Pekerjaan Panas)</option>
          <option value="WORK_AT_HEIGHT" ${state.ptwFilters.permit_type === 'WORK_AT_HEIGHT' ? 'selected' : ''}>Ketinggian (WAH)</option>
          <option value="CONFINED_SPACE" ${state.ptwFilters.permit_type === 'CONFINED_SPACE' ? 'selected' : ''}>Ruang Terbatas</option>
          <option value="LOTO" ${state.ptwFilters.permit_type === 'LOTO' ? 'selected' : ''}>Isolasi Energi (LOTO)</option>
          <option value="EXCAVATION" ${state.ptwFilters.permit_type === 'EXCAVATION' ? 'selected' : ''}>Penggalian</option>
          <option value="LIFTING" ${state.ptwFilters.permit_type === 'LIFTING' ? 'selected' : ''}>Pengangkatan (Lifting)</option>
          <option value="ELECTRICAL" ${state.ptwFilters.permit_type === 'ELECTRICAL' ? 'selected' : ''}>Kelistrikan</option>
          <option value="CHEMICAL" ${state.ptwFilters.permit_type === 'CHEMICAL' ? 'selected' : ''}>Bahan Kimia</option>
        </select>
        <select class="hse-select" id="hseFilterPtwLocation">
          ${renderLocationHierarchyOptions(state.ptwFilters.location_id, 'Semua Lokasi', true)}
        </select>
        <select class="hse-select" id="hseFilterPtwStatus">
          <option value="">Semua Status</option>
          <option value="ACTIVE" ${state.ptwFilters.status === 'ACTIVE' ? 'selected' : ''}>Aktif (ACTIVE)</option>
          <option value="APPROVED" ${state.ptwFilters.status === 'APPROVED' ? 'selected' : ''}>Disetujui (APPROVED)</option>
          <option value="HSE_CHECK" ${state.ptwFilters.status === 'HSE_CHECK' ? 'selected' : ''}>Pemeriksaan HSE</option>
          <option value="SUBMITTED" ${state.ptwFilters.status === 'SUBMITTED' ? 'selected' : ''}>Diajukan (SUBMITTED)</option>
          <option value="CLOSED" ${state.ptwFilters.status === 'CLOSED' ? 'selected' : ''}>Ditutup (CLOSED)</option>
          <option value="REJECTED" ${state.ptwFilters.status === 'REJECTED' ? 'selected' : ''}>Ditolak (REJECTED)</option>
        </select>
        <label style="display:inline-flex;align-items:center;gap:6px;font-size:12px;cursor:pointer;">
          <input type="checkbox" id="hseFilterPtwSimopsOnly" ${state.ptwFilters.simops_only ? 'checked' : ''}>
          <span>Hanya Konflik SIMOPS</span>
        </label>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>No Permit</th>
              <th>Jenis Izin</th>
              <th>Lokasi & Area</th>
              <th>Pekerjaan</th>
              <th>Pemohon / Pengawas</th>
              <th>Masa Berlaku</th>
              <th>Status</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${permits.length === 0 ? `
              <tr>
                <td colspan="8" style="text-align:center;padding:24px;color:var(--hse-text-muted);">
                  Belum ada Izin Kerja (Permit) yang sesuai kriteria pencarian.
                </td>
              </tr>
            ` : permits.map(p => {
              const b = permitTypeBadges[p.permit_type] || { label: p.permit_type, icon: 'ti-file-certificate', cls: 'medium' };
              const st = p.computed_status || p.status;
              const isSimops = Boolean(p.is_simops);

              return `
                <tr>
                  <td><strong>${ESC(p.permit_no)}</strong></td>
                  <td>
                    <span class="hse-badge hse-badge--${b.cls}">
                      <i class="ti ${b.icon}" aria-hidden="true"></i> ${ESC(b.label)}
                    </span>
                  </td>
                  <td>
                    <div>${ESC(p.location_name || '-')}</div>
                    ${p.area_description ? `<div style="font-size:11px;color:var(--hse-text-secondary);">${ESC(p.area_description)}</div>` : ''}
                    ${isSimops ? `<span class="hse-badge hse-badge--simops" style="margin-top:2px;"><i class="ti ti-alert-triangle" aria-hidden="true"></i> SIMOPS AKTIF</span>` : ''}
                  </td>
                  <td style="max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${ESC(p.title)}">
                    <strong>${ESC(p.title)}</strong>
                    ${p.contractor_name ? `<div style="font-size:10px;color:var(--hse-text-muted);">${ESC(p.contractor_name)}</div>` : ''}
                  </td>
                  <td>
                    <div>${ESC(p.applicant_name || '-')}</div>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(p.supervisor_name || 'Pengawas Site')}</div>
                  </td>
                  <td style="font-size:11px;">
                    <div>Mulai: ${ESC(String(p.valid_from).slice(0, 16).replace('T', ' '))}</div>
                    <div>Selesai: ${ESC(String(p.valid_until).slice(0, 16).replace('T', ' '))}</div>
                  </td>
                  <td>
                    <span class="hse-badge hse-badge--ptw-${st.toLowerCase().replace(/_/g, '-')}">${ESC(st)}</span>
                  </td>
                  <td>
                    <button type="button" class="hse-btn" data-btn-ptw-detail="${p.id}" style="padding:2px 8px;font-size:11px;">
                      Detail & Pengendalian
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  // -------------------------------------------------------------
  // FASE 4: PTW DETAIL MODAL & CHILD ACTIONS (LOTO, WORKERS, HANDOVER)
  // -------------------------------------------------------------

  async function openPermitDetailModal(permitId, activeTab = 'info') {
    try {
      const permit = await api(`/ptw/permits/${permitId}`);
      state.selectedPermit = permit;
      state.ptwDetailTab = activeTab;

      const workers = permit.workers || [];
      const isolations = permit.isolations || [];
      const handovers = permit.handovers || [];
      const simopsList = permit.simopsConflicts || [];
      const isSimops = simopsList.length > 0;

      const tabs = [
        { key: 'info', label: 'Informasi & Otorisasi', icon: 'ti-info-circle' },
        { key: 'workers', label: `Pekerja & Lisensi (${workers.length})`, icon: 'ti-users' },
        { key: 'loto', label: `Isolasi LOTO (${isolations.length})`, icon: 'ti-lock' },
        { key: 'handovers', label: `Serah Terima Shift (${handovers.length})`, icon: 'ti-arrows-left-right' },
      ];

      state.activeModal = `
        <div class="hse-modal-header">
          <div>
            <div class="hse-modal-title">
              Izin Kerja: ${ESC(permit.permit_no)}
              <span class="hse-badge hse-badge--ptw-${(permit.computed_status || permit.status).toLowerCase().replace(/_/g, '-')}" style="margin-left:6px;vertical-align:middle;">
                ${ESC(permit.computed_status || permit.status)}
              </span>
            </div>
            <div style="font-size:12px;color:var(--hse-text-secondary);margin-top:2px;">
              ${ESC(permit.permit_type)} · ${ESC(permit.location_name)} (${ESC(permit.area_description || 'Area Umum')})
            </div>
          </div>
          <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
        </div>

        ${isSimops ? `
          <div class="hse-simops-alert" style="margin-top:10px;">
            <i class="ti ti-alert-triangle" style="font-size:20px;flex-shrink:0;" aria-hidden="true"></i>
            <div>
              <strong>PERINGATAN SIMOPS AKTIF:</strong> Terdeteksi ${simopsList.length} permit aktif lain di ${ESC(permit.location_name)}:
              ${simopsList.map(c => `<strong>${ESC(c.permit_no)}</strong> (${ESC(c.permit_type)})`).join(', ')}.
              Koordinasikan zona kerja untuk mencegah kecelakaan fatal operasi bersamaan!
            </div>
          </div>
        ` : ''}

        <div class="hse-tab-pills" style="margin-top:12px;margin-bottom:14px;">
          ${tabs.map(t => `
            <button type="button" class="hse-tab-pill ${state.ptwDetailTab === t.key ? 'is-active' : ''}" data-ptw-tab="${t.key}">
              <i class="ti ${t.icon}" aria-hidden="true"></i> ${ESC(t.label)}
            </button>
          `).join('')}
        </div>

        <div style="min-height:260px;">
          ${state.ptwDetailTab === 'info' ? renderPermitInfoTab(permit) : (
            state.ptwDetailTab === 'workers' ? renderPermitWorkersTab(permit) : (
              state.ptwDetailTab === 'loto' ? renderPermitLotoTab(permit) : renderPermitHandoversTab(permit)
            )
          )}
        </div>
      `;

      render();

      document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
        state.activeModal = null;
        render();
      });

      rootEl.querySelectorAll('[data-ptw-tab]').forEach(btn => {
        btn.addEventListener('click', () => {
          openPermitDetailModal(permitId, btn.dataset.ptwTab);
        });
      });

      attachPermitDetailActions(permit);
    } catch (err) {
      alert('Gagal memuat detail izin kerja: ' + err.message);
    }
  }

