  // -------------------------------------------------------------
  // FASE 4: INSPECTION MODALS (CREATE & DETAIL)
  // -------------------------------------------------------------

  function openCreateInspectionModal(preselectedSchedule = null) {
    const templates = state.inspectionTemplates || [];
    const locations = state.masters.locations || [];
    let selectedTemplate = null;

    if (preselectedSchedule) {
      selectedTemplate = templates.find(t => t.id === preselectedSchedule.template_root_id || t.root_id === preselectedSchedule.template_root_id) || templates[0] || null;
    } else {
      selectedTemplate = templates[0] || null;
    }

    const renderTemplateQuestions = (tmpl) => {
      if (!tmpl || !tmpl.items || tmpl.items.length === 0) {
        return `<div style="text-align:center;padding:16px;color:var(--hse-text-muted);">Tidak ada pertanyaan dalam checklist ini.</div>`;
      }

      // Group items by category
      const groups = {};
      tmpl.items.forEach(it => {
        const cat = it.category || 'Umum';
        if (!groups[cat]) groups[cat] = [];
        groups[cat].push(it);
      });

      return Object.keys(groups).map(catName => `
        <div class="hse-checklist-group">
          <div class="hse-checklist-group-title">${ESC(catName)}</div>
          ${groups[catName].map(it => `
            <div class="hse-checklist-row ${it.is_critical ? 'is-critical' : ''}">
              <div class="hse-checklist-prompt">
                <div>${ESC(it.item_prompt || it.question || 'Pemeriksaan')}</div>
                ${it.is_critical ? `<span class="hse-badge hse-badge--extreme" style="font-size:9px;margin-top:2px;">KRITIKAL (Auto-CAPA jika GAGAL)</span>` : ''}
              </div>
              <div class="hse-checklist-options">
                <label class="hse-checklist-opt">
                  <input type="radio" name="chk_ans_${it.id}" value="YES" checked>
                  <span style="color:var(--hse-text-success);">YES</span>
                </label>
                <label class="hse-checklist-opt">
                  <input type="radio" name="chk_ans_${it.id}" value="NO">
                  <span style="color:var(--hse-text-danger);">NO</span>
                </label>
                <label class="hse-checklist-opt">
                  <input type="radio" name="chk_ans_${it.id}" value="NA">
                  <span style="color:var(--hse-text-muted);">N/A</span>
                </label>
              </div>
            </div>
          `).join('')}
        </div>
      `).join('');
    };

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">
          <i class="ti ti-clipboard-check"></i> Pelaksanaan Inspeksi Keselamatan Lapangan
        </div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseCreateInspection" style="margin-top:12px;">
        ${preselectedSchedule ? `
          <div style="background:var(--hse-surface-1);border:1px solid var(--hse-border);padding:8px 12px;border-radius:6px;margin-bottom:12px;display:flex;align-items:center;gap:10px;">
            <i class="ti ti-calendar-check" style="color:var(--hse-text-accent);font-size:20px;"></i>
            <div>
              <div style="font-size:12px;font-weight:700;color:var(--hse-text-primary);">
                Realisasi Jadwal: ${ESC(preselectedSchedule.template_name)}
              </div>
              <div style="font-size:11px;color:var(--hse-text-secondary);">
                Objek: ${ESC(preselectedSchedule.location_name || preselectedSchedule.asset_id || '-')} &middot; Tenggat: ${ESC(String(preselectedSchedule.next_due_date || '-').slice(0, 10))}
              </div>
            </div>
          </div>
        ` : ''}

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Pilih Checklist Template *</label>
            <select class="hse-form-select" id="inInsTemplate" required ${preselectedSchedule ? 'disabled style="background:var(--hse-surface-1);"' : ''}>
              ${templates.map(t => `<option value="${t.id}" ${selectedTemplate && (selectedTemplate.id === t.id || selectedTemplate.root_id === t.root_id) ? 'selected' : ''}>${ESC(t.name)} (${ESC(t.code || '')})</option>`).join('')}
            </select>
          </div>
          <div>
            <label class="hse-form-label">Lokasi Pemeriksaan *</label>
            <select class="hse-form-select" id="inInsLocation" required>
              ${renderLocationHierarchyOptions(preselectedSchedule?.location_id || '', 'Pilih Lokasi')}
            </select>
          </div>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tag / Nomor Unit (Opsional)</label>
            <input type="text" class="hse-form-input" id="inInsUnit" placeholder="Mis. LV-012 / HD-785 / APAR-WS-01" value="${ESC(preselectedSchedule?.asset_id || preselectedSchedule?.location_name || '')}">
          </div>
          <div>
            <label class="hse-form-label">Tanggal Pelaksanaan *</label>
            <input type="date" class="hse-form-input" id="inInsDate" value="${new Date().toISOString().slice(0, 10)}" required>
          </div>
        </div>

        <div style="font-size:12px;font-weight:600;margin-top:10px;margin-bottom:6px;color:var(--hse-text-primary);">
          Daftar Butir Pemeriksaan Checklist:
        </div>
        <div id="hseInsQuestionsContainer" style="max-height:300px;overflow-y:auto;padding-right:4px;">
          ${renderTemplateQuestions(selectedTemplate)}
        </div>

        <div class="hse-form-group" style="margin-top:10px;">
          <label class="hse-form-label">Catatan / Ringkasan Inspektur</label>
          <textarea class="hse-form-textarea" id="inInsNotes" placeholder="Kondisi umum unit / area kerja saat diperiksa...">${preselectedSchedule?.notes ? ESC(`Instruksi jadwal: ${preselectedSchedule.notes}`) : ''}</textarea>
        </div>

        <div class="hse-form-group" style="margin-top:10px;">
          <label class="hse-form-label">📷 Foto Inspeksi * <span style="font-weight:400;color:var(--hse-text-muted);">(Wajib minimal 1 foto, maks. 3, otomatis dikompresi)</span></label>
          <input type="file" class="hse-form-input" id="inInsPhotos" accept="image/*" multiple style="padding:6px;">
          <div id="inInsPhotoPreviewList"></div>
        </div>

        <div class="hse-form-group" style="margin-top:10px;">
          <label class="hse-form-label">📎 Dokumen Pendukung <span style="font-weight:400;color:var(--hse-text-muted);">(Opsional, PDF/DOCX/XLSX, maks. 3 × 2 MB)</span></label>
          <input type="file" class="hse-form-input" id="inInsDocs" accept=".pdf,.docx,.xlsx" multiple style="padding:6px;">
          <div id="inInsDocList"></div>
        </div>

        <div id="hseInsFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitHseInspection">Selesaikan & Simpan Inspeksi</button>
        </div>
      </form>
    `;
    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const tmplSelect = document.getElementById('inInsTemplate');
    if (tmplSelect && !preselectedSchedule) {
      tmplSelect.addEventListener('change', (e) => {
        selectedTemplate = templates.find(t => t.id === e.target.value) || null;
        const container = document.getElementById('hseInsQuestionsContainer');
        if (container) {
          container.innerHTML = renderTemplateQuestions(selectedTemplate);
        }
      });
    }

    const insPhotoCtrl = bindPhotoAttachmentController('inInsPhotos', 'inInsPhotoPreviewList', []);
    const insDocCtrl = bindDocumentAttachmentController('inInsDocs', 'inInsDocList', []);

    const form = document.getElementById('formHseCreateInspection');
    const submitBtn = document.getElementById('btnSubmitHseInspection');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseInsFormError');
        if (errEl) errEl.hidden = true;

        if (!selectedTemplate || !selectedTemplate.items) {
          if (errEl) { errEl.textContent = 'Template checklist tidak valid'; errEl.hidden = false; }
          return;
        }

        const photos = insPhotoCtrl.getPhotos();
        if (photos.length === 0) {
          if (errEl) { errEl.textContent = 'Inspeksi wajib memiliki minimal 1 foto'; errEl.hidden = false; }
          return;
        }

        const answers = selectedTemplate.items.map(it => {
          const checkedRadio = form.querySelector(`input[name="chk_ans_${it.id}"]:checked`);
          return {
            item_id: it.id,
            question: it.question || it.item_prompt || 'Pemeriksaan',
            is_critical: Boolean(it.is_critical),
            answer: checkedRadio ? checkedRadio.value : 'YES',
            notes: null,
          };
        });

        const payload = {
          template_id: selectedTemplate.id,
          location_id: document.getElementById('inInsLocation')?.value,
          schedule_id: preselectedSchedule ? preselectedSchedule.id : null,
          object_identifier: document.getElementById('inInsUnit')?.value.trim() || 'Unit Lapangan',
          equipment_tag: document.getElementById('inInsUnit')?.value.trim() || null,
          inspection_date: document.getElementById('inInsDate')?.value,
          result_summary: document.getElementById('inInsNotes')?.value.trim() || null,
          notes: document.getElementById('inInsNotes')?.value.trim() || null,
          photos,
          documents: insDocCtrl.getDocuments(),
          answers,
        };

        const work = async () => {
          await api('/inspections', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadInspectionData();
          await loadHazardsAndActions();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

  async function openInspectionDetailModal(inspectionId) {
    try {
      const ins = await api(`/inspections/${inspectionId}`);
      state.selectedInspection = ins;
      const answers = ins.answers || [];
      const criticalFindings = ins.criticalFindings || [];

      // Staged edit lampiran: perubahan hanya lokal sampai "Simpan Perubahan"
      let dirty = false;

      const refreshSaveState = () => {
        const photos = photoCtrl ? photoCtrl.getPhotos() : [];
        const saveBtn = document.getElementById('btnHseInsSaveLampiran');
        const dirtyHint = document.getElementById('hseInsLampiranDirtyHint');
        const photoHint = document.getElementById('hseInsPhotoRequiredHint');
        const photoCount = document.getElementById('hseInsPhotoCount');
        if (saveBtn) saveBtn.disabled = !(dirty && photos.length > 0);
        if (dirtyHint) dirtyHint.style.display = dirty ? 'block' : 'none';
        if (photoHint) photoHint.hidden = photos.length > 0;
        if (photoCount) photoCount.textContent = `${photos.length}/3 foto`;
      };

      const onLampiranChange = () => {
        dirty = true;
        refreshSaveState();
      };

      const onBeforeUnload = (event) => {
        if (!dirty) return;
        event.preventDefault();
        event.returnValue = '';
      };
      global.addEventListener('beforeunload', onBeforeUnload);

      state.activeModal = `
        <div class="hse-modal-header">
          <div>
            <div class="hse-modal-title">
              Inspeksi: ${ESC(ins.inspection_no)}
              <span class="hse-badge hse-badge--${ins.status === 'COMPLETED' ? 'closed' : 'process'}" style="margin-left:6px;vertical-align:middle;">
                ${ESC(ins.status)}
              </span>
            </div>
            <div style="font-size:12px;color:var(--hse-text-secondary);margin-top:2px;">
              ${ESC(ins.template_name)} · ${ESC(ins.location_name)} ${(ins.equipment_tag || ins.object_identifier) ? `· Unit: ${ESC(ins.equipment_tag || ins.object_identifier)}` : ''}
            </div>
          </div>
          <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
        </div>

        <div style="display:grid;grid-template-columns:repeat(3, 1fr);gap:10px;margin-top:12px;margin-bottom:12px;">
          <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);padding:8px 10px;border-radius:6px;text-align:center;">
            <div style="font-size:11px;color:var(--hse-text-secondary);">Tingkat Kelulusan</div>
            <div style="font-size:16px;font-weight:700;color:${ins.pass_rate_pct >= 85 ? 'var(--hse-text-success)' : 'var(--hse-text-warning)'};">
              ${ins.pass_rate_pct != null ? `${ins.pass_rate_pct}%` : '-'}
            </div>
          </div>
          <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);padding:8px 10px;border-radius:6px;text-align:center;">
            <div style="font-size:11px;color:var(--hse-text-secondary);">Auditor / Pemeriksa</div>
            <div style="font-size:13px;font-weight:600;">${ESC(ins.inspector_name || ins.inspected_by_name || '-')}</div>
          </div>
          <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);padding:8px 10px;border-radius:6px;text-align:center;">
            <div style="font-size:11px;color:var(--hse-text-secondary);">Temuan Kritikal</div>
            <div style="font-size:16px;font-weight:700;color:${criticalFindings.length > 0 ? 'var(--hse-text-danger)' : 'var(--hse-text-success)'};">
              ${criticalFindings.length}
            </div>
          </div>
        </div>

        ${criticalFindings.length > 0 ? `
          <div class="hse-simops-alert" style="margin-bottom:12px;">
            <i class="ti ti-alert-triangle" style="font-size:20px;flex-shrink:0;" aria-hidden="true"></i>
            <div>
              <strong>TEMUAN KRITIKAL DIHASILKAN:</strong> Ditemukan ${criticalFindings.length} butir pemeriksaan kritikal yang gagal (NO).
              Tindakan korektif (CAPA) otomatis diterbitkan oleh sistem untuk segera ditindaklanjuti.
            </div>
          </div>
        ` : ''}

        <div style="font-size:12px;font-weight:600;margin-bottom:6px;">Daftar Jawaban Butir Pemeriksaan:</div>
        <div class="hse-table-wrap" style="max-height:280px;overflow-y:auto;">
          <table class="hse-table" style="font-size:11px;">
            <thead>
              <tr>
                <th style="width:30px;">No</th>
                <th>Kategori</th>
                <th>Butir Pemeriksaan</th>
                <th style="text-align:center;width:80px;">Hasil</th>
                <th>Catatan Temuan</th>
              </tr>
            </thead>
            <tbody>
              ${answers.map((a, idx) => {
                const ansCls = { YES: 'valid', NO: 'expired', NA: 'accent' }[a.answer] || 'accent';
                return `
                  <tr>
                    <td>${idx + 1}</td>
                    <td><span class="hse-badge hse-badge--accent">${ESC(a.category || '-')}</span></td>
                    <td>
                      <div>${ESC(a.item_prompt || a.question || '-')}</div>
                      ${a.is_critical ? `<span class="hse-badge hse-badge--extreme" style="font-size:9px;">KRITIKAL</span>` : ''}
                    </td>
                    <td style="text-align:center;">
                      <span class="hse-badge hse-badge--${ansCls}">${ESC(a.answer)}</span>
                    </td>
                    <td style="color:var(--hse-text-secondary);">
                      ${ESC(a.notes || a.note || '-')}
                      ${photoThumbsHtml(`insa:${a.id || `${ins.id}-${idx}`}`, a.photo, `${ins.inspection_no || 'Inspeksi'} · butir ${idx + 1}`)}
                    </td>
                  </tr>
                `;
              }).join('')}
            </tbody>
          </table>
        </div>

        ${ins.notes || ins.result_summary ? `
          <div style="margin-top:10px;font-size:12px;background:var(--hse-surface-1);padding:8px 10px;border-radius:6px;border:0.5px solid var(--hse-border);">
            <strong>Catatan Inspektur:</strong> ${ESC(ins.notes || ins.result_summary)}
          </div>
        ` : ''}

        <div style="margin-top:12px;">
          <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
            <div style="font-size:12px;font-weight:600;">📷 Foto Inspeksi <span style="color:var(--hse-text-danger);">*</span></div>
            <span id="hseInsPhotoCount" style="font-size:11px;color:var(--hse-text-secondary);">${(ins.photos || []).length}/3 foto</span>
          </div>
          <input type="file" class="hse-form-input" id="inInsDetailPhotos" accept="image/*" multiple style="padding:6px;margin-top:4px;">
          <div id="inInsDetailPhotoList"></div>
        </div>

        <div style="margin-top:12px;">
          <div style="font-size:12px;font-weight:600;">📎 Dokumen Pendukung <span style="font-weight:400;color:var(--hse-text-muted);">(PDF/DOCX/XLSX, maks. 3 × 2 MB)</span></div>
          <input type="file" class="hse-form-input" id="inInsDetailDocs" accept=".pdf,.docx,.xlsx" multiple style="padding:6px;margin-top:4px;">
          <div id="inInsDetailDocList"></div>
        </div>

        <div id="hseInsLampiranError" style="color:var(--hse-text-danger);font-size:11px;margin-top:8px;" hidden></div>
        <div id="hseInsLampiranDirtyHint" style="font-size:11px;color:var(--hse-text-warning);margin-top:6px;display:none;">
          Ada perubahan lampiran yang belum disimpan.
        </div>

        <div style="display:flex;justify-content:flex-end;align-items:center;gap:8px;margin-top:14px;">
          <span id="hseInsPhotoRequiredHint" style="font-size:11px;color:var(--hse-text-danger);margin-right:auto;" ${(ins.photos || []).length > 0 ? 'hidden' : ''}>
            Inspeksi wajib memiliki minimal 1 foto
          </span>
          <button type="button" class="hse-btn" id="btnHseInsDetailClose">Tutup</button>
          <button type="button" class="hse-btn hse-btn--primary" id="btnHseInsSaveLampiran" disabled>Simpan Perubahan</button>
        </div>
      `;

      render();

      const photoCtrl = bindPhotoAttachmentController('inInsDetailPhotos', 'inInsDetailPhotoList', ins.photos || [], onLampiranChange);
      const docCtrl = bindDocumentAttachmentController('inInsDetailDocs', 'inInsDetailDocList', ins.documents || [], onLampiranChange);
      refreshSaveState();

      const tryClose = () => {
        if (dirty) {
          const photosEmpty = photoCtrl.getPhotos().length === 0;
          const msg = photosEmpty
            ? 'Perubahan lampiran belum tersimpan. Ingat: Inspeksi wajib memiliki minimal 1 foto. Tinggalkan tanpa simpan?'
            : 'Perubahan lampiran belum tersimpan. Tinggalkan tanpa simpan?';
          if (!window.confirm(msg)) return;
        }
        global.removeEventListener('beforeunload', onBeforeUnload);
        state.activeModal = null;
        render();
      };
      document.getElementById('btnHseCloseModal2')?.addEventListener('click', tryClose);
      document.getElementById('btnHseInsDetailClose')?.addEventListener('click', tryClose);

      const saveBtn = document.getElementById('btnHseInsSaveLampiran');
      const errEl = document.getElementById('hseInsLampiranError');
      saveBtn?.addEventListener('click', async () => {
        if (errEl) errEl.hidden = true;
        const photos = photoCtrl.getPhotos();
        if (photos.length === 0) {
          if (errEl) { errEl.textContent = 'Inspeksi wajib memiliki minimal 1 foto'; errEl.hidden = false; }
          return;
        }

        const work = async () => {
          await api(`/inspections/${inspectionId}/lampiran`, {
            method: 'PUT',
            body: { photos, documents: docCtrl.getDocuments() },
          });
          dirty = false;
          global.removeEventListener('beforeunload', onBeforeUnload);
          await loadInspectionData();
          await openInspectionDetailModal(inspectionId);
        };

        try {
          await runHseActionFeedback(saveBtn, work);
        } catch (err) {
          if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
        }
      });
    } catch (err) {
      alert('Gagal memuat detail inspeksi: ' + err.message);
    }
  }

  // -------------------------------------------------------------
  // REGISTER RISIKO (IBPR / HIRADC) VIEWS & MODALS
  // -------------------------------------------------------------

  function renderRiskRegisterTab() {
    const risks = state.riskRegister || [];
    const overview = state.riskOverview || {
      totalRisks: risks.length,
      extremeCount: 0,
      highCount: 0,
      mediumCount: 0,
      lowCount: 0,
      reviewDueCount: 0,
      matrix: [],
    };

    const levelBadge = lvl => {
      const cls = { LOW: 'low', MEDIUM: 'medium', HIGH: 'high', EXTREME: 'extreme' }[lvl] || 'low';
      const label = { LOW: 'Rendah', MEDIUM: 'Sedang', HIGH: 'Tinggi', EXTREME: 'Ekstrem' }[lvl] || lvl;
      return `<span class="hse-badge hse-badge--${cls}">${ESC(label)}</span>`;
    };

    const statusBadge = st => {
      const map = {
        ACTIVE: { cls: 'process', label: 'Aktif' },
        UNDER_REVIEW: { cls: 'warning', label: 'Perlu Review' },
        CLOSED: { cls: 'closed', label: 'Ditutup' },
      };
      const s = map[st] || { cls: 'process', label: st };
      return `<span class="hse-badge hse-badge--${s.cls}">${ESC(s.label)}</span>`;
    };

    const hierarchyLabels = {
      ELIMINATION: { label: 'Eliminasi', cls: 'elimination' },
      SUBSTITUTION: { label: 'Substitusi', cls: 'substitution' },
      ENGINEERING: { label: 'Rekayasa', cls: 'engineering' },
      ADMINISTRATIVE: { label: 'Administrasi', cls: 'administrative' },
      PPE: { label: 'APD', cls: 'ppe' },
    };

    const likelihoodNames = {
      5: '5 - Hampir Pasti',
      4: '4 - Sering',
      3: '3 - Dapat Terjadi',
      2: '2 - Jarang',
      1: '1 - Hampir Tidak Pernah',
    };

    const matrixCells = [];
    for (let l = 5; l >= 1; l--) {
      for (let c = 1; c <= 5; c++) {
        const score = l * c;
        let lvl = 'LOW';
        if (score >= 17) lvl = 'EXTREME';
        else if (score >= 10) lvl = 'HIGH';
        else if (score >= 5) lvl = 'MEDIUM';

        const matchedItem = (overview.matrix || []).find(m => Number(m.likelihood) === l && Number(m.consequence) === c);
        const count = matchedItem ? Number(matchedItem.count) : 0;
        const isSelected = (String(state.riskFilters.cell_l) === String(l) && String(state.riskFilters.cell_c) === String(c));
        const cellCls = lvl.toLowerCase();

        matrixCells.push({ l, c, score, level: lvl, count, isSelected, cellCls });
      }
    }

    const isMatrixFilterActive = Boolean(state.riskFilters.cell_l && state.riskFilters.cell_c);

    return `
      <!-- KPI CARDS -->
      <div class="hse-kpi-grid" style="grid-template-columns: repeat(6, 1fr); margin-bottom: 14px;">
        <div class="hse-card hse-kpi-card">
          <div class="hse-kpi-val">${overview.totalRisks}</div>
          <div class="hse-kpi-lbl">Total Register Risiko</div>
        </div>
        <div class="hse-card hse-kpi-card" style="border-left: 3px solid var(--hse-fill-danger);">
          <div class="hse-kpi-val" style="color:var(--hse-text-danger);">${overview.extremeCount}</div>
          <div class="hse-kpi-lbl">Risiko Ekstrem (Merah)</div>
        </div>
        <div class="hse-card hse-kpi-card" style="border-left: 3px solid var(--hse-fill-warning);">
          <div class="hse-kpi-val" style="color:var(--hse-text-warning);">${overview.highCount}</div>
          <div class="hse-kpi-lbl">Risiko Tinggi (Kuning)</div>
        </div>
        <div class="hse-card hse-kpi-card" style="border-left: 3px solid var(--hse-fill-accent);">
          <div class="hse-kpi-val" style="color:var(--hse-text-accent);">${overview.mediumCount}</div>
          <div class="hse-kpi-lbl">Risiko Sedang (Biru)</div>
        </div>
        <div class="hse-card hse-kpi-card" style="border-left: 3px solid var(--hse-fill-success);">
          <div class="hse-kpi-val" style="color:var(--hse-text-success);">${overview.lowCount}</div>
          <div class="hse-kpi-lbl">Risiko Rendah (Hijau)</div>
        </div>
        <div class="hse-card hse-kpi-card">
          <div class="hse-kpi-val" style="color:${overview.reviewDueCount > 0 ? 'var(--hse-text-warning)' : 'inherit'};">${overview.reviewDueCount}</div>
          <div class="hse-kpi-lbl">Jadwal Review Terlewat</div>
        </div>
      </div>

      <!-- MATRIKS RISIKO 5X5 INTERAKTIF -->
      <div class="hse-matrix-container">
        <div class="hse-matrix-header">
          <div>
            <div style="font-weight:700;font-size:13px;display:flex;align-items:center;gap:6px;">
              <i class="ti ti-grid-dots" style="color:var(--hse-text-accent);"></i>
              Matriks Sebaran Risiko Sisa (5×5 Likelihood vs Consequence)
            </div>
            <div style="font-size:11px;color:var(--hse-text-secondary);margin-top:2px;">
              Klik pada salah satu sel matriks untuk memfilter daftar register risiko di bawah berdasarkan tingkat kemungkinan dan keparahan.
            </div>
          </div>
          <div class="hse-matrix-legend">
            <span class="hse-legend-item"><span class="hse-legend-dot hse-legend-dot--extreme"></span> Ekstrem (&ge;17)</span>
            <span class="hse-legend-item"><span class="hse-legend-dot hse-legend-dot--high"></span> Tinggi (10-16)</span>
            <span class="hse-legend-item"><span class="hse-legend-dot hse-legend-dot--medium"></span> Sedang (5-9)</span>
            <span class="hse-legend-item"><span class="hse-legend-dot hse-legend-dot--low"></span> Rendah (1-4)</span>
          </div>
        </div>

        ${isMatrixFilterActive ? `
          <div style="display:flex;align-items:center;justify-content:space-between;background:var(--hse-bg-accent);padding:6px 12px;border-radius:6px;font-size:11px;color:var(--hse-text-accent);">
            <span>
              <i class="ti ti-filter" aria-hidden="true"></i> 
              Filter sel matriks aktif: <strong>Kemungkinan L = ${state.riskFilters.cell_l}</strong> &times; <strong>Keparahan C = ${state.riskFilters.cell_c}</strong> (Skor: ${Number(state.riskFilters.cell_l) * Number(state.riskFilters.cell_c)})
            </span>
            <button type="button" class="hse-btn hse-btn--sm" id="btnHseResetRiskMatrixCell" style="font-size:10px;padding:2px 8px;">
              <i class="ti ti-x" aria-hidden="true"></i> Reset Filter Matriks
            </button>
          </div>
        ` : ''}

        <div class="hse-matrix-grid-wrapper">
          <table class="hse-matrix-table">
            <thead>
              <tr>
                <th rowspan="2" class="hse-matrix-th-axis" style="width:140px;">Kemungkinan (L) \\ Keparahan (C)</th>
                <th colspan="5" class="hse-matrix-th-axis">Keparahan / Dampak (Consequence)</th>
              </tr>
              <tr>
                <th class="hse-matrix-th-axis" style="width:17%;">1 - Ringan Sekali</th>
                <th class="hse-matrix-th-axis" style="width:17%;">2 - Ringan</th>
                <th class="hse-matrix-th-axis" style="width:17%;">3 - Sedang</th>
                <th class="hse-matrix-th-axis" style="width:17%;">4 - Berat</th>
                <th class="hse-matrix-th-axis" style="width:17%;">5 - Bencana</th>
              </tr>
            </thead>
            <tbody>
              ${[5, 4, 3, 2, 1].map(l => `
                <tr>
                  <th class="hse-matrix-th-axis" style="text-align:left;padding:6px 8px;font-size:10px;">
                    ${likelihoodNames[l]}
                  </th>
                  ${[1, 2, 3, 4, 5].map(c => {
                    const cell = matrixCells.find(m => m.l === l && m.c === c);
                    return `
                      <td style="padding:3px;">
                        <div class="hse-matrix-cell hse-matrix-cell--${cell.cellCls} ${cell.isSelected ? 'is-selected' : ''}" 
                             data-risk-cell-l="${l}" data-risk-cell-c="${c}" title="Kemungkinan: ${l}, Keparahan: ${c}, Skor: ${cell.score} (${cell.level})">
                          <span class="hse-matrix-cell-score">Skor ${cell.score}</span>
                          ${cell.count > 0 ? `<span class="hse-matrix-cell-count">${cell.count}</span>` : '<span style="font-size:10px;opacity:0.4;">0</span>'}
                        </div>
                      </td>
                    `;
                  }).join('')}
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      </div>

      <!-- HEADER AKSI & FILTER BAR -->
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;">
        <div style="font-size:13px;color:var(--hse-text-secondary);">
          Identifikasi Bahaya, Penilaian Risiko, dan Penentuan Pengendalian (IBPR / HIRADC) berbasis SNI ISO 45001 & Permen ESDM No. 26/2018.
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseOpenCreateRisk">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Register Risiko
        </button>
      </div>

      <div class="hse-filter-bar">
        <input type="text" class="hse-input" id="hseRiskSearch" placeholder="Cari aktivitas, bahaya, dampak, PIC..." value="${ESC(state.riskFilters.search)}" style="min-width:220px;">
        <select class="hse-select" id="hseFilterRiskResidualLevel">
          <option value="">Semua Tingkat Risiko Sisa</option>
          <option value="EXTREME" ${state.riskFilters.residual_level === 'EXTREME' ? 'selected' : ''}>Ekstrem (EXTREME)</option>
          <option value="HIGH" ${state.riskFilters.residual_level === 'HIGH' ? 'selected' : ''}>Tinggi (HIGH)</option>
          <option value="MEDIUM" ${state.riskFilters.residual_level === 'MEDIUM' ? 'selected' : ''}>Sedang (MEDIUM)</option>
          <option value="LOW" ${state.riskFilters.residual_level === 'LOW' ? 'selected' : ''}>Rendah (LOW)</option>
        </select>
        <select class="hse-select" id="hseFilterRiskInitialLevel">
          <option value="">Semua Tingkat Risiko Awal</option>
          <option value="EXTREME" ${state.riskFilters.initial_level === 'EXTREME' ? 'selected' : ''}>Awal: Ekstrem</option>
          <option value="HIGH" ${state.riskFilters.initial_level === 'HIGH' ? 'selected' : ''}>Awal: Tinggi</option>
          <option value="MEDIUM" ${state.riskFilters.initial_level === 'MEDIUM' ? 'selected' : ''}>Awal: Sedang</option>
          <option value="LOW" ${state.riskFilters.initial_level === 'LOW' ? 'selected' : ''}>Awal: Rendah</option>
        </select>
        <select class="hse-select" id="hseFilterRiskStatus">
          <option value="">Semua Status</option>
          <option value="ACTIVE" ${state.riskFilters.status === 'ACTIVE' ? 'selected' : ''}>Aktif (ACTIVE)</option>
          <option value="UNDER_REVIEW" ${state.riskFilters.status === 'UNDER_REVIEW' ? 'selected' : ''}>Perlu Review</option>
          <option value="CLOSED" ${state.riskFilters.status === 'CLOSED' ? 'selected' : ''}>Ditutup</option>
        </select>
      </div>

      <!-- TABEL DAFTAR REGISTER RISIKO -->
      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th style="min-width:110px;">No. Register & Dept</th>
              <th style="min-width:150px;">Aktivitas Operasi</th>
              <th style="min-width:160px;">Bahaya & Dampak</th>
              <th style="text-align:center;min-width:100px;">Risiko Awal</th>
              <th style="min-width:200px;">Hirarki Pengendalian</th>
              <th style="text-align:center;min-width:100px;">Risiko Sisa</th>
              <th style="min-width:110px;">PIC & Review</th>
              <th style="text-align:center;">Status</th>
              <th style="text-align:center;width:70px;">Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${risks.length === 0 ? `
              <tr>
                <td colspan="9" style="text-align:center;padding:28px;color:var(--hse-text-muted);">
                  Belum ada data register risiko (IBPR) yang sesuai filter.
                </td>
              </tr>
            ` : risks.map(r => {
              let parsedControls = [];
              try {
                parsedControls = typeof r.controls === 'string' ? JSON.parse(r.controls) : (r.controls || []);
              } catch (_) { parsedControls = []; }

              return `
                <tr>
                  <td>
                    <div style="font-weight:600;font-family:monospace;font-size:11px;">${ESC(r.risk_no)}</div>
                    <div style="font-size:10px;color:var(--hse-text-secondary);margin-top:2px;">${ESC(r.department_name || '-')}</div>
                  </td>
                  <td>
                    <div style="font-weight:600;">${ESC(r.activity)}</div>
                  </td>
                  <td>
                    <div style="color:var(--hse-text-primary);"><i class="ti ti-alert-triangle" style="color:var(--hse-text-warning);font-size:10px;"></i> ${ESC(r.hazard)}</div>
                    <div style="font-size:11px;color:var(--hse-text-secondary);margin-top:3px;">${ESC(r.consequence_desc)}</div>
                  </td>
                  <td style="text-align:center;">
                    <div>${levelBadge(r.initial_level)}</div>
                    <div style="font-size:10px;color:var(--hse-text-secondary);margin-top:2px;">
                      L:${r.initial_likelihood} &times; C:${r.initial_consequence} (Skor ${r.initial_score})
                    </div>
                  </td>
                  <td>
                    <div style="display:flex;flex-direction:column;gap:3px;">
                      ${parsedControls.map(c => {
                        const hInfo = hierarchyLabels[c.hierarchy] || { label: c.hierarchy, cls: 'engineering' };
                        return `
                          <div class="hse-control-item">
                            <span class="hse-hierarchy-badge hse-hierarchy-badge--${hInfo.cls}">${hInfo.label}</span>
                            <span style="font-size:11px;color:var(--hse-text-primary);">${ESC(c.description)}</span>
                          </div>
                        `;
                      }).join('')}
                    </div>
                  </td>
                  <td style="text-align:center;">
                    <div>${levelBadge(r.residual_level)}</div>
                    <div style="font-size:10px;color:var(--hse-text-secondary);margin-top:2px;">
                      L:${r.residual_likelihood} &times; C:${r.residual_consequence} (Skor ${r.residual_score})
                    </div>
                  </td>
                  <td>
                    <div style="font-weight:500;">${ESC(r.owner_name || '-')}</div>
                    <div style="font-size:10px;color:var(--hse-text-secondary);margin-top:2px;">
                      Rev: ${r.review_date ? ESC(r.review_date.slice(0, 10)) : '-'}
                    </div>
                  </td>
                  <td style="text-align:center;">
                    ${statusBadge(r.status)}
                  </td>
                  <td style="text-align:center;">
                    <button type="button" class="hse-btn hse-btn--sm" data-btn-risk-detail="${r.id}" title="Lihat Detail IBPR">
                      <i class="ti ti-eye" aria-hidden="true"></i>
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function openCreateRiskModal() {
    const calcScore = (l, c) => {
      const score = Number(l) * Number(c);
      let level = 'LOW';
      let cls = 'low';
      let label = 'Rendah';
      if (score >= 17) { level = 'EXTREME'; cls = 'extreme'; label = 'Ekstrem'; }
      else if (score >= 10) { level = 'HIGH'; cls = 'high'; label = 'Tinggi'; }
      else if (score >= 5) { level = 'MEDIUM'; cls = 'medium'; label = 'Sedang'; }
      return { score, level, cls, label };
    };

    state.activeModal = `
      <div class="hse-modal-header">
        <div>
          <div class="hse-modal-title">Tambah Register Risiko (IBPR / HIRADC)</div>
          <div style="font-size:12px;color:var(--hse-text-secondary);margin-top:2px;">
            Identifikasi potensi bahaya, penilaian risiko awal, 5 hirarki kontrol, dan evaluasi risiko sisa.
          </div>
        </div>
        <button type="button" class="hse-modal-close" id="btnHseCloseRiskModal">&times;</button>
      </div>

      <form id="formHseCreateRisk" style="display:flex;flex-direction:column;gap:14px;margin-top:14px;">
        <div class="hse-form-row">
          <div class="hse-form-col">
            <label class="hse-form-label">Aktivitas Operasional <span style="color:var(--hse-text-danger);">*</span></label>
            <input type="text" class="hse-input" id="inRiskActivity" required placeholder="Contoh: Pengisian Bahan Bakar di Fuel Station Pit 3">
          </div>
          <div class="hse-form-col">
            <label class="hse-form-label">Departemen Terkait</label>
            <input type="text" class="hse-input" id="inRiskDept" placeholder="Contoh: Mining Operations / Hauling / Workshop">
          </div>
        </div>

        <div class="hse-form-row">
          <div class="hse-form-col">
            <label class="hse-form-label">Potensi Bahaya (Hazard) <span style="color:var(--hse-text-danger);">*</span></label>
            <textarea class="hse-input hse-form-textarea" id="inRiskHazard" required placeholder="Contoh: Tumpahan hidrokarbon / solar, percikan listrik statis, uap mudah terbakar"></textarea>
          </div>
          <div class="hse-form-col">
            <label class="hse-form-label">Potensi Dampak / Konsekuensi <span style="color:var(--hse-text-danger);">*</span></label>
            <textarea class="hse-input hse-form-textarea" id="inRiskConsequence" required placeholder="Contoh: Kebakaran fuel dispenser, luka bakar berat pada operator, pencemaran tanah"></textarea>
          </div>
        </div>

        <!-- SESI PENILAIAN RISIKO AWAL -->
        <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);border-radius:6px;padding:12px;">
          <div style="font-weight:700;font-size:12px;margin-bottom:8px;color:var(--hse-text-primary);display:flex;align-items:center;gap:6px;">
            <i class="ti ti-chart-bar" style="color:var(--hse-text-warning);"></i> Penilaian Risiko Awal (Sebelum Pengendalian Tambahan)
          </div>
          <div class="hse-form-row" style="align-items:flex-end;">
            <div class="hse-form-col">
              <label class="hse-form-label">Kemungkinan Awal (Likelihood)</label>
              <select class="hse-select" id="inRiskInitL">
                <option value="5">5 - Hampir Pasti (Almost Certain)</option>
                <option value="4" selected>4 - Sering (Likely)</option>
                <option value="3">3 - Dapat Terjadi (Possible)</option>
                <option value="2">2 - Jarang (Unlikely)</option>
                <option value="1">1 - Hampir Tidak Pernah (Rare)</option>
              </select>
            </div>
            <div class="hse-form-col">
              <label class="hse-form-label">Keparahan Awal (Consequence)</label>
              <select class="hse-select" id="inRiskInitC">
                <option value="5">5 - Bencana (Catastrophic)</option>
                <option value="4" selected>4 - Berat (Major)</option>
                <option value="3">3 - Sedang (Moderate)</option>
                <option value="2">2 - Ringan (Minor)</option>
                <option value="1">1 - Ringan Sekali (Insignificant)</option>
              </select>
            </div>
            <div class="hse-form-col" style="flex:0 0 160px;">
              <label class="hse-form-label">Hasil Risiko Awal</label>
              <div id="riskInitDisplay" style="height:36px;display:flex;align-items:center;gap:6px;">
                <span class="hse-badge hse-badge--high" id="riskInitBadge">Tinggi (Skor 16)</span>
              </div>
            </div>
          </div>
        </div>

        <!-- SESI 5 HIRARKI PENGENDALIAN RISIKO -->
        <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);border-radius:6px;padding:12px;">
          <div style="font-weight:700;font-size:12px;margin-bottom:8px;color:var(--hse-text-primary);display:flex;align-items:center;gap:6px;">
            <i class="ti ti-shield-check" style="color:var(--hse-text-accent);"></i> Penetapan 5 Hirarki Pengendalian Risiko
          </div>
          <div style="display:flex;flex-direction:column;gap:8px;">
            <div>
              <label class="hse-form-label"><span class="hse-hierarchy-badge hse-hierarchy-badge--elimination">1. Eliminasi</span> Menghilangkan sumber bahaya secara total</label>
              <input type="text" class="hse-input" id="inCtrlElimination" placeholder="Contoh: Menghilangkan proses pengisian manual wadah terbuka...">
            </div>
            <div>
              <label class="hse-form-label"><span class="hse-hierarchy-badge hse-hierarchy-badge--substitution">2. Substitusi</span> Mengganti zat/alat berbahaya dengan yang lebih aman</label>
              <input type="text" class="hse-input" id="inCtrlSubstitution" placeholder="Contoh: Mengganti fitting pipa plastik dengan baja konduktif...">
            </div>
            <div>
              <label class="hse-form-label"><span class="hse-hierarchy-badge hse-hierarchy-badge--engineering">3. Rekayasa Teknik</span> Isolasi, sensor otomatis, grounding, pembumian</label>
              <input type="text" class="hse-input" id="inCtrlEngineering" placeholder="Contoh: Pemasangan grounding static bonding clamp, shut-off valve darurat otomatis...">
            </div>
            <div>
              <label class="hse-form-label"><span class="hse-hierarchy-badge hse-hierarchy-badge--administrative">4. Administratif</span> SOP, induksi, sertifikasi kompetensi, izin kerja, inspeksi</label>
              <input type="text" class="hse-input" id="inCtrlAdmin" placeholder="Contoh: SOP Refueling No. SOP-MIN-012, larangan merokok & gadget, inspeksi harian...">
            </div>
            <div>
              <label class="hse-form-label"><span class="hse-hierarchy-badge hse-hierarchy-badge--ppe">5. APD (Alat Pelindung Diri)</span> Perlindungan terakhir pekerja</label>
              <input type="text" class="hse-input" id="inCtrlPpe" placeholder="Contoh: Wearpack tahan api/antistatis, kacamata safety, sarung tangan nitril...">
            </div>
          </div>
        </div>

        <!-- SESI PENILAIAN RISIKO SISA -->
        <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);border-radius:6px;padding:12px;">
          <div style="font-weight:700;font-size:12px;margin-bottom:8px;color:var(--hse-text-primary);display:flex;align-items:center;gap:6px;">
            <i class="ti ti-activity" style="color:var(--hse-text-success);"></i> Penilaian Risiko Sisa (Residual Risk Setelah Pengendalian)
          </div>
          <div class="hse-form-row" style="align-items:flex-end;">
            <div class="hse-form-col">
              <label class="hse-form-label">Kemungkinan Sisa (Residual Likelihood)</label>
              <select class="hse-select" id="inRiskResL">
                <option value="5">5 - Hampir Pasti (Almost Certain)</option>
                <option value="4" selected>4 - Sering (Likely)</option>
                <option value="3">3 - Dapat Terjadi (Possible)</option>
                <option value="2">2 - Jarang (Unlikely)</option>
                <option value="1">1 - Hampir Tidak Pernah (Rare)</option>
              </select>
            </div>
            <div class="hse-form-col">
              <label class="hse-form-label">Keparahan Sisa (Residual Consequence)</label>
              <select class="hse-select" id="inRiskResC">
                <option value="5">5 - Bencana (Catastrophic)</option>
                <option value="4">4 - Berat (Major)</option>
                <option value="3" selected>3 - Sedang (Moderate)</option>
                <option value="2">2 - Ringan (Minor)</option>
                <option value="1">1 - Ringan Sekali (Insignificant)</option>
              </select>
            </div>
            <div class="hse-form-col" style="flex:0 0 160px;">
              <label class="hse-form-label">Hasil Risiko Sisa</label>
              <div id="riskResDisplay" style="height:36px;display:flex;align-items:center;gap:6px;">
                <span class="hse-badge hse-badge--medium" id="riskResBadge">Sedang (Skor 6)</span>
              </div>
            </div>
          </div>
        </div>

        <div class="hse-form-row">
          <div class="hse-form-col">
            <label class="hse-form-label">Penanggung Jawab (Owner / PIC)</label>
            <input type="text" class="hse-input" id="inRiskOwner" placeholder="Contoh: Pengawas Fuel Station / Section Head Plant">
          </div>
          <div class="hse-form-col">
            <label class="hse-form-label">Tanggal Review Berikutnya</label>
            <input type="date" class="hse-input" id="inRiskReviewDate">
          </div>
          <div class="hse-form-col">
            <label class="hse-form-label">Status Register</label>
            <select class="hse-select" id="inRiskStatus">
              <option value="ACTIVE" selected>Aktif (ACTIVE)</option>
              <option value="UNDER_REVIEW">Perlu Review (UNDER_REVIEW)</option>
              <option value="CLOSED">Ditutup (CLOSED)</option>
            </select>
          </div>
        </div>

        <div id="hseRiskFormError" class="hse-badge hse-badge--extreme" style="display:none;padding:8px 12px;font-size:11px;"></div>

        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:10px;">
          <button type="button" class="hse-btn" id="btnHseCancelRisk">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitHseRisk">
            <i class="ti ti-check" aria-hidden="true"></i> Simpan Register Risiko
          </button>
        </div>
      </form>
    `;

    render();

    // Wiring modal listeners
    document.getElementById('btnHseCloseRiskModal')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });
    document.getElementById('btnHseCancelRisk')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const updateCalcDisplays = () => {
      const initL = document.getElementById('inRiskInitL')?.value || 4;
      const initC = document.getElementById('inRiskInitC')?.value || 4;
      const initCalc = calcScore(initL, initC);
      const initBadge = document.getElementById('riskInitBadge');
      if (initBadge) {
        initBadge.className = `hse-badge hse-badge--${initCalc.cls}`;
        initBadge.textContent = `${initCalc.label} (Skor ${initCalc.score})`;
      }

      const resL = document.getElementById('inRiskResL')?.value || 2;
      const resC = document.getElementById('inRiskResC')?.value || 3;
      const resCalc = calcScore(resL, resC);
      const resBadge = document.getElementById('riskResBadge');
      if (resBadge) {
        resBadge.className = `hse-badge hse-badge--${resCalc.cls}`;
        resBadge.textContent = `${resCalc.label} (Skor ${resCalc.score})`;
      }
    };

    updateCalcDisplays();

    document.getElementById('inRiskInitL')?.addEventListener('change', updateCalcDisplays);
    document.getElementById('inRiskInitC')?.addEventListener('change', updateCalcDisplays);
    document.getElementById('inRiskResL')?.addEventListener('change', updateCalcDisplays);
    document.getElementById('inRiskResC')?.addEventListener('change', updateCalcDisplays);

    const form = document.getElementById('formHseCreateRisk');
    const submitBtn = document.getElementById('btnSubmitHseRisk');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseRiskFormError');
        if (errEl) errEl.style.display = 'none';

        const controls = [];
        const elim = document.getElementById('inCtrlElimination')?.value.trim();
        if (elim) controls.push({ hierarchy: 'ELIMINATION', description: elim });
        const subs = document.getElementById('inCtrlSubstitution')?.value.trim();
        if (subs) controls.push({ hierarchy: 'SUBSTITUTION', description: subs });
        const eng = document.getElementById('inCtrlEngineering')?.value.trim();
        if (eng) controls.push({ hierarchy: 'ENGINEERING', description: eng });
        const adm = document.getElementById('inCtrlAdmin')?.value.trim();
        if (adm) controls.push({ hierarchy: 'ADMINISTRATIVE', description: adm });
        const ppe = document.getElementById('inCtrlPpe')?.value.trim();
        if (ppe) controls.push({ hierarchy: 'PPE', description: ppe });

        const payload = {
          activity: document.getElementById('inRiskActivity')?.value.trim(),
          department_name: document.getElementById('inRiskDept')?.value.trim() || null,
          hazard: document.getElementById('inRiskHazard')?.value.trim(),
          consequence_desc: document.getElementById('inRiskConsequence')?.value.trim(),
          initial_likelihood: Number(document.getElementById('inRiskInitL')?.value),
          initial_consequence: Number(document.getElementById('inRiskInitC')?.value),
          controls,
          residual_likelihood: Number(document.getElementById('inRiskResL')?.value),
          residual_consequence: Number(document.getElementById('inRiskResC')?.value),
          owner_name: document.getElementById('inRiskOwner')?.value.trim() || null,
          review_date: document.getElementById('inRiskReviewDate')?.value || null,
          status: document.getElementById('inRiskStatus')?.value || 'ACTIVE',
        };

        const work = async () => {
          await api('/risk-register', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadRiskRegisterData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.style.display = 'block'; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.style.display = 'block'; }
          }
        }
      });
    }
  }

  function openRiskDetailModal(riskId) {
    const r = (state.riskRegister || []).find(it => String(it.id) === String(riskId));
    if (!r) return;

    const levelBadge = lvl => {
      const cls = { LOW: 'low', MEDIUM: 'medium', HIGH: 'high', EXTREME: 'extreme' }[lvl] || 'low';
      const label = { LOW: 'Rendah', MEDIUM: 'Sedang', HIGH: 'Tinggi', EXTREME: 'Ekstrem' }[lvl] || lvl;
      return `<span class="hse-badge hse-badge--${cls}">${ESC(label)}</span>`;
    };

    const hierarchyLabels = {
      ELIMINATION: { label: 'Eliminasi', cls: 'elimination' },
      SUBSTITUTION: { label: 'Substitusi', cls: 'substitution' },
      ENGINEERING: { label: 'Rekayasa Teknik', cls: 'engineering' },
      ADMINISTRATIVE: { label: 'Administrasi', cls: 'administrative' },
      PPE: { label: 'APD', cls: 'ppe' },
    };

    let parsedControls = [];
    try {
      parsedControls = typeof r.controls === 'string' ? JSON.parse(r.controls) : (r.controls || []);
    } catch (_) { parsedControls = []; }

    state.activeModal = `
      <div class="hse-modal-header">
        <div>
          <div class="hse-modal-title">
            Register Risiko: ${ESC(r.risk_no)}
            <span class="hse-badge hse-badge--${r.status === 'ACTIVE' ? 'process' : 'closed'}" style="margin-left:6px;vertical-align:middle;">
              ${ESC(r.status)}
            </span>
          </div>
          <div style="font-size:12px;color:var(--hse-text-secondary);margin-top:2px;">
            Departemen: ${ESC(r.department_name || '-')} &bull; Dibuat: ${r.created_at ? ESC(r.created_at.slice(0, 10)) : '-'}
          </div>
        </div>
        <button type="button" class="hse-modal-close" id="btnHseCloseRiskDetailModal">&times;</button>
      </div>

      <div style="display:flex;flex-direction:column;gap:14px;margin-top:14px;">
        <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);padding:10px 12px;border-radius:6px;">
          <div style="font-weight:700;font-size:13px;color:var(--hse-text-primary);">${ESC(r.activity)}</div>
          <div style="margin-top:6px;font-size:12px;">
            <div style="color:var(--hse-text-primary);"><strong>Potensi Bahaya:</strong> ${ESC(r.hazard)}</div>
            <div style="color:var(--hse-text-secondary);margin-top:2px;"><strong>Dampak / Konsekuensi:</strong> ${ESC(r.consequence_desc)}</div>
          </div>
        </div>

        <!-- RISK COMPARISON: INITIAL VS RESIDUAL -->
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
          <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);border-radius:6px;padding:12px;text-align:center;">
            <div style="font-size:11px;color:var(--hse-text-secondary);font-weight:600;margin-bottom:4px;">PENILAIAN RISIKO AWAL</div>
            <div style="margin-bottom:6px;">${levelBadge(r.initial_level)}</div>
            <div style="font-size:14px;font-weight:700;">Skor: ${r.initial_score}</div>
            <div style="font-size:11px;color:var(--hse-text-secondary);margin-top:2px;">
              Kemungkinan: ${r.initial_likelihood} &bull; Keparahan: ${r.initial_consequence}
            </div>
          </div>

          <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);border-radius:6px;padding:12px;text-align:center;">
            <div style="font-size:11px;color:var(--hse-text-secondary);font-weight:600;margin-bottom:4px;">PENILAIAN RISIKO SISA (RESIDUAL)</div>
            <div style="margin-bottom:6px;">${levelBadge(r.residual_level)}</div>
            <div style="font-size:14px;font-weight:700;color:var(--hse-text-success);">Skor: ${r.residual_score}</div>
            <div style="font-size:11px;color:var(--hse-text-secondary);margin-top:2px;">
              Kemungkinan: ${r.residual_likelihood} &bull; Keparahan: ${r.residual_consequence}
            </div>
          </div>
        </div>

        <!-- CONTROLS LIST -->
        <div style="background:var(--hse-surface-1);border:0.5px solid var(--hse-border);border-radius:6px;padding:12px;">
          <div style="font-weight:700;font-size:12px;margin-bottom:8px;color:var(--hse-text-primary);">
            Hirarki Pengendalian yang Diterapkan:
          </div>
          ${parsedControls.length === 0 ? `
            <div style="font-size:11px;color:var(--hse-text-muted);">Belum ada kontrol terdaftar.</div>
          ` : `
            <div style="display:flex;flex-direction:column;gap:6px;">
              ${parsedControls.map(c => {
                const hInfo = hierarchyLabels[c.hierarchy] || { label: c.hierarchy, cls: 'engineering' };
                return `
                  <div style="display:flex;align-items:flex-start;gap:8px;background:var(--hse-surface-2);padding:6px 10px;border-radius:4px;border:0.5px solid var(--hse-border);">
                    <span class="hse-hierarchy-badge hse-hierarchy-badge--${hInfo.cls}">${hInfo.label}</span>
                    <span style="font-size:12px;color:var(--hse-text-primary);">${ESC(c.description)}</span>
                  </div>
                `;
              }).join('')}
            </div>
          `}
        </div>

        <!-- PIC & REVIEW INFO -->
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;font-size:12px;background:var(--hse-surface-1);border:0.5px solid var(--hse-border);border-radius:6px;padding:10px 12px;">
          <div>
            <span style="color:var(--hse-text-secondary);">Penanggung Jawab (Owner):</span>
            <div style="font-weight:600;margin-top:2px;">${ESC(r.owner_name || '-')}</div>
          </div>
          <div>
            <span style="color:var(--hse-text-secondary);">Tanggal Review Berikutnya:</span>
            <div style="font-weight:600;margin-top:2px;">${r.review_date ? ESC(r.review_date.slice(0, 10)) : '-'}</div>
          </div>
        </div>

        <div style="display:flex;justify-content:flex-end;margin-top:10px;">
          <button type="button" class="hse-btn" id="btnHseCloseRiskDetailModal2">Tutup</button>
        </div>
      </div>
    `;

    render();

    document.getElementById('btnHseCloseRiskDetailModal')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });
    document.getElementById('btnHseCloseRiskDetailModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });
  }

  // -------------------------------------------------------------
  // FASE 5: KESEHATAN KERJA (OCCUPATIONAL HEALTH) VIEWS & MODALS
  // -------------------------------------------------------------

  function renderOccHealthView() {
    const isMcu = state.occHealthSubTab === 'mcu';
    const isFfw = state.occHealthSubTab === 'ffw';
    const isSubstance = state.occHealthSubTab === 'substance';
    const isCases = state.occHealthSubTab === 'cases';
    const isHygiene = state.occHealthSubTab === 'hygiene';

    return `
      <div class="hse-subnav">
        <button type="button" class="hse-subnav-btn ${isMcu ? 'is-active' : ''}" data-occ-health-tab="mcu">
          <i class="ti ti-heartbeat" aria-hidden="true"></i> MCU Berkala & Pra-Kerja
        </button>
        <button type="button" class="hse-subnav-btn ${isFfw ? 'is-active' : ''}" data-occ-health-tab="ffw">
          <i class="ti ti-stethoscope" aria-hidden="true"></i> Fit for Work (FFW) Harian
        </button>
        <button type="button" class="hse-subnav-btn ${isSubstance ? 'is-active' : ''}" data-occ-health-tab="substance">
          <i class="ti ti-test-pipe" aria-hidden="true"></i> Tes Narkoba & Alkohol
        </button>
        <button type="button" class="hse-subnav-btn ${isCases ? 'is-active' : ''}" data-occ-health-tab="cases">
          <i class="ti ti-first-aid-kit" aria-hidden="true"></i> Kasus Klinik & PAK
        </button>
        <button type="button" class="hse-subnav-btn ${isHygiene ? 'is-active' : ''}" data-occ-health-tab="hygiene">
          <i class="ti ti-activity" aria-hidden="true"></i> Higiene Industri (NAB)
        </button>
      </div>

      ${isMcu ? renderOccHealthMcuTab() : (
        isFfw ? renderOccHealthFfwTab() : (
          isSubstance ? renderOccHealthSubstanceTab() : (
            isCases ? renderOccHealthCasesTab() : renderOccHealthHygieneTab()
          )
        )
      )}
    `;
  }

  function renderOccHealthMcuTab() {
    const records = state.mcuRecords || [];
    const stats = state.occHealthOverview?.mcu || {
      total_mcu: records.length,
      fit_count: records.filter(r => r.fit_status === 'FIT').length,
      fit_notes_count: records.filter(r => r.fit_status === 'FIT_WITH_NOTES').length,
      unfit_count: records.filter(r => ['TEMP_UNFIT', 'UNFIT'].includes(r.fit_status)).length,
      expiring_count: records.filter(r => r.validity_status === 'EXPIRING').length,
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total MCU</span>
          <span class="hse-stat-pill-val">${stats.total_mcu}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Layak (Fit)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.fit_count}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Layak dg Catatan</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);">${stats.fit_notes_count}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.unfit_count > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.unfit_count > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:${stats.unfit_count > 0 ? 'var(--hse-text-danger)' : 'inherit'};">Tidak Layak (Unfit)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.unfit_count}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Segera Berakhir (&le; 30 hari)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);">${stats.expiring_count}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseMcuSearch" placeholder="Cari nama karyawan, NIK, fasilitas medis..." value="${ESC(state.mcuFilters.search)}">
          <select class="hse-filter-select" id="hseFilterMcuType">
            <option value="">Semua Jenis MCU</option>
            <option value="PRE_EMPLOYMENT" ${state.mcuFilters.mcu_type === 'PRE_EMPLOYMENT' ? 'selected' : ''}>Pra-Kerja (Pre-Employment)</option>
            <option value="PERIODIC" ${state.mcuFilters.mcu_type === 'PERIODIC' ? 'selected' : ''}>Berkala (Periodic)</option>
            <option value="SPECIAL" ${state.mcuFilters.mcu_type === 'SPECIAL' ? 'selected' : ''}>Khusus (Special)</option>
            <option value="EXIT" ${state.mcuFilters.mcu_type === 'EXIT' ? 'selected' : ''}>Akhir Kerja (Exit)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterMcuFit">
            <option value="">Semua Hasil Kelayakan</option>
            <option value="FIT" ${state.mcuFilters.fit_status === 'FIT' ? 'selected' : ''}>FIT (Layak)</option>
            <option value="FIT_WITH_NOTES" ${state.mcuFilters.fit_status === 'FIT_WITH_NOTES' ? 'selected' : ''}>FIT WITH NOTES (Layak dg Catatan)</option>
            <option value="TEMP_UNFIT" ${state.mcuFilters.fit_status === 'TEMP_UNFIT' ? 'selected' : ''}>TEMP UNFIT (Sementara)</option>
            <option value="UNFIT" ${state.mcuFilters.fit_status === 'UNFIT' ? 'selected' : ''}>UNFIT (Tidak Layak)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddMcu">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat MCU Baru
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Pekerja</th>
              <th>Departemen / Posisi</th>
              <th>Jenis MCU</th>
              <th>Tanggal Periksa</th>
              <th>Masa Berlaku</th>
              <th>Status Masa Berlaku</th>
              <th>Kelayakan Medis</th>
              <th>Pembatasan Kerja</th>
              <th>Fasilitas / Dokter</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${records.length === 0 ? `
              <tr>
                <td colspan="10" style="text-align:center;padding:24px;color:var(--hse-text-muted);">
                  Belum ada catatan Medical Check Up (MCU) yang sesuai.
                </td>
              </tr>
            ` : records.map(r => {
              const fitCls = {
                FIT: 'success',
                FIT_WITH_NOTES: 'warning',
                TEMP_UNFIT: 'danger',
                UNFIT: 'danger'
              }[r.fit_status] || 'accent';
              const valCls = {
                VALID: 'success',
                EXPIRING: 'warning',
                EXPIRED: 'danger'
              }[r.validity_status] || 'accent';

              return `
                <tr>
                  <td>
                    <strong>${ESC(r.employee_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(r.employee_nrp || '')}</div>
                  </td>
                  <td>
                    <div>${ESC(r.department_name || '-')}</div>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(r.position_name || '')}</div>
                  </td>
                  <td><span class="hse-badge hse-badge--accent">${ESC(r.mcu_type)}</span></td>
                  <td>${ESC(String(r.mcu_date).slice(0, 10))}</td>
                  <td>${ESC(String(r.valid_until).slice(0, 10))}</td>
                  <td><span class="hse-badge hse-badge--${valCls}">${ESC(r.validity_status || 'VALID')}</span></td>
                  <td><span class="hse-badge hse-badge--${fitCls}">${ESC(r.fit_status)}</span></td>
                  <td>${r.work_restrictions ? `<span style="color:var(--hse-text-warning);font-weight:500;">${ESC(r.work_restrictions)}</span>` : '<span style="color:var(--hse-text-muted);">-</span>'}</td>
                  <td>
                    <div>${ESC(r.medical_facility || '-')}</div>
                    <small style="color:var(--hse-text-muted);">${ESC(r.examiner_doctor || '')}</small>
                  </td>
                  <td>
                    <button type="button" class="hse-btn" data-btn-mcu-edit="${r.id}" style="padding:2px 8px;font-size:11px;">
                      <i class="ti ti-edit" aria-hidden="true"></i> Edit
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderOccHealthFfwTab() {
    const checks = state.ffwChecks || [];
    const stats = state.occHealthOverview?.ffw || {
      total_checks: checks.length,
      fit_count: checks.filter(c => c.overall_result === 'FIT').length,
      unfit_count: checks.filter(c => c.overall_result === 'UNFIT').length,
      fatigue_risk_count: checks.filter(c => Number(c.sleep_hours) < 5.0).length,
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Skrining Hari Ini</span>
          <span class="hse-stat-pill-val">${stats.total_checks}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Layak Operasi (Fit)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.fit_count}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.unfit_count > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.unfit_count > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:${stats.unfit_count > 0 ? 'var(--hse-text-danger)' : 'inherit'};">Tidak Layak (Unfit)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.unfit_count}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.fatigue_risk_count > 0 ? 'var(--hse-fill-warning)' : 'var(--hse-border)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Risiko Fatigue (&lt; 5 Jam)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);font-weight:700;">${stats.fatigue_risk_count}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseFfwSearch" placeholder="Cari pekerja, NIK, pemeriksa..." value="${ESC(state.ffwFilters.search)}">
          <select class="hse-filter-select" id="hseFilterFfwShift">
            <option value="">Semua Shift</option>
            <option value="SHIFT_1" ${state.ffwFilters.shift === 'SHIFT_1' ? 'selected' : ''}>Shift 1 (Pagi/Siang)</option>
            <option value="SHIFT_2" ${state.ffwFilters.shift === 'SHIFT_2' ? 'selected' : ''}>Shift 2 (Malam)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterFfwResult">
            <option value="">Semua Hasil</option>
            <option value="FIT" ${state.ffwFilters.overall_result === 'FIT' ? 'selected' : ''}>FIT (Layak)</option>
            <option value="TEMPORARY_FIT" ${state.ffwFilters.overall_result === 'TEMPORARY_FIT' ? 'selected' : ''}>TEMPORARY FIT (Observasi)</option>
            <option value="UNFIT" ${state.ffwFilters.overall_result === 'UNFIT' ? 'selected' : ''}>UNFIT (Tidak Layak)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddFfw">
          <i class="ti ti-plus" aria-hidden="true"></i> Skrining FFW Harian
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Waktu & Shift</th>
              <th>Pekerja</th>
              <th>Departemen</th>
              <th>Jam Tidur</th>
              <th>Tanda Vital (TD / Nadi / Suhu)</th>
              <th>Gejala Sakit</th>
              <th>Hasil Skrining</th>
              <th>Tindakan / Rekomendasi</th>
              <th>Pemeriksa</th>
            </tr>
          </thead>
          <tbody>
            ${checks.length === 0 ? `
              <tr>
                <td colspan="9" style="text-align:center;padding:24px;color:var(--hse-text-muted);">
                  Belum ada pemeriksaan Fit for Work pada periode ini.
                </td>
              </tr>
            ` : checks.map(c => {
              const resCls = { FIT: 'success', TEMPORARY_FIT: 'warning', UNFIT: 'danger' }[c.overall_result] || 'accent';
              const isFatigue = Number(c.sleep_hours) < 5.0;

              return `
                <tr>
                  <td>
                    <strong>${ESC(String(c.check_date).slice(0, 10))}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(c.shift || 'SHIFT_1')}</div>
                  </td>
                  <td>
                    <strong>${ESC(c.employee_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(c.employee_nrp || '')}</div>
                  </td>
                  <td>${ESC(c.department_name || '-')}</td>
                  <td>
                    <span style="font-weight:600;color:${isFatigue ? 'var(--hse-text-danger)' : 'inherit'};">
                      ${c.sleep_hours != null ? `${c.sleep_hours} Jam` : '-'}
                    </span>
                    ${isFatigue ? `<span class="hse-badge hse-badge--extreme" style="font-size:9px;margin-left:4px;">FATIGUE</span>` : ''}
                  </td>
                  <td>
                    <div>TD: ${c.blood_pressure_systolic ? `${c.blood_pressure_systolic}/${c.blood_pressure_diastolic} mmHg` : '-'}</div>
                    <div style="font-size:10px;color:var(--hse-text-muted);">Nadi: ${c.heart_rate_bpm ? `${c.heart_rate_bpm} bpm` : '-'} · Suhu: ${c.body_temp_celsius ? `${c.body_temp_celsius}°C` : '-'}</div>
                  </td>
                  <td>
                    ${c.has_symptoms ? `<span class="hse-badge hse-badge--warning" title="${ESC(c.symptoms_desc || '')}">Ada Gejala</span>` : '<span style="color:var(--hse-text-success);font-weight:500;">Nihil</span>'}
                  </td>
                  <td><span class="hse-badge hse-badge--${resCls}">${ESC(c.overall_result)}</span></td>
                  <td style="max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${ESC(c.action_taken || '-')}">
                    ${ESC(c.action_taken || '-')}
                  </td>
                  <td>${ESC(c.checker_name || '-')}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderOccHealthSubstanceTab() {
    const tests = state.substanceTests || [];
    const stats = state.occHealthOverview?.substance || {
      total_tests: tests.length,
      negative_count: tests.filter(t => t.overall_result === 'NEGATIVE').length,
      positive_count: tests.filter(t => t.overall_result === 'POSITIVE').length,
      random_count: tests.filter(t => t.test_type === 'RANDOM').length,
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Tes Zat</span>
          <span class="hse-stat-pill-val">${stats.total_tests}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Negatif (Bersih)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.negative_count}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.positive_count > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.positive_count > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:${stats.positive_count > 0 ? 'var(--hse-text-danger)' : 'inherit'};">Positif Terindikasi</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.positive_count}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Uji Acak (Random)</span>
          <span class="hse-stat-pill-val">${stats.random_count}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseSubstanceSearch" placeholder="Cari pekerja, NIK, pemeriksa..." value="${ESC(state.substanceFilters.search)}">
          <select class="hse-filter-select" id="hseFilterSubstanceType">
            <option value="">Semua Jenis Tes</option>
            <option value="RANDOM" ${state.substanceFilters.test_type === 'RANDOM' ? 'selected' : ''}>Acak (Random)</option>
            <option value="PRE_EMPLOYMENT" ${state.substanceFilters.test_type === 'PRE_EMPLOYMENT' ? 'selected' : ''}>Pra-Kerja</option>
            <option value="POST_INCIDENT" ${state.substanceFilters.test_type === 'POST_INCIDENT' ? 'selected' : ''}>Pasca Insiden (Post-Incident)</option>
            <option value="FOR_CAUSE" ${state.substanceFilters.test_type === 'FOR_CAUSE' ? 'selected' : ''}>Kecurigaan (For Cause)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterSubstanceResult">
            <option value="">Semua Hasil</option>
            <option value="NEGATIVE" ${state.substanceFilters.overall_result === 'NEGATIVE' ? 'selected' : ''}>NEGATIVE (Negatif)</option>
            <option value="POSITIVE" ${state.substanceFilters.overall_result === 'POSITIVE' ? 'selected' : ''}>POSITIVE (Positif)</option>
            <option value="INCONCLUSIVE" ${state.substanceFilters.overall_result === 'INCONCLUSIVE' ? 'selected' : ''}>INCONCLUSIVE (Ulangi)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddSubstance">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat Tes Baru
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Tanggal</th>
              <th>Pekerja</th>
              <th>Departemen</th>
              <th>Jenis & Alasan Tes</th>
              <th>Breathalyzer (Alkohol)</th>
              <th>Tes Urin 6-Panel (Narkoba)</th>
              <th>Hasil Akhir</th>
              <th>Petugas & Saksi</th>
              <th>Tindakan Lanjut</th>
            </tr>
          </thead>
          <tbody>
            ${tests.length === 0 ? `
              <tr>
                <td colspan="9" style="text-align:center;padding:24px;color:var(--hse-text-muted);">
                  Belum ada catatan tes alkohol atau narkoba.
                </td>
              </tr>
            ` : tests.map(t => {
              const resCls = t.overall_result === 'NEGATIVE' ? 'success' : (t.overall_result === 'POSITIVE' ? 'danger' : 'warning');
              return `
                <tr>
                  <td><strong>${ESC(String(t.test_date).slice(0, 10))}</strong></td>
                  <td>
                    <strong>${ESC(t.employee_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(t.employee_nrp || '')}</div>
                  </td>
                  <td>${ESC(t.department_name || '-')}</td>
                  <td>
                    <span class="hse-badge hse-badge--accent">${ESC(t.test_type)}</span>
                    ${t.reason ? `<div style="font-size:10px;color:var(--hse-text-muted);margin-top:2px;">${ESC(t.reason)}</div>` : ''}
                  </td>
                  <td>
                    <span style="font-weight:600;color:${Number(t.breathalyzer_level) > 0 ? 'var(--hse-text-danger)' : 'var(--hse-text-success)'};">
                      ${t.breathalyzer_level != null ? `${t.breathalyzer_level} mg/L` : '0.00'}
                    </span>
                  </td>
                  <td><span class="hse-badge hse-badge--${t.urine_drug_result === 'NEGATIVE' ? 'success' : 'danger'}">${ESC(t.urine_drug_result || '-')}</span></td>
                  <td><span class="hse-badge hse-badge--${resCls}">${ESC(t.overall_result)}</span></td>
                  <td>
                    <div>${ESC(t.tester_name || '-')}</div>
                    ${t.witness_name ? `<small style="color:var(--hse-text-muted);">Saksi: ${ESC(t.witness_name)}</small>` : ''}
                  </td>
                  <td style="max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${ESC(t.action_taken || '-')}">
                    ${ESC(t.action_taken || '-')}
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderOccHealthCasesTab() {
    const cases = state.healthCases || [];
    const stats = state.occHealthOverview?.cases || {
      total_cases: cases.length,
      open_cases: cases.filter(c => ['OPEN', 'MONITORING'].includes(c.status)).length,
      pak_cases: cases.filter(c => ['WORK_RELATED', 'SUSPECTED_OD'].includes(c.case_type)).length,
      lost_workdays: cases.reduce((acc, c) => acc + (Number(c.lost_workdays) || 0), 0),
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Kunjungan / Kasus</span>
          <span class="hse-stat-pill-val">${stats.total_cases}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.open_cases > 0 ? 'var(--hse-fill-warning)' : 'var(--hse-border)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Dalam Pemantauan</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);font-weight:700;">${stats.open_cases}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.pak_cases > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.pak_cases > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:${stats.pak_cases > 0 ? 'var(--hse-text-danger)' : 'inherit'};">Kasus Terkait Kerja / PAK</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.pak_cases}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Hari Kerja Hilang</span>
          <span class="hse-stat-pill-val">${stats.lost_workdays} Hari</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseHealthCaseSearch" placeholder="Cari no kasus, nama, keluhan..." value="${ESC(state.healthCaseFilters.search)}">
          <select class="hse-filter-select" id="hseFilterHealthCaseType">
            <option value="">Semua Kategori</option>
            <option value="ILLNESS" ${state.healthCaseFilters.case_type === 'ILLNESS' ? 'selected' : ''}>Penyakit Umum (Illness)</option>
            <option value="INJURY" ${state.healthCaseFilters.case_type === 'INJURY' ? 'selected' : ''}>Cedera Kerja Ringan (Injury)</option>
            <option value="WORK_RELATED" ${state.healthCaseFilters.case_type === 'WORK_RELATED' ? 'selected' : ''}>Terkait Pekerjaan (Work-Related)</option>
            <option value="SUSPECTED_OD" ${state.healthCaseFilters.case_type === 'SUSPECTED_OD' ? 'selected' : ''}>Suspek PAK (Occupational Disease)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterHealthCaseStatus">
            <option value="">Semua Status</option>
            <option value="OPEN" ${state.healthCaseFilters.status === 'OPEN' ? 'selected' : ''}>OPEN (Baru)</option>
            <option value="MONITORING" ${state.healthCaseFilters.status === 'MONITORING' ? 'selected' : ''}>MONITORING (Pantau)</option>
            <option value="CLOSED" ${state.healthCaseFilters.status === 'CLOSED' ? 'selected' : ''}>CLOSED (Selesai/Sembuh)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddHealthCase">
          <i class="ti ti-plus" aria-hidden="true"></i> Lapor Kasus Kesehatan
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>No Kasus</th>
              <th>Tanggal</th>
              <th>Pekerja</th>
              <th>Departemen</th>
              <th>Kategori</th>
              <th>Keluhan Utama & Diagnosis</th>
              <th>Hari Hilang</th>
              <th>Status</th>
              <th>Tenaga Medis</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${cases.length === 0 ? `
              <tr>
                <td colspan="10" style="text-align:center;padding:24px;color:var(--hse-text-muted);">
                  Belum ada data kunjungan klinik atau kasus kesehatan kerja.
                </td>
              </tr>
            ` : cases.map(c => {
              const stCls = { OPEN: 'danger', MONITORING: 'warning', CLOSED: 'closed' }[c.status] || 'accent';
              const typeCls = ['WORK_RELATED', 'SUSPECTED_OD'].includes(c.case_type) ? 'danger' : 'accent';

              return `
                <tr>
                  <td><strong>${ESC(c.case_no)}</strong></td>
                  <td>${ESC(String(c.visit_date).slice(0, 10))}</td>
                  <td>
                    <strong>${ESC(c.employee_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(c.employee_nrp || '')}</div>
                  </td>
                  <td>${ESC(c.department_name || '-')}</td>
                  <td><span class="hse-badge hse-badge--${typeCls}">${ESC(c.case_type)}</span></td>
                  <td>
                    <div><strong>${ESC(c.chief_complaint || '-')}</strong></div>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(c.diagnosis || 'Diagnosis kerja belum disimpulkan')}</div>
                  </td>
                  <td style="text-align:center;">
                    <span style="font-weight:600;color:${Number(c.lost_workdays) > 0 ? 'var(--hse-text-danger)' : 'inherit'};">
                      ${Number(c.lost_workdays) || 0}
                    </span>
                  </td>
                  <td><span class="hse-badge hse-badge--${stCls}">${ESC(c.status)}</span></td>
                  <td>${ESC(c.medical_staff_name || '-')}</td>
                  <td>
                    <button type="button" class="hse-btn" data-btn-health-case-edit="${c.id}" style="padding:2px 8px;font-size:11px;">
                      <i class="ti ti-edit" aria-hidden="true"></i> Update
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderOccHealthHygieneTab() {
    const measurements = state.hygieneMeasurements || [];
    const stats = state.occHealthOverview?.hygiene || {
      total_measurements: measurements.length,
      exceeded_count: measurements.filter(m => m.nab_status === 'EXCEEDED').length,
      near_limit_count: measurements.filter(m => m.nab_status === 'NEAR_LIMIT').length,
      ok_count: measurements.filter(m => m.nab_status === 'OK').length,
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Titik Pemantauan</span>
          <span class="hse-stat-pill-val">${stats.total_measurements}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.exceeded_count > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.exceeded_count > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:${stats.exceeded_count > 0 ? 'var(--hse-text-danger)' : 'inherit'};">Melebihi NAB (Bahaya)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.exceeded_count}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Mendekati NAB (&ge; 85%)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);">${stats.near_limit_count}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Aman (Sesuai NAB)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.ok_count}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseHygieneSearch" placeholder="Cari titik lokasi / rekomendasi..." value="${ESC(state.hygieneFilters.search)}">
          <select class="hse-filter-select" id="hseFilterHygieneParam">
            <option value="">Semua Parameter Bahaya</option>
            <option value="NOISE" ${state.hygieneFilters.parameter === 'NOISE' ? 'selected' : ''}>Kebisingan (Noise)</option>
            <option value="DUST" ${state.hygieneFilters.parameter === 'DUST' ? 'selected' : ''}>Debu Tambang (Dust)</option>
            <option value="LIGHTING" ${state.hygieneFilters.parameter === 'LIGHTING' ? 'selected' : ''}>Pencahayaan (Lighting)</option>
            <option value="VIBRATION" ${state.hygieneFilters.parameter === 'VIBRATION' ? 'selected' : ''}>Getaran (Vibration)</option>
            <option value="HEAT" ${state.hygieneFilters.parameter === 'HEAT' ? 'selected' : ''}>Iklim Kerja Panas (ISBB)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterHygieneNab">
            <option value="">Semua Status NAB</option>
            <option value="OK" ${state.hygieneFilters.nab_status === 'OK' ? 'selected' : ''}>OK (Aman)</option>
            <option value="NEAR_LIMIT" ${state.hygieneFilters.nab_status === 'NEAR_LIMIT' ? 'selected' : ''}>NEAR LIMIT (Waspada)</option>
            <option value="EXCEEDED" ${state.hygieneFilters.nab_status === 'EXCEEDED' ? 'selected' : ''}>EXCEEDED (Melampaui)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddHygiene">
          <i class="ti ti-plus" aria-hidden="true"></i> Input Pengukuran Higiene
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Tanggal</th>
              <th>Lokasi / Titik Ukur</th>
              <th>Parameter Lingkungan</th>
              <th>Nilai Terukur</th>
              <th>Batas NAB</th>
              <th>Evaluasi Status NAB</th>
              <th>Paparan Jam/Hari</th>
              <th>Rekomendasi Rekayasa / APD</th>
              <th>Petugas Pengukur</th>
            </tr>
          </thead>
          <tbody>
            ${measurements.length === 0 ? `
              <tr>
                <td colspan="9" style="text-align:center;padding:24px;color:var(--hse-text-muted);">
                  Belum ada catatan pengukuran higiene industri lingkungan kerja.
                </td>
              </tr>
            ` : measurements.map(m => {
              const nabCls = {
                OK: 'success',
                NEAR_LIMIT: 'warning',
                EXCEEDED: 'extreme'
              }[m.nab_status] || 'accent';

              return `
                <tr>
                  <td><strong>${ESC(String(m.measurement_date).slice(0, 10))}</strong></td>
                  <td><strong>${ESC(m.location_name || '-')}</strong></td>
                  <td><span class="hse-badge hse-badge--accent">${ESC(m.parameter)}</span></td>
                  <td>
                    <span style="font-weight:700;font-size:13px;color:${m.nab_status === 'EXCEEDED' ? 'var(--hse-text-danger)' : 'inherit'};">
                      ${m.measured_value} ${ESC(m.unit || '')}
                    </span>
                  </td>
                  <td>${m.threshold_nab != null ? `${m.threshold_nab} ${ESC(m.unit || '')}` : '-'}</td>
                  <td><span class="hse-badge hse-badge--${nabCls}">${ESC(m.nab_status)}</span></td>
                  <td>${m.exposure_duration_hours != null ? `${m.exposure_duration_hours} jam` : '-'}</td>
                  <td style="max-width:220px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${ESC(m.corrective_action || m.notes || '-')}">
                    ${ESC(m.corrective_action || m.notes || '-')}
                  </td>
                  <td>${ESC(m.measured_by_name || '-')}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  // --- OCCUPATIONAL HEALTH MODALS CONTROLLERS ---

  function openCreateMcuModal(rec = null) {
    const isEdit = Boolean(rec && rec.id);
    const emps = state.masters.employees || [];
    const today = new Date().toISOString().slice(0, 10);
    const nextYear = new Date(Date.now() + 365 * 86400000).toISOString().slice(0, 10);

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">${isEdit ? 'Perbarui Hasil Pemeriksaan MCU' : 'Catat Medical Check Up (MCU) Baru'}</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseMcuRecord" style="margin-top:12px;">
        <div class="hse-form-group">
          <label class="hse-form-label">Pilih Karyawan *</label>
          <select class="hse-form-select" id="inMcuEmpId" required ${isEdit ? 'disabled' : ''}>
            <option value="">Pilih Karyawan...</option>
            ${emps.map(e => `
              <option value="${e.id}" ${(rec && rec.employee_id === e.id) ? 'selected' : ''}>
                ${ESC(e.nama)} (${ESC(e.nrp || e.nik || 'No-NRP')}) - ${ESC(e.jabatan || '')}
              </option>
            `).join('')}
          </select>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Jenis Pemeriksaan MCU *</label>
            <select class="hse-form-select" id="inMcuType" required>
              <option value="PERIODIC" ${(!rec || rec.mcu_type === 'PERIODIC') ? 'selected' : ''}>Berkala (Periodic)</option>
              <option value="PRE_EMPLOYMENT" ${(rec && rec.mcu_type === 'PRE_EMPLOYMENT') ? 'selected' : ''}>Pra-Kerja (Pre-Employment)</option>
              <option value="SPECIAL" ${(rec && rec.mcu_type === 'SPECIAL') ? 'selected' : ''}>Khusus (Special)</option>
              <option value="EXIT" ${(rec && rec.mcu_type === 'EXIT') ? 'selected' : ''}>Akhir Kerja (Exit)</option>
            </select>
          </div>
          <div>
            <label class="hse-form-label">Hasil Kelayakan Medis *</label>
            <select class="hse-form-select" id="inMcuFitStatus" required>
              <option value="FIT" ${(!rec || rec.fit_status === 'FIT') ? 'selected' : ''}>FIT (Layak Penuh)</option>
              <option value="FIT_WITH_NOTES" ${(rec && rec.fit_status === 'FIT_WITH_NOTES') ? 'selected' : ''}>FIT WITH NOTES (Layak dg Pembatasan)</option>
              <option value="TEMP_UNFIT" ${(rec && rec.fit_status === 'TEMP_UNFIT') ? 'selected' : ''}>TEMP UNFIT (Sementara Tidak Layak)</option>
              <option value="UNFIT" ${(rec && rec.fit_status === 'UNFIT') ? 'selected' : ''}>UNFIT (Tidak Layak Kerja Tambang)</option>
            </select>
          </div>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tanggal Pelaksanaan MCU *</label>
            <input type="date" class="hse-form-input" id="inMcuDate" value="${rec ? String(rec.mcu_date).slice(0, 10) : today}" required>
          </div>
          <div>
            <label class="hse-form-label">Masa Berlaku Hingga *</label>
            <input type="date" class="hse-form-input" id="inMcuValidUntil" value="${rec ? String(rec.valid_until).slice(0, 10) : nextYear}" required>
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Pembatasan Pekerjaan (Work Restrictions)</label>
          <input type="text" class="hse-form-input" id="inMcuRestrictions" placeholder="Contoh: Tidak boleh bekerja di ketinggian &gt; 2 meter, wajib kacamata koreksi" value="${ESC(rec?.work_restrictions || '')}">
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Fasilitas Kesehatan / Provider MCU</label>
            <input type="text" class="hse-form-input" id="inMcuFacility" placeholder="Klinik Site / Pramita / Bio Medika" value="${ESC(rec?.medical_facility || '')}">
          </div>
          <div>
            <label class="hse-form-label">Dokter Pemeriksa / Hiperkes</label>
            <input type="text" class="hse-form-input" id="inMcuDoctor" placeholder="dr. Pemeriksa Terakreditasi" value="${ESC(rec?.examiner_doctor || '')}">
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Catatan Kesehatan / Rekomendasi Medis</label>
          <textarea class="hse-form-textarea" id="inMcuNotes" placeholder="Catatan medis non-konfidensial / follow-up...">${ESC(rec?.notes || '')}</textarea>
        </div>

        <div id="hseMcuFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitMcu">${isEdit ? 'Simpan Perubahan' : 'Simpan Data MCU'}</button>
        </div>
      </form>
    `;

    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const form = document.getElementById('formHseMcuRecord');
    const submitBtn = document.getElementById('btnSubmitMcu');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseMcuFormError');
        if (errEl) errEl.hidden = true;

        const payload = {
          employee_id: document.getElementById('inMcuEmpId')?.value || rec?.employee_id,
          mcu_type: document.getElementById('inMcuType')?.value,
          fit_status: document.getElementById('inMcuFitStatus')?.value,
          mcu_date: document.getElementById('inMcuDate')?.value,
          valid_until: document.getElementById('inMcuValidUntil')?.value,
          work_restrictions: document.getElementById('inMcuRestrictions')?.value.trim() || null,
          medical_facility: document.getElementById('inMcuFacility')?.value.trim() || null,
          examiner_doctor: document.getElementById('inMcuDoctor')?.value.trim() || null,
          notes: document.getElementById('inMcuNotes')?.value.trim() || null,
        };

        const work = async () => {
          if (isEdit) {
            await api(`/health/mcu/${rec.id}`, { method: 'PUT', body: payload });
          } else {
            await api('/health/mcu', { method: 'POST', body: payload });
          }
          state.activeModal = null;
          await loadOccHealthData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

  function openCreateFfwModal() {
    const emps = state.masters.employees || [];
    const today = new Date().toISOString().slice(0, 10);

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">Skrining Fit for Work (FFW) Harian Pra-Shift</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseFfwCheck" style="margin-top:12px;">
        <div class="hse-form-group">
          <label class="hse-form-label">Pilih Pekerja *</label>
          <select class="hse-form-select" id="inFfwEmpId" required>
            <option value="">Pilih Pekerja Operasional...</option>
            ${emps.map(e => `
              <option value="${e.id}">${ESC(e.nama)} (${ESC(e.nrp || e.nik || 'No-NRP')}) - ${ESC(e.jabatan || '')}</option>
            `).join('')}
          </select>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tanggal Skrining *</label>
            <input type="date" class="hse-form-input" id="inFfwDate" value="${today}" required>
          </div>
          <div>
            <label class="hse-form-label">Shift Operasional *</label>
            <select class="hse-form-select" id="inFfwShift" required>
              <option value="SHIFT_1">Shift 1 (Pagi / Siang)</option>
              <option value="SHIFT_2">Shift 2 (Malam)</option>
            </select>
          </div>
        </div>

        <div class="hse-form-group" style="background:var(--hse-surface-1);padding:10px;border-radius:6px;border:0.5px solid var(--hse-border);">
          <label class="hse-form-label" style="font-weight:600;">Jumlah Jam Tidur / Istirahat Sebelum Shift *</label>
          <div style="display:flex;align-items:center;gap:10px;">
            <input type="number" step="0.5" min="0" max="24" class="hse-form-input" id="inFfwSleep" value="7.0" style="max-width:120px;" required>
            <span style="font-size:12px;color:var(--hse-text-secondary);">Jam</span>
          </div>
          <div id="hseFfwFatigueAlert" style="margin-top:6px;font-size:11px;color:var(--hse-text-danger);font-weight:600;" hidden>
            <i class="ti ti-alert-triangle" aria-hidden="true"></i> PERINGATAN FATIGUE: Tidur &lt; 5 jam. Operator otomatis Tidak Layak Kerja (UNFIT).
          </div>
        </div>

        <div style="font-weight:600;font-size:12px;margin-top:10px;margin-bottom:6px;">Pemeriksaan Tanda-Tanda Vital:</div>
        <div class="hse-form-row" style="margin-bottom:6px;">
          <div>
            <label class="hse-form-label">Tekanan Darah Sistolik (mmHg)</label>
            <input type="number" class="hse-form-input" id="inFfwBpSys" placeholder="120" min="60" max="250">
          </div>
          <div>
            <label class="hse-form-label">Tekanan Darah Diastolik (mmHg)</label>
            <input type="number" class="hse-form-input" id="inFfwBpDia" placeholder="80" min="40" max="160">
          </div>
        </div>
        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Denyut Nadi (bpm)</label>
            <input type="number" class="hse-form-input" id="inFfwPulse" placeholder="75" min="40" max="180">
          </div>
          <div>
            <label class="hse-form-label">Suhu Tubuh (°C)</label>
            <input type="number" step="0.1" class="hse-form-input" id="inFfwTemp" placeholder="36.5" min="34" max="42">
          </div>
        </div>

        <div class="hse-form-group" style="margin-top:10px;">
          <label style="display:flex;align-items:center;gap:6px;font-size:12px;cursor:pointer;">
            <input type="checkbox" id="chkFfwSymptoms">
            <span>Pekerja menyatakan ada gejala sakit (pusing, mual, demam, flu berat)</span>
          </label>
          <div id="wrapFfwSymptoms" style="margin-top:6px;display:none;">
            <input type="text" class="hse-form-input" id="inFfwSymptomsDesc" placeholder="Jelaskan keluhan sakit yang dirasakan...">
          </div>
        </div>

        <div class="hse-form-row" style="margin-top:10px;">
          <div>
            <label class="hse-form-label">Kesimpulan Kelayakan FFW *</label>
            <select class="hse-form-select" id="inFfwResult" required>
              <option value="FIT">FIT (Layak Kerja Penuh)</option>
              <option value="TEMPORARY_FIT">TEMPORARY FIT (Observasi / Istirahat 30 Menit)</option>
              <option value="UNFIT">UNFIT (Tidak Layak Kerja)</option>
            </select>
          </div>
          <div>
            <label class="hse-form-label">Petugas Pemeriksa / Medic *</label>
            <input type="text" class="hse-form-input" id="inFfwChecker" placeholder="Paramedic / Pengawas Site" required>
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Tindakan / Rekomendasi Penanganan</label>
          <input type="text" class="hse-form-input" id="inFfwAction" placeholder="Contoh: Diberi obat paracetamol / dipulangkan istirahat / ganti operator">
        </div>

        <div id="hseFfwFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitFfw">Simpan Skrining FFW</button>
        </div>
      </form>
    `;

    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const sleepInput = document.getElementById('inFfwSleep');
    const fatigueAlert = document.getElementById('hseFfwFatigueAlert');
    const resultSelect = document.getElementById('inFfwResult');
    const actionInput = document.getElementById('inFfwAction');

    if (sleepInput) {
      sleepInput.addEventListener('input', () => {
        const val = parseFloat(sleepInput.value) || 0;
        if (val < 5.0) {
          if (fatigueAlert) fatigueAlert.hidden = false;
          if (resultSelect) resultSelect.value = 'UNFIT';
          if (actionInput && !actionInput.value) {
            actionInput.value = 'Kurang tidur < 5 jam (fatigue risk). Istirahat minimal 2 jam.';
          }
        } else {
          if (fatigueAlert) fatigueAlert.hidden = true;
          if (resultSelect && resultSelect.value === 'UNFIT' && actionInput?.value.includes('Kurang tidur')) {
            resultSelect.value = 'FIT';
            actionInput.value = '';
          }
        }
      });
    }

    const chkSym = document.getElementById('chkFfwSymptoms');
    const wrapSym = document.getElementById('wrapFfwSymptoms');
    if (chkSym && wrapSym) {
      chkSym.addEventListener('change', () => {
        wrapSym.style.display = chkSym.checked ? 'block' : 'none';
      });
    }

    const form = document.getElementById('formHseFfwCheck');
    const submitBtn = document.getElementById('btnSubmitFfw');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseFfwFormError');
        if (errEl) errEl.hidden = true;

        const payload = {
          employee_id: document.getElementById('inFfwEmpId')?.value,
          check_date: document.getElementById('inFfwDate')?.value,
          shift: document.getElementById('inFfwShift')?.value,
          sleep_hours: parseFloat(document.getElementById('inFfwSleep')?.value) || 0,
          blood_pressure_systolic: parseInt(document.getElementById('inFfwBpSys')?.value, 10) || null,
          blood_pressure_diastolic: parseInt(document.getElementById('inFfwBpDia')?.value, 10) || null,
          heart_rate_bpm: parseInt(document.getElementById('inFfwPulse')?.value, 10) || null,
          body_temp_celsius: parseFloat(document.getElementById('inFfwTemp')?.value) || null,
          has_symptoms: chkSym ? chkSym.checked : false,
          symptoms_desc: document.getElementById('inFfwSymptomsDesc')?.value.trim() || null,
          overall_result: document.getElementById('inFfwResult')?.value,
          action_taken: document.getElementById('inFfwAction')?.value.trim() || null,
          checker_name: document.getElementById('inFfwChecker')?.value.trim(),
        };

        const work = async () => {
          await api('/health/ffw', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadOccHealthData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

  function openCreateSubstanceModal() {
    const emps = state.masters.employees || [];
    const today = new Date().toISOString().slice(0, 10);

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">Pencatatan Tes Alkohol & Narkoba (Substance Test)</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseSubstanceTest" style="margin-top:12px;">
        <div class="hse-form-group">
          <label class="hse-form-label">Pilih Pekerja *</label>
          <select class="hse-form-select" id="inSubEmpId" required>
            <option value="">Pilih Pekerja yang Diuji...</option>
            ${emps.map(e => `
              <option value="${e.id}">${ESC(e.nama)} (${ESC(e.nrp || e.nik || 'No-NRP')}) - ${ESC(e.jabatan || '')}</option>
            `).join('')}
          </select>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tanggal Pelaksanaan *</label>
            <input type="date" class="hse-form-input" id="inSubDate" value="${today}" required>
          </div>
          <div>
            <label class="hse-form-label">Jenis Tes *</label>
            <select class="hse-form-select" id="inSubType" required>
              <option value="RANDOM">Acak Rutin (Random)</option>
              <option value="PRE_EMPLOYMENT">Pra-Kerja (Pre-Employment)</option>
              <option value="POST_INCIDENT">Pasca Insiden (Post-Incident)</option>
              <option value="FOR_CAUSE">Indikasi Kecurigaan (For Cause)</option>
            </select>
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Alasan Pelaksanaan Tes</label>
          <input type="text" class="hse-form-input" id="inSubReason" placeholder="Contoh: Skrining acak shift 1 front tambang / pasca insiden tabrakan DT">
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Kadar Alkohol Breathalyzer (mg/L)</label>
            <input type="number" step="0.01" min="0" class="hse-form-input" id="inSubBreath" value="0.00">
            <small style="color:var(--hse-text-muted);">Nilai &gt; 0.00 otomatis positif</small>
          </div>
          <div>
            <label class="hse-form-label">Hasil Tes Urin 6-Panel *</label>
            <select class="hse-form-select" id="inSubUrine" required>
              <option value="NEGATIVE">NEGATIVE (Negatif - Bersih)</option>
              <option value="POSITIVE">POSITIVE (Positif Terdeteksi)</option>
              <option value="INCONCLUSIVE">INCONCLUSIVE (Tidak Konklusif)</option>
            </select>
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Kesimpulan Akhir *</label>
          <select class="hse-form-select" id="inSubOverall" required>
            <option value="NEGATIVE">NEGATIVE (Lolos - Bebas Narkoba & Alkohol)</option>
            <option value="POSITIVE">POSITIVE (Gagal - Terindikasi Alkohol / Zat Terlarang)</option>
            <option value="INCONCLUSIVE">INCONCLUSIVE (Perlu Uji Ulang Laboratorium)</option>
          </select>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Petugas Penguji *</label>
            <input type="text" class="hse-form-input" id="inSubTester" placeholder="Nama Petugas HSE / Paramedic" required>
          </div>
          <div>
            <label class="hse-form-label">Saksi Pengujian</label>
            <input type="text" class="hse-form-input" id="inSubWitness" placeholder="Nama Foreman / Saksi Departemen">
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Tindakan Lanjut / Sanksi (Bila Positif)</label>
          <input type="text" class="hse-form-input" id="inSubAction" placeholder="Contoh: Penonaktifan sementara SIMPER, konseling, atau investigasi HRD">
        </div>

        <div id="hseSubFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitSub">Simpan Hasil Tes</button>
        </div>
      </form>
    `;

    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const breathInput = document.getElementById('inSubBreath');
    const urineSelect = document.getElementById('inSubUrine');
    const overallSelect = document.getElementById('inSubOverall');

    function syncOverall() {
      const bVal = parseFloat(breathInput?.value) || 0;
      const uVal = urineSelect?.value;
      if (bVal > 0 || uVal === 'POSITIVE') {
        if (overallSelect) overallSelect.value = 'POSITIVE';
      } else if (uVal === 'INCONCLUSIVE') {
        if (overallSelect) overallSelect.value = 'INCONCLUSIVE';
      } else {
        if (overallSelect) overallSelect.value = 'NEGATIVE';
      }
    }

    if (breathInput) breathInput.addEventListener('input', syncOverall);
    if (urineSelect) urineSelect.addEventListener('change', syncOverall);

    const form = document.getElementById('formHseSubstanceTest');
    const submitBtn = document.getElementById('btnSubmitSub');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseSubFormError');
        if (errEl) errEl.hidden = true;

        const payload = {
          employee_id: document.getElementById('inSubEmpId')?.value,
          test_date: document.getElementById('inSubDate')?.value,
          test_type: document.getElementById('inSubType')?.value,
          reason: document.getElementById('inSubReason')?.value.trim() || null,
          breathalyzer_level: parseFloat(document.getElementById('inSubBreath')?.value) || 0,
          urine_drug_result: document.getElementById('inSubUrine')?.value,
          overall_result: document.getElementById('inSubOverall')?.value,
          tester_name: document.getElementById('inSubTester')?.value.trim(),
          witness_name: document.getElementById('inSubWitness')?.value.trim() || null,
          action_taken: document.getElementById('inSubAction')?.value.trim() || null,
        };

        const work = async () => {
          await api('/health/substance-tests', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadOccHealthData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

  function openCreateHealthCaseModal(rec = null) {
    const isEdit = Boolean(rec && rec.id);
    const emps = state.masters.employees || [];
    const today = new Date().toISOString().slice(0, 10);

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">${isEdit ? `Perbarui Kasus Medis #${ESC(rec.case_no)}` : 'Lapor Kasus Kesehatan / Kunjungan Klinik Baru'}</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseHealthCase" style="margin-top:12px;">
        <div class="hse-form-group">
          <label class="hse-form-label">Pilih Pekerja *</label>
          <select class="hse-form-select" id="inCaseEmpId" required ${isEdit ? 'disabled' : ''}>
            <option value="">Pilih Pasien / Pekerja...</option>
            ${emps.map(e => `
              <option value="${e.id}" ${(rec && rec.employee_id === e.id) ? 'selected' : ''}>
                ${ESC(e.nama)} (${ESC(e.nrp || e.nik || 'No-NRP')}) - ${ESC(e.jabatan || '')}
              </option>
            `).join('')}
          </select>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tanggal Kunjungan / Lapor *</label>
            <input type="date" class="hse-form-input" id="inCaseDate" value="${rec ? String(rec.visit_date).slice(0, 10) : today}" required>
          </div>
          <div>
            <label class="hse-form-label">Kategori Kasus *</label>
            <select class="hse-form-select" id="inCaseType" required>
              <option value="ILLNESS" ${(!rec || rec.case_type === 'ILLNESS') ? 'selected' : ''}>Penyakit Umum (Illness)</option>
              <option value="INJURY" ${(rec && rec.case_type === 'INJURY') ? 'selected' : ''}>Cedera Ringan (Minor Injury)</option>
              <option value="WORK_RELATED" ${(rec && rec.case_type === 'WORK_RELATED') ? 'selected' : ''}>Terkait Pekerjaan (Work-Related)</option>
              <option value="SUSPECTED_OD" ${(rec && rec.case_type === 'SUSPECTED_OD') ? 'selected' : ''}>Suspek PAK (Occupational Disease)</option>
            </select>
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Keluhan Utama *</label>
          <input type="text" class="hse-form-input" id="inCaseComplaint" placeholder="Keluhan utama yang dirasakan pasien" value="${ESC(rec?.chief_complaint || '')}" required>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Diagnosis Medis / Temuan Klinis</label>
          <textarea class="hse-form-textarea" id="inCaseDiagnosis" placeholder="Diagnosis kerja atau dugaan klinis dokter...">${ESC(rec?.diagnosis || '')}</textarea>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Hari Kerja Hilang (Lost Days)</label>
            <input type="number" min="0" class="hse-form-input" id="inCaseLostDays" value="${rec?.lost_workdays ?? 0}">
          </div>
          <div>
            <label class="hse-form-label">Status Kasus *</label>
            <select class="hse-form-select" id="inCaseStatus" required>
              <option value="OPEN" ${(!rec || rec.status === 'OPEN') ? 'selected' : ''}>OPEN (Baru)</option>
              <option value="MONITORING" ${(rec && rec.status === 'MONITORING') ? 'selected' : ''}>MONITORING (Dalam Pemantauan)</option>
              <option value="CLOSED" ${(rec && rec.status === 'CLOSED') ? 'selected' : ''}>CLOSED (Selesai / Pulih)</option>
            </select>
          </div>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tindakan / Pengobatan Diberikan</label>
            <input type="text" class="hse-form-input" id="inCaseTreatment" placeholder="Pemberian obat / rujukan RS / istirahat" value="${ESC(rec?.treatment_given || '')}">
          </div>
          <div>
            <label class="hse-form-label">Tenaga Medis Pemeriksa</label>
            <input type="text" class="hse-form-input" id="inCaseStaff" placeholder="dr. Site / Paramedic" value="${ESC(rec?.medical_staff_name || '')}">
          </div>
        </div>

        <div id="hseCaseFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitCase">${isEdit ? 'Simpan Pembaruan' : 'Lapor Kasus'}</button>
        </div>
      </form>
    `;

    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const form = document.getElementById('formHseHealthCase');
    const submitBtn = document.getElementById('btnSubmitCase');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseCaseFormError');
        if (errEl) errEl.hidden = true;

        const payload = {
          employee_id: document.getElementById('inCaseEmpId')?.value || rec?.employee_id,
          visit_date: document.getElementById('inCaseDate')?.value,
          case_type: document.getElementById('inCaseType')?.value,
          chief_complaint: document.getElementById('inCaseComplaint')?.value.trim(),
          diagnosis: document.getElementById('inCaseDiagnosis')?.value.trim() || null,
          lost_workdays: parseInt(document.getElementById('inCaseLostDays')?.value, 10) || 0,
          status: document.getElementById('inCaseStatus')?.value,
          treatment_given: document.getElementById('inCaseTreatment')?.value.trim() || null,
          medical_staff_name: document.getElementById('inCaseStaff')?.value.trim() || null,
        };

        const work = async () => {
          if (isEdit) {
            await api(`/health/cases/${rec.id}`, { method: 'PUT', body: payload });
          } else {
            await api('/health/cases', { method: 'POST', body: payload });
          }
          state.activeModal = null;
          await loadOccHealthData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

  function openCreateHygieneModal() {
    const locations = state.masters.locations || [];
    const today = new Date().toISOString().slice(0, 10);

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">Input Pengukuran Higiene Industri Lingkungan Kerja</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseHygieneMeasurement" style="margin-top:12px;">
        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tanggal Pengukuran *</label>
            <input type="date" class="hse-form-input" id="inHygDate" value="${today}" required>
          </div>
          <div>
            <label class="hse-form-label">Lokasi / Titik Pemantauan *</label>
            <select class="hse-form-select" id="inHygLocId" required>
              ${renderLocationHierarchyOptions('', 'Pilih Lokasi Tambang...')}
            </select>
          </div>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Parameter Bahaya Fisik *</label>
            <select class="hse-form-select" id="inHygParam" required>
              <option value="NOISE">Kebisingan (Noise - dBA)</option>
              <option value="DUST">Debu Respirabel Tambang (Dust - mg/m³)</option>
              <option value="LIGHTING">Pencahayaan (Lighting - Lux)</option>
              <option value="VIBRATION">Getaran Mesin/Alat (Vibration - m/s²)</option>
              <option value="HEAT">Iklim Kerja Panas (ISBB - °C)</option>
            </select>
          </div>
          <div>
            <label class="hse-form-label">Satuan Nilai Ukur</label>
            <input type="text" class="hse-form-input" id="inHygUnit" value="dBA" required>
          </div>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Nilai Terukur *</label>
            <input type="number" step="0.01" class="hse-form-input" id="inHygValue" placeholder="85.0" required>
          </div>
          <div>
            <label class="hse-form-label">Nilai Ambang Batas (NAB Baku Mutu) *</label>
            <input type="number" step="0.01" class="hse-form-input" id="inHygNab" value="85.0" required>
          </div>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Durasi Paparan Pekerja (Jam/Hari)</label>
            <input type="number" step="0.5" class="hse-form-input" id="inHygExposure" value="8.0" min="0" max="24">
          </div>
          <div>
            <label class="hse-form-label">Petugas Pengukur (Industrial Hygienist)</label>
            <input type="text" class="hse-form-input" id="inHygInspector" placeholder="Nama Petugas Higiene HSE">
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Rekomendasi Rekayasa / Pengendalian APD</label>
          <textarea class="hse-form-textarea" id="inHygAction" placeholder="Contoh: Wajib penggunaan earmuff & earplug (double protection) atau peredam silencer..."></textarea>
        </div>

        <div id="hseHygFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitHyg">Simpan Data Higiene</button>
        </div>
      </form>
    `;

    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const paramSelect = document.getElementById('inHygParam');
    const unitInput = document.getElementById('inHygUnit');
    const nabInput = document.getElementById('inHygNab');

    if (paramSelect) {
      paramSelect.addEventListener('change', () => {
        const val = paramSelect.value;
        if (val === 'NOISE') {
          if (unitInput) unitInput.value = 'dBA';
          if (nabInput) nabInput.value = '85.0';
        } else if (val === 'DUST') {
          if (unitInput) unitInput.value = 'mg/m³';
          if (nabInput) nabInput.value = '3.0';
        } else if (val === 'LIGHTING') {
          if (unitInput) unitInput.value = 'Lux';
          if (nabInput) nabInput.value = '100.0';
        } else if (val === 'VIBRATION') {
          if (unitInput) unitInput.value = 'm/s²';
          if (nabInput) nabInput.value = '5.0';
        } else if (val === 'HEAT') {
          if (unitInput) unitInput.value = '°C';
          if (nabInput) nabInput.value = '28.0';
        }
      });
    }

    const form = document.getElementById('formHseHygieneMeasurement');
    const submitBtn = document.getElementById('btnSubmitHyg');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseHygFormError');
        if (errEl) errEl.hidden = true;

        const payload = {
          measurement_date: document.getElementById('inHygDate')?.value,
          location_id: document.getElementById('inHygLocId')?.value,
          parameter: document.getElementById('inHygParam')?.value,
          unit: document.getElementById('inHygUnit')?.value.trim() || null,
          measured_value: parseFloat(document.getElementById('inHygValue')?.value) || 0,
          threshold_nab: parseFloat(document.getElementById('inHygNab')?.value) || null,
          exposure_duration_hours: parseFloat(document.getElementById('inHygExposure')?.value) || null,
          corrective_action: document.getElementById('inHygAction')?.value.trim() || null,
          measured_by_name: document.getElementById('inHygInspector')?.value.trim() || null,
        };

        const work = async () => {
          await api('/health/hygiene', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadOccHealthData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

// ============================================================================
  // FASE 6: TANGGAP DARURAT (EMERGENCY RESPONSE) VIEWS
  // ============================================================================
  function renderEmergencyView() {
    const isTeam = state.emergencySubTab === 'team';
    const isDrills = state.emergencySubTab === 'drills';
    const isEq = state.emergencySubTab === 'equipment';
    const isAssembly = state.emergencySubTab === 'assembly';
    const isContacts = state.emergencySubTab === 'contacts';

    return `
      <div class="hse-subnav">
        <button type="button" class="hse-subnav-btn ${isTeam ? 'is-active' : ''}" data-emergency-tab="team">
          <i class="ti ti-users" aria-hidden="true"></i> Tim ERT
        </button>
        <button type="button" class="hse-subnav-btn ${isDrills ? 'is-active' : ''}" data-emergency-tab="drills">
          <i class="ti ti-flame" aria-hidden="true"></i> Simulasi & Drill
        </button>
        <button type="button" class="hse-subnav-btn ${isEq ? 'is-active' : ''}" data-emergency-tab="equipment">
          <i class="ti ti-fire-extinguisher" aria-hidden="true"></i> Peralatan Darurat
        </button>
        <button type="button" class="hse-subnav-btn ${isAssembly ? 'is-active' : ''}" data-emergency-tab="assembly">
          <i class="ti ti-map-pin" aria-hidden="true"></i> Titik Kumpul Evakuasi
        </button>
        <button type="button" class="hse-subnav-btn ${isContacts ? 'is-active' : ''}" data-emergency-tab="contacts">
          <i class="ti ti-phone-call" aria-hidden="true"></i> Kontak Darurat
        </button>
      </div>

      ${isTeam ? renderEmergencyTeamTab() : (
        isDrills ? renderEmergencyDrillsTab() : (
          isEq ? renderEmergencyEquipmentTab() : (
            isAssembly ? renderEmergencyAssemblyTab() : renderEmergencyContactsTab()
          )
        )
      )}
    `;
  }

  function renderEmergencyTeamTab() {
    const team = state.emergencyTeam || [];
    const stats = state.emergencyOverview?.team || { total_team: team.length, active_team: team.length, commander_count: 0, firefighter_count: 0, firstaider_count: 0, rescue_count: 0 };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Personil ERT</span>
          <span class="hse-stat-pill-val">${stats.total_team || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Personil Aktif</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.active_team || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-danger);">Incident Commander</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);">${stats.commander_count || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Fire Fighters</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);">${stats.firefighter_count || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-accent);">Rescue Squad</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-accent);">${stats.rescue_count || 0}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseErtSearch" placeholder="Cari nama, NRP, sertifikasi..." value="${ESC(state.emergencyTeamFilters.search)}">
          <select class="hse-filter-select" id="hseFilterErtRole">
            <option value="">Semua Peran ERT</option>
            <option value="COMMANDER" ${state.emergencyTeamFilters.role === 'COMMANDER' ? 'selected' : ''}>Incident Commander</option>
            <option value="FIRE_FIGHTER" ${state.emergencyTeamFilters.role === 'FIRE_FIGHTER' ? 'selected' : ''}>Fire Fighter</option>
            <option value="FIRST_AIDER" ${state.emergencyTeamFilters.role === 'FIRST_AIDER' ? 'selected' : ''}>First Aider / Paramedic</option>
            <option value="RESCUE" ${state.emergencyTeamFilters.role === 'RESCUE' ? 'selected' : ''}>Rescue Specialist</option>
            <option value="COMMUNICATION" ${state.emergencyTeamFilters.role === 'COMMUNICATION' ? 'selected' : ''}>Radio & Dispatcher</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddErtMember">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Personil ERT
        </button>
      </div>

      <div class="hse-ert-grid">
        ${team.length === 0 ? `<div style="grid-column:1/-1;text-align:center;padding:24px;color:var(--hse-text-muted);">Belum ada data anggota tim ERT.</div>` : team.map(m => {
          const roleClass = m.role?.toLowerCase() || 'rescue';
          return `
            <div class="hse-ert-card">
              <div class="hse-ert-card-header">
                <span class="hse-ert-card-name">${ESC(m.employee_name)}</span>
                <span class="hse-ert-role-badge ${roleClass}">${ESC(m.role)}</span>
              </div>
              <div style="font-size:11px;color:var(--hse-text-secondary);">
                ${ESC(m.position_name || '-')} · ${ESC(m.department_name || '-')}
              </div>
              <div style="font-size:11px;">
                <span style="color:var(--hse-text-muted);">Shift:</span> ${ESC(m.shift || '-')} ·
                <span style="color:var(--hse-text-muted);">Kontak:</span> <strong>${ESC(m.phone_no || '-')}</strong>
              </div>
              <div style="font-size:11px;background:var(--hse-surface-1);padding:6px;border-radius:4px;border:0.5px solid var(--hse-border);">
                <i class="ti ti-certificate" style="color:var(--hse-text-accent);font-size:12px;"></i>
                ${ESC(m.certifications || 'Belum ada catatan sertifikasi')}
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  function renderEmergencyDrillsTab() {
    const drills = state.emergencyDrills || [];
    const stats = state.emergencyOverview?.drills || { total_drills_ytd: drills.length, avg_response_time_sec: 0, good_result: 0, adequate_result: 0, needs_improvement: 0 };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Drill YTD</span>
          <span class="hse-stat-pill-val">${stats.total_drills_ytd || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Rata-rata Waktu Respon</span>
          <span class="hse-stat-pill-val">${stats.avg_response_time_sec ? Math.round(stats.avg_response_time_sec / 60) + ' Menit' : '-'}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Hasil Baik (Good)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.good_result || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.needs_improvement > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'};">
          <span class="hse-stat-pill-label" style="color:${stats.needs_improvement > 0 ? 'var(--hse-text-danger)' : 'inherit'};">Perlu Perbaikan</span>
          <span class="hse-stat-pill-val" style="color:${stats.needs_improvement > 0 ? 'var(--hse-text-danger)' : 'inherit'};">${stats.needs_improvement || 0}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseDrillSearch" placeholder="Cari skenario, judul, lokasi drill..." value="${ESC(state.emergencyDrillFilters.search)}">
          <select class="hse-filter-select" id="hseFilterDrillScenario">
            <option value="">Semua Skenario</option>
            <option value="FIRE" ${state.emergencyDrillFilters.scenario === 'FIRE' ? 'selected' : ''}>Kebakaran (Fire)</option>
            <option value="MEDICAL" ${state.emergencyDrillFilters.scenario === 'MEDICAL' ? 'selected' : ''}>Evakuasi Medis</option>
            <option value="SPILL" ${state.emergencyDrillFilters.scenario === 'SPILL' ? 'selected' : ''}>Tumpahan Kimia / B3</option>
            <option value="ROCKFALL" ${state.emergencyDrillFilters.scenario === 'ROCKFALL' ? 'selected' : ''}>Longsor Tambang (Rockfall)</option>
            <option value="EVACUATION" ${state.emergencyDrillFilters.scenario === 'EVACUATION' ? 'selected' : ''}>Evakuasi Menyeluruh</option>
          </select>
          <select class="hse-filter-select" id="hseFilterDrillResult">
            <option value="">Semua Hasil</option>
            <option value="GOOD" ${state.emergencyDrillFilters.result === 'GOOD' ? 'selected' : ''}>GOOD (Memuaskan)</option>
            <option value="ADEQUATE" ${state.emergencyDrillFilters.result === 'ADEQUATE' ? 'selected' : ''}>ADEQUATE (Cukup)</option>
            <option value="NEEDS_IMPROVEMENT" ${state.emergencyDrillFilters.result === 'NEEDS_IMPROVEMENT' ? 'selected' : ''}>NEEDS IMPROVEMENT</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddDrill">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat Simulasi / Drill
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>No Drill</th>
              <th>Tanggal</th>
              <th>Skenario & Judul</th>
              <th>Lokasi</th>
              <th>Peserta</th>
              <th>Waktu Respon</th>
              <th>Hasil Evaluasi</th>
              <th>Tautan CAPA</th>
            </tr>
          </thead>
          <tbody>
            ${drills.length === 0 ? `<tr><td colspan="8" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada riwayat simulasi tanggap darurat.</td></tr>` : drills.map(d => {
              const resBadge = d.result === 'GOOD'
                ? `<span class="hse-badge hse-badge--success">GOOD</span>`
                : (d.result === 'ADEQUATE' ? `<span class="hse-badge hse-badge--accent">ADEQUATE</span>` : `<span class="hse-badge hse-badge--danger">NEEDS IMPROVEMENT</span>`);
              const respMins = d.response_time_sec ? Math.round(d.response_time_sec / 60) + ' min (' + d.response_time_sec + 's)' : '-';
              return `
                <tr>
                  <td><strong>${ESC(d.drill_no)}</strong></td>
                  <td>${d.drill_date ? new Date(d.drill_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td>
                    <span class="hse-badge hse-badge--secondary" style="font-size:10px;">${ESC(d.scenario)}</span>
                    <div style="font-weight:600;margin-top:2px;">${ESC(d.scenario_title)}</div>
                  </td>
                  <td>${ESC(d.location_name || '-')}</td>
                  <td>${d.participant_count} Orang</td>
                  <td>${respMins}</td>
                  <td>${resBadge}</td>
                  <td>${d.action_no ? `<span class="hse-badge hse-badge--warning">${ESC(d.action_no)} (${ESC(d.action_status)})</span>` : '<span style="color:var(--hse-text-muted);font-size:11px;">-</span>'}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderEmergencyEquipmentTab() {
    const eq = state.emergencyEquipment || [];
    const stats = state.emergencyOverview?.equipment || { total_equipment: eq.length, good_count: 0, due_inspection: 0, overdue_inspection: 0, defective_count: 0 };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Peralatan</span>
          <span class="hse-stat-pill-val">${stats.total_equipment || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Kondisi Baik</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.good_count || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.due_inspection > 0 ? 'var(--hse-fill-warning)' : 'var(--hse-border)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Inspeksi Mendekati ( $\le$ 7 hr)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);font-weight:700;">${stats.due_inspection || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.overdue_inspection > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.overdue_inspection > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:${stats.overdue_inspection > 0 ? 'var(--hse-text-danger)' : 'inherit'};">Inspeksi Lewat Waktu</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.overdue_inspection || 0}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseEqSearch" placeholder="Cari kode alat, no seri, lokasi..." value="${ESC(state.emergencyEquipmentFilters.search)}">
          <select class="hse-filter-select" id="hseFilterEqType">
            <option value="">Semua Tipe Peralatan</option>
            <option value="FIRE_EXTINGUISHER" ${state.emergencyEquipmentFilters.equipment_type === 'FIRE_EXTINGUISHER' ? 'selected' : ''}>APAR / Tabung Pemadam</option>
            <option value="FIRST_AID_BOX" ${state.emergencyEquipmentFilters.equipment_type === 'FIRST_AID_BOX' ? 'selected' : ''}>Kotak P3K Tambang</option>
            <option value="EYEWASH" ${state.emergencyEquipmentFilters.equipment_type === 'EYEWASH' ? 'selected' : ''}>Eyewash & Shower</option>
            <option value="HYDRANT" ${state.emergencyEquipmentFilters.equipment_type === 'HYDRANT' ? 'selected' : ''}>Hydrant Pillar</option>
            <option value="SPILL_KIT" ${state.emergencyEquipmentFilters.equipment_type === 'SPILL_KIT' ? 'selected' : ''}>Spill Kit B3</option>
          </select>
          <select class="hse-filter-select" id="hseFilterEqStatus">
            <option value="">Semua Status</option>
            <option value="GOOD" ${state.emergencyEquipmentFilters.status === 'GOOD' ? 'selected' : ''}>GOOD (Siap Pakai)</option>
            <option value="DUE" ${state.emergencyEquipmentFilters.status === 'DUE' ? 'selected' : ''}>DUE (Jadwal Dekat)</option>
            <option value="OVERDUE" ${state.emergencyEquipmentFilters.status === 'OVERDUE' ? 'selected' : ''}>OVERDUE (Lewat Waktu)</option>
            <option value="DEFECTIVE" ${state.emergencyEquipmentFilters.status === 'DEFECTIVE' ? 'selected' : ''}>DEFECTIVE (Rusak)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddEquipment">
          <i class="ti ti-plus" aria-hidden="true"></i> Registrasi Alat Baru
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Kode Alat</th>
              <th>Tipe</th>
              <th>Lokasi Penempatan</th>
              <th>Kapasitas / Isi</th>
              <th>Inspeksi Terakhir</th>
              <th>Inspeksi Berikut</th>
              <th>Kedaluwarsa Isi</th>
              <th>Status</th>
              <th>Inspektor</th>
            </tr>
          </thead>
          <tbody>
            ${eq.length === 0 ? `<tr><td colspan="9" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada inventaris peralatan darurat.</td></tr>` : eq.map(item => {
              const stBadge = item.status === 'OVERDUE'
                ? `<span class="hse-badge hse-badge--danger">OVERDUE</span>`
                : (item.status === 'DUE' ? `<span class="hse-badge hse-badge--warning">DUE INSPECTION</span>` : (item.status === 'DEFECTIVE' ? `<span class="hse-badge hse-badge--danger">RUSAK</span>` : `<span class="hse-badge hse-badge--success">GOOD</span>`));
              return `
                <tr>
                  <td><strong>${ESC(item.equipment_code)}</strong></td>
                  <td>${ESC(item.equipment_type)}</td>
                  <td>${ESC(item.location_name)}</td>
                  <td>${ESC(item.capacity || '-')}</td>
                  <td>${item.last_inspection_date ? new Date(item.last_inspection_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td>${item.next_inspection_date ? new Date(item.next_inspection_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td>${item.content_expiry_date ? new Date(item.content_expiry_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td>${stBadge}</td>
                  <td>${ESC(item.inspector_name || '-')}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderEmergencyAssemblyTab() {
    const points = state.emergencyAssemblyPoints || [];
    const stats = state.emergencyOverview?.assembly || { total_assembly_points: points.length, total_capacity: 0 };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Titik Kumpul (Assembly)</span>
          <span class="hse-stat-pill-val">${stats.total_assembly_points || 0} Titik</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Daya Tampung Orang</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-accent);">${stats.total_capacity || 0} Orang</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div style="font-size:12px;font-weight:600;color:var(--hse-text-secondary);">
          Daftar Muster Point & Koordinator Evakuasi (Warden Area)
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddAssemblyPoint" style="margin-left:auto;">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Titik Kumpul
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Kode</th>
              <th>Nama Titik Kumpul</th>
              <th>Lokasi Tambang</th>
              <th>Daya Tampung</th>
              <th>Koordinator Evakuasi (Warden)</th>
              <th>Peta / Rute</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            ${points.length === 0 ? `<tr><td colspan="7" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada titik kumpul evakuasi terdaftar.</td></tr>` : points.map(p => `
              <tr>
                <td><strong>${ESC(p.code)}</strong></td>
                <td><strong>${ESC(p.name)}</strong></td>
                <td>${ESC(p.location_name)}</td>
                <td>${p.capacity_persons} Orang</td>
                <td><i class="ti ti-user-check" style="color:var(--hse-text-success);"></i> ${ESC(p.warden_name || '-')}</td>
                <td>${p.map_url ? `<a href="${ESC(p.map_url)}" target="_blank" style="color:var(--hse-text-accent);text-decoration:none;"><i class="ti ti-map"></i> Lihat Peta</a>` : '<span style="color:var(--hse-text-muted);">-</span>'}</td>
                <td>${p.is_active ? '<span class="hse-badge hse-badge--success">AKTIF</span>' : '<span class="hse-badge hse-badge--secondary">NON-AKTIF</span>'}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderEmergencyContactsTab() {
    const contacts = state.emergencyContacts || [];

    return `
      <div class="hse-filter-bar">
        <div style="font-size:12px;font-weight:600;color:var(--hse-text-secondary);">
          Direktori Kontak Cepat Tanggap Darurat (Internal Site & Instansi Eksternal)
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddEmergencyContact" style="margin-left:auto;">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Kontak Darurat
        </button>
      </div>

      <div class="hse-contact-grid">
        ${contacts.length === 0 ? `<div style="grid-column:1/-1;text-align:center;padding:24px;color:var(--hse-text-muted);">Belum ada nomor kontak darurat.</div>` : contacts.map(c => {
          const catClass = c.category?.toLowerCase() || 'internal';
          return `
            <div class="hse-contact-card ${catClass}">
              <div style="font-size:10px;font-weight:700;color:var(--hse-text-muted);text-transform:uppercase;">
                ${ESC(c.category)}
              </div>
              <div style="font-size:13px;font-weight:700;color:var(--hse-text-primary);">
                ${ESC(c.name)}
              </div>
              <div style="font-size:14px;font-weight:700;color:var(--hse-text-danger);margin:4px 0;">
                <i class="ti ti-phone-call"></i> ${ESC(c.phone_no)}
              </div>
              ${c.alternate_phone ? `<div style="font-size:11px;color:var(--hse-text-muted);"><i class="ti ti-broadcast"></i> ${ESC(c.alternate_phone)}</div>` : ''}
              ${c.address ? `<div style="font-size:11px;color:var(--hse-text-secondary);"><i class="ti ti-map-pin"></i> ${ESC(c.address)}</div>` : ''}
              ${c.notes ? `<div style="font-size:10px;color:var(--hse-text-muted);margin-top:4px;border-top:0.5px solid var(--hse-border);padding-top:4px;">${ESC(c.notes)}</div>` : ''}
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  // ============================================================================
  // FASE 6: APD DAN PERALATAN (PPE) VIEWS
  // ============================================================================
  function renderPpeView() {
    const isIss = state.ppeSubTab === 'issuances';
    const isStd = state.ppeSubTab === 'standards';
    const isItems = state.ppeSubTab === 'items';

    return `
      <div class="hse-subnav">
        <button type="button" class="hse-subnav-btn ${isIss ? 'is-active' : ''}" data-ppe-tab="issuances">
          <i class="ti ti-user-check" aria-hidden="true"></i> Distribusi APD Karyawan
        </button>
        <button type="button" class="hse-subnav-btn ${isStd ? 'is-active' : ''}" data-ppe-tab="standards">
          <i class="ti ti-matrix" aria-hidden="true"></i> Standar APD per Jabatan
        </button>
        <button type="button" class="hse-subnav-btn ${isItems ? 'is-active' : ''}" data-ppe-tab="items">
          <i class="ti ti-archive" aria-hidden="true"></i> Master Katalog & Stok APD
        </button>
      </div>

      ${isIss ? renderPpeIssuancesTab() : (
        isStd ? renderPpeStandardsTab() : renderPpeItemsTab()
      )}
    `;
  }

  function renderPpeIssuancesTab() {
    const issuances = state.ppeIssuances || [];
    const stats = state.ppeOverview?.issuances || { total_issuances: issuances.length, active_issuances: 0, due_replacement_count: 0, overdue_replacement_count: 0 };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Penyerahan</span>
          <span class="hse-stat-pill-val">${stats.total_issuances || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">APD Sedang Digunakan</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.active_issuances || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.due_replacement_count > 0 ? 'var(--hse-fill-warning)' : 'var(--hse-border)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Jatuh Tempo Ganti ( $\le$ 30 Hari)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);font-weight:700;">${stats.due_replacement_count || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.overdue_replacement_count > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.overdue_replacement_count > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-danger);">Lewat Batas Pakai</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.overdue_replacement_count || 0}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hsePpeIssuanceSearch" placeholder="Cari nama karyawan, NRP, nama APD..." value="${ESC(state.ppeIssuanceFilters.search)}">
          <select class="hse-filter-select" id="hseFilterPpeIssuanceStatus">
            <option value="">Semua Status</option>
            <option value="ACTIVE" ${state.ppeIssuanceFilters.status === 'ACTIVE' ? 'selected' : ''}>ACTIVE (Sedang Dipakai)</option>
            <option value="DUE_REPLACEMENT" ${state.ppeIssuanceFilters.status === 'DUE_REPLACEMENT' ? 'selected' : ''}>DUE REPLACEMENT (Waktunya Ganti)</option>
            <option value="RETURNED" ${state.ppeIssuanceFilters.status === 'RETURNED' ? 'selected' : ''}>RETURNED (Dikembalikan)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddPpeIssuance">
          <i class="ti ti-plus" aria-hidden="true"></i> Serahkan APD Baru
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Karyawan</th>
              <th>Jabatan & Dept</th>
              <th>Item APD</th>
              <th>Kategori</th>
              <th>Ukuran & Jml</th>
              <th>Tgl Serah</th>
              <th>Batas Ganti (Due)</th>
              <th>Status</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${issuances.length === 0 ? `<tr><td colspan="9" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada riwayat distribusi APD.</td></tr>` : issuances.map(iss => {
              const stBadge = iss.status === 'DUE_REPLACEMENT'
                ? `<span class="hse-badge hse-badge--warning">DUE GANTI</span>`
                : (iss.status === 'RETURNED' ? `<span class="hse-badge hse-badge--secondary">KEMBALI</span>` : `<span class="hse-badge hse-badge--success">AKTIF</span>`);
              return `
                <tr>
                  <td>
                    <strong>${ESC(iss.employee_name)}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(iss.employee_nrp || '-')}</div>
                  </td>
                  <td>${ESC(iss.position_name || '-')} · ${ESC(iss.department_name || '-')}</td>
                  <td><strong>${ESC(iss.ppe_item_name)}</strong></td>
                  <td><span class="hse-badge hse-badge--secondary" style="font-size:10px;">${ESC(iss.ppe_category)}</span></td>
                  <td>${ESC(iss.size || '-')} (${iss.quantity} unit)</td>
                  <td>${iss.issued_date ? new Date(iss.issued_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td><strong>${iss.replace_due_date ? new Date(iss.replace_due_date).toLocaleDateString('id-ID') : '-'}</strong></td>
                  <td>${stBadge}</td>
                  <td>
                    ${iss.status === 'ACTIVE' || iss.status === 'DUE_REPLACEMENT' ? `
                      <button type="button" class="hse-btn hse-btn--secondary" style="padding:2px 6px;font-size:11px;" data-return-issuance-id="${iss.id}">
                        <i class="ti ti-arrow-back"></i> Kembalikan
                      </button>
                    ` : '<span style="color:var(--hse-text-muted);font-size:11px;">-</span>'}
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderPpeStandardsTab() {
    const stds = state.ppeStandards || [];

    return `
      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hsePpeStdSearch" placeholder="Cari jabatan atau nama APD..." value="${ESC(state.ppeStandardFilters.search)}">
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddPpeStandard" style="margin-left:auto;">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Standar APD Jabatan
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Jabatan Pekerja</th>
              <th>Area Penempatan</th>
              <th>Item APD Wajib</th>
              <th>Kategori</th>
              <th>Interval Ganti</th>
              <th>Standar Mutu</th>
              <th>Keterangan</th>
            </tr>
          </thead>
          <tbody>
            ${stds.length === 0 ? `<tr><td colspan="7" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada matriks standar APD per jabatan.</td></tr>` : stds.map(s => `
              <tr>
                <td><strong>${ESC(s.position_name)}</strong></td>
                <td><span class="hse-badge hse-badge--secondary">${ESC(s.location_type || 'ALL')}</span></td>
                <td><strong>${ESC(s.ppe_name)}</strong></td>
                <td>${ESC(s.ppe_category)}</td>
                <td>${s.replace_interval_months} Bulan</td>
                <td style="font-size:11px;">${ESC(s.standard_specification || '-')}</td>
                <td style="font-size:11px;color:var(--hse-text-muted);">${ESC(s.notes || '-')}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderPpeItemsTab() {
    const items = state.ppeItems || [];
    const stats = state.ppeOverview?.items || { total_items: items.length, critical_stock_count: 0, total_stock_on_hand: 0 };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Katalog APD</span>
          <span class="hse-stat-pill-val">${stats.total_items || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.critical_stock_count > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.critical_stock_count > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-danger);">Stok Kritis ( $\le$ Min)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.critical_stock_count || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Stok Fisik Tersedia</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-accent);">${stats.total_stock_on_hand || 0} Unit</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hsePpeItemSearch" placeholder="Cari kode APD, nama, standar SNI..." value="${ESC(state.ppeItemFilters.search)}">
          <select class="hse-filter-select" id="hseFilterPpeItemCat">
            <option value="">Semua Kategori</option>
            <option value="HEAD" ${state.ppeItemFilters.category === 'HEAD' ? 'selected' : ''}>Head (Helm)</option>
            <option value="EYE" ${state.ppeItemFilters.category === 'EYE' ? 'selected' : ''}>Eye (Kacamata)</option>
            <option value="EAR" ${state.ppeItemFilters.category === 'EAR' ? 'selected' : ''}>Ear (Sumbat Telinga)</option>
            <option value="RESPIRATORY" ${state.ppeItemFilters.category === 'RESPIRATORY' ? 'selected' : ''}>Respiratory (Masker)</option>
            <option value="HAND" ${state.ppeItemFilters.category === 'HAND' ? 'selected' : ''}>Hand (Sarung Tangan)</option>
            <option value="BODY" ${state.ppeItemFilters.category === 'BODY' ? 'selected' : ''}>Body (Rompi/Coverall)</option>
            <option value="FOOT" ${state.ppeItemFilters.category === 'FOOT' ? 'selected' : ''}>Foot (Sepatu Safety)</option>
            <option value="FALL_PROTECTION" ${state.ppeItemFilters.category === 'FALL_PROTECTION' ? 'selected' : ''}>Fall Protection (Harness)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterPpeItemCritical">
            <option value="">Semua Kondisi Stok</option>
            <option value="true" ${state.ppeItemFilters.is_critical === 'true' ? 'selected' : ''}>Stok Kritis Saja</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddPpeItem">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Master APD
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Kode</th>
              <th>Nama Item APD</th>
              <th>Kategori</th>
              <th>Masa Pakai (Bulan)</th>
              <th>Standar Mutu SNI / ANSI</th>
              <th>Stok Saat Ini</th>
              <th>Batas Min</th>
              <th>Status Stok</th>
            </tr>
          </thead>
          <tbody>
            ${items.length === 0 ? `<tr><td colspan="8" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada katalog APD terdaftar.</td></tr>` : items.map(it => {
              const critBadge = it.is_critical_stock
                ? `<span class="hse-stock-pill critical"><i class="ti ti-alert-triangle"></i> KRITIS</span>`
                : `<span class="hse-stock-pill normal"><i class="ti ti-check"></i> AMAN</span>`;
              return `
                <tr>
                  <td><strong>${ESC(it.code)}</strong></td>
                  <td><strong>${ESC(it.name)}</strong></td>
                  <td><span class="hse-badge hse-badge--secondary">${ESC(it.category)}</span></td>
                  <td>${it.replace_interval_months} Bln</td>
                  <td style="font-size:11px;">${ESC(it.standard_specification || '-')}</td>
                  <td><strong>${it.current_stock}</strong> ${ESC(it.unit)}</td>
                  <td>${it.minimum_stock} ${ESC(it.unit)}</td>
                  <td>${critBadge}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  // ============================================================================
  // FASE 7: KONTRAKTOR (CSMS) & LINGKUNGAN HIDUP RENDERERS
  // ============================================================================
  function renderContractorView() {
    const isComp = state.contractorSubTab === 'companies';
    const isAss = state.contractorSubTab === 'assessments';
    const isDocs = state.contractorSubTab === 'documents';
    const isViols = state.contractorSubTab === 'violations';

    return `
      <div class="hse-subnav">
        <button type="button" class="hse-subnav-btn ${isComp ? 'is-active' : ''}" data-contractor-tab="companies">
          <i class="ti ti-building" aria-hidden="true"></i> Daftar Mitra Kerja
        </button>
        <button type="button" class="hse-subnav-btn ${isAss ? 'is-active' : ''}" data-contractor-tab="assessments">
          <i class="ti ti-shield-check" aria-hidden="true"></i> Penilaian CSMS
        </button>
        <button type="button" class="hse-subnav-btn ${isDocs ? 'is-active' : ''}" data-contractor-tab="documents">
          <i class="ti ti-file-certificate" aria-hidden="true"></i> Dokumen &amp; Perizinan
        </button>
        <button type="button" class="hse-subnav-btn ${isViols ? 'is-active' : ''}" data-contractor-tab="violations">
          <i class="ti ti-alert-triangle" aria-hidden="true"></i> Pelanggaran &amp; Sanksi
        </button>
      </div>

      ${isComp ? renderContractorCompaniesTab() : (
        isAss ? renderContractorAssessmentsTab() : (
          isDocs ? renderContractorDocumentsTab() : renderContractorViolationsTab()
        )
      )}
    `;
  }

  function renderContractorCompaniesTab() {
    const ctrs = state.contractors || [];
    const stats = state.contractorOverview || {
      total_contractors: ctrs.length,
      active_contractors: ctrs.filter(c => c.is_active).length,
      csms_approved: 0,
      expiring_or_expired_docs: 0,
      open_violations: 0,
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Mitra Kerja</span>
          <span class="hse-stat-pill-val">${stats.total_contractors || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Mitra Aktif Berizin</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);">${stats.active_contractors || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-primary);">CSMS Lolos (Approved)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-primary);font-weight:700;">${stats.csms_approved || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.expiring_or_expired_docs > 0 ? 'var(--hse-fill-warning)' : 'var(--hse-border)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Dokumen Expiring / Expired</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);font-weight:700;">${stats.expiring_or_expired_docs || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.open_violations > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.open_violations > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-danger);">Pelanggaran Belum Tuntas</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.open_violations || 0}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseCtrSearch" placeholder="Cari nama kontraktor, kode, PIC..." value="${ESC(state.contractorFilters.search)}">
          <select class="hse-filter-select" id="hseFilterCtrBusinessType">
            <option value="">Semua Bidang Usaha</option>
            <option value="HAULING" ${state.contractorFilters.business_type === 'HAULING' ? 'selected' : ''}>Hauling Batubara</option>
            <option value="CIVIL_WORKS" ${state.contractorFilters.business_type === 'CIVIL_WORKS' ? 'selected' : ''}>Konstruksi &amp; Sipil</option>
            <option value="DRILLING_BLASTING" ${state.contractorFilters.business_type === 'DRILLING_BLASTING' ? 'selected' : ''}>Drilling &amp; Blasting</option>
            <option value="CATERING_CAMP" ${state.contractorFilters.business_type === 'CATERING_CAMP' ? 'selected' : ''}>Katering &amp; Camp</option>
            <option value="HEAVY_EQUIPMENT_MAINTENANCE" ${state.contractorFilters.business_type === 'HEAVY_EQUIPMENT_MAINTENANCE' ? 'selected' : ''}>Maintenance Alat Berat</option>
            <option value="OTHER" ${state.contractorFilters.business_type === 'OTHER' ? 'selected' : ''}>Lainnya</option>
          </select>
          <select class="hse-filter-select" id="hseFilterCtrActive">
            <option value="">Semua Status Aktif</option>
            <option value="true" ${state.contractorFilters.is_active === 'true' ? 'selected' : ''}>Aktif</option>
            <option value="false" ${state.contractorFilters.is_active === 'false' ? 'selected' : ''}>Nonaktif</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddContractor">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Mitra Kerja
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Kode</th>
              <th>Nama Perusahaan Mitra</th>
              <th>Bidang Usaha</th>
              <th>PIC &amp; Kontak</th>
              <th>Pekerja di Site</th>
              <th>Skor &amp; Status CSMS</th>
              <th>Status Mitra</th>
            </tr>
          </thead>
          <tbody>
            ${ctrs.length === 0 ? `<tr><td colspan="7" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada data kontraktor terdaftar.</td></tr>` : ctrs.map(c => {
              let csmsBadge = `<span class="hse-csms-badge none">BELUM DINILAI</span>`;
              if (c.csms_status === 'APPROVED') {
                csmsBadge = `<span class="hse-csms-badge approved"><i class="ti ti-check"></i> APPROVED (${c.latest_csms_score || '-'})</span>`;
              } else if (c.csms_status === 'CONDITIONAL') {
                csmsBadge = `<span class="hse-csms-badge conditional"><i class="ti ti-alert-circle"></i> CONDITIONAL (${c.latest_csms_score || '-'})</span>`;
              } else if (c.csms_status === 'REJECTED') {
                csmsBadge = `<span class="hse-csms-badge rejected"><i class="ti ti-x"></i> REJECTED (${c.latest_csms_score || '-'})</span>`;
              }

              const actBadge = c.is_active
                ? `<span class="hse-badge hse-badge--success">AKTIF</span>`
                : `<span class="hse-badge hse-badge--secondary">NONAKTIF</span>`;

              return `
                <tr>
                  <td><strong>${ESC(c.code)}</strong></td>
                  <td>
                    <strong>${ESC(c.name)}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(c.address || '-')}</div>
                  </td>
                  <td><span class="hse-badge hse-badge--secondary">${ESC(c.business_type)}</span></td>
                  <td>
                    <strong>${ESC(c.pic_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(c.pic_phone || '')} ${c.pic_email ? `· ${ESC(c.pic_email)}` : ''}</div>
                  </td>
                  <td><strong>${c.worker_count || 0}</strong> org</td>
                  <td>${csmsBadge}</td>
                  <td>${actBadge}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderContractorAssessmentsTab() {
    const assessments = state.contractorAssessments || [];

    return `
      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseCtrAssSearch" placeholder="Cari nama kontraktor, asesor..." value="${ESC(state.contractorAssessmentFilters.search)}">
          <select class="hse-filter-select" id="hseFilterCtrAssResult">
            <option value="">Semua Hasil Penilaian</option>
            <option value="APPROVED" ${state.contractorAssessmentFilters.result === 'APPROVED' ? 'selected' : ''}>APPROVED (&ge; 75)</option>
            <option value="CONDITIONAL" ${state.contractorAssessmentFilters.result === 'CONDITIONAL' ? 'selected' : ''}>CONDITIONAL (60 - 74)</option>
            <option value="REJECTED" ${state.contractorAssessmentFilters.result === 'REJECTED' ? 'selected' : ''}>REJECTED (&lt; 60)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddContractorAssessment">
          <i class="ti ti-plus" aria-hidden="true"></i> Penilaian CSMS Baru
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Mitra Kontraktor</th>
              <th>Jenis Asesmen</th>
              <th>Tanggal Penilaian</th>
              <th>Skor CSMS</th>
              <th>Hasil Kelayakan</th>
              <th>Berlaku Hingga</th>
              <th>PIC Asesor</th>
              <th>Rekomendasi / Catatan</th>
            </tr>
          </thead>
          <tbody>
            ${assessments.length === 0 ? `<tr><td colspan="8" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada riwayat penilaian CSMS.</td></tr>` : assessments.map(a => {
              let resBadge = `<span class="hse-csms-badge rejected">REJECTED</span>`;
              if (a.result === 'APPROVED') {
                resBadge = `<span class="hse-csms-badge approved"><i class="ti ti-check"></i> APPROVED</span>`;
              } else if (a.result === 'CONDITIONAL') {
                resBadge = `<span class="hse-csms-badge conditional"><i class="ti ti-alert-circle"></i> CONDITIONAL</span>`;
              }

              return `
                <tr>
                  <td>
                    <strong>${ESC(a.contractor_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(a.contractor_code || '')} · ${ESC(a.contractor_business || '')}</div>
                  </td>
                  <td><span class="hse-badge hse-badge--secondary">${ESC(a.assessment_type)}</span></td>
                  <td>${a.assessment_date ? new Date(a.assessment_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td><strong style="font-size:13px;">${a.score}</strong> / 100</td>
                  <td>${resBadge}</td>
                  <td><strong>${a.valid_until ? new Date(a.valid_until).toLocaleDateString('id-ID') : '-'}</strong></td>
                  <td>${ESC(a.assessor_name || '-')}</td>
                  <td style="font-size:11px;max-width:200px;">${ESC(a.notes || '-')}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderContractorDocumentsTab() {
    const docs = state.contractorDocuments || [];

    return `
      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseCtrDocSearch" placeholder="Cari nama kontraktor, no dokumen..." value="${ESC(state.contractorDocFilters.search)}">
          <select class="hse-filter-select" id="hseFilterCtrDocType">
            <option value="">Semua Jenis Dokumen</option>
            <option value="SMK3" ${state.contractorDocFilters.doc_type === 'SMK3' ? 'selected' : ''}>Sertifikat SMK3</option>
            <option value="IUJP" ${state.contractorDocFilters.doc_type === 'IUJP' ? 'selected' : ''}>Izin Usaha Jasa Pertambangan (IUJP)</option>
            <option value="INSURANCE_POLICY" ${state.contractorDocFilters.doc_type === 'INSURANCE_POLICY' ? 'selected' : ''}>Polis Asuransi / BPJS TK</option>
            <option value="PERSONNEL_CERT" ${state.contractorDocFilters.doc_type === 'PERSONNEL_CERT' ? 'selected' : ''}>Sertifikasi Personel K3</option>
            <option value="OTHER" ${state.contractorDocFilters.doc_type === 'OTHER' ? 'selected' : ''}>Lainnya</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddContractorDoc">
          <i class="ti ti-plus" aria-hidden="true"></i> Unggah Dokumen / Izin
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Mitra Kontraktor</th>
              <th>Tipe Dokumen</th>
              <th>Nomor Dokumen</th>
              <th>Tanggal Terbit</th>
              <th>Kedaluwarsa</th>
              <th>Status Izin</th>
              <th>Catatan / Tautan</th>
            </tr>
          </thead>
          <tbody>
            ${docs.length === 0 ? `<tr><td colspan="7" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada dokumen perizinan kontraktor terdaftar.</td></tr>` : docs.map(d => {
              let stBadge = `<span class="hse-badge hse-badge--success">VALID</span>`;
              if (d.status === 'EXPIRING') {
                stBadge = `<span class="hse-badge hse-badge--warning"><i class="ti ti-alert-triangle"></i> EXPIRING (&le; 30 Hari)</span>`;
              } else if (d.status === 'EXPIRED') {
                stBadge = `<span class="hse-badge hse-badge--danger"><i class="ti ti-x"></i> EXPIRED</span>`;
              }

              return `
                <tr>
                  <td>
                    <strong>${ESC(d.contractor_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(d.contractor_code || '')}</div>
                  </td>
                  <td><span class="hse-badge hse-badge--secondary">${ESC(d.doc_type)}</span></td>
                  <td><strong>${ESC(d.doc_number)}</strong></td>
                  <td>${d.issued_date ? new Date(d.issued_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td><strong>${d.expiry_date ? new Date(d.expiry_date).toLocaleDateString('id-ID') : 'Seumur Hidup'}</strong></td>
                  <td>${stBadge}</td>
                  <td style="font-size:11px;">${ESC(d.notes || d.file_url || '-')}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderContractorViolationsTab() {
    const viols = state.contractorViolations || [];

    return `
      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseCtrViolSearch" placeholder="Cari nama kontraktor, deskripsi..." value="${ESC(state.contractorViolFilters.search)}">
          <select class="hse-filter-select" id="hseFilterCtrViolSeverity">
            <option value="">Semua Keparahan</option>
            <option value="MINOR" ${state.contractorViolFilters.severity === 'MINOR' ? 'selected' : ''}>Minor (Ringan)</option>
            <option value="MAJOR" ${state.contractorViolFilters.severity === 'MAJOR' ? 'selected' : ''}>Major (Sedang/Berat)</option>
            <option value="CRITICAL" ${state.contractorViolFilters.severity === 'CRITICAL' ? 'selected' : ''}>Critical (Kritis/Pemberhentian)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterCtrViolStatus">
            <option value="">Semua Status</option>
            <option value="OPEN" ${state.contractorViolFilters.status === 'OPEN' ? 'selected' : ''}>Open (Belum Selesai)</option>
            <option value="RESOLVED" ${state.contractorViolFilters.status === 'RESOLVED' ? 'selected' : ''}>Resolved (Tuntas)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddContractorViolation">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat Pelanggaran K3LH
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Tanggal</th>
              <th>Mitra Kontraktor</th>
              <th>Deskripsi Pelanggaran</th>
              <th>Keparahan</th>
              <th>Sanksi Diterapkan</th>
              <th>Status</th>
              <th>Pelapor</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${viols.length === 0 ? `<tr><td colspan="8" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Tidak ada catatan pelanggaran kontraktor.</td></tr>` : viols.map(v => {
              let sevBadge = `<span class="hse-badge hse-badge--info">MINOR</span>`;
              if (v.severity === 'MAJOR') sevBadge = `<span class="hse-badge hse-badge--warning">MAJOR</span>`;
              if (v.severity === 'CRITICAL') sevBadge = `<span class="hse-badge hse-badge--danger">CRITICAL</span>`;

              const stBadge = v.status === 'OPEN'
                ? `<span class="hse-badge hse-badge--danger"><i class="ti ti-clock"></i> OPEN</span>`
                : `<span class="hse-badge hse-badge--success"><i class="ti ti-check"></i> RESOLVED</span>`;

              return `
                <tr>
                  <td>${v.violation_date ? new Date(v.violation_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td>
                    <strong>${ESC(v.contractor_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(v.contractor_code || '')}</div>
                  </td>
                  <td style="font-size:11px;max-width:240px;">${ESC(v.description)}</td>
                  <td>${sevBadge}</td>
                  <td><strong>${ESC(v.sanction_type)}</strong></td>
                  <td>${stBadge}</td>
                  <td style="font-size:11px;">${ESC(v.reported_by_name || '-')}</td>
                  <td>
                    ${v.status === 'OPEN' ? `
                      <button type="button" class="hse-btn hse-btn--secondary" style="padding:2px 8px;font-size:11px;" data-resolve-contractor-viol-id="${v.id}">
                        <i class="ti ti-check"></i> Selesaikan
                      </button>
                    ` : `<span style="font-size:11px;color:var(--hse-text-muted);">-</span>`}
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  // ============================================================================
  // FASE 7: LINGKUNGAN HIDUP RENDERER
  // ============================================================================
  function renderEnvironmentView() {
    const isWaste = state.environmentSubTab === 'waste';
    const isMon = state.environmentSubTab === 'monitoring';
    const isRec = state.environmentSubTab === 'reclamation';

    return `
      <div class="hse-subnav">
        <button type="button" class="hse-subnav-btn ${isWaste ? 'is-active' : ''}" data-environment-tab="waste">
          <i class="ti ti-trash" aria-hidden="true"></i> Log &amp; Neraca Limbah B3
        </button>
        <button type="button" class="hse-subnav-btn ${isMon ? 'is-active' : ''}" data-environment-tab="monitoring">
          <i class="ti ti-droplet" aria-hidden="true"></i> Pemantauan Kualitas Lingkungan
        </button>
        <button type="button" class="hse-subnav-btn ${isRec ? 'is-active' : ''}" data-environment-tab="reclamation">
          <i class="ti ti-plant" aria-hidden="true"></i> Reklamasi &amp; Revegetasi
        </button>
      </div>

      ${isWaste ? renderEnvironmentWasteTab() : (
        isMon ? renderEnvironmentMonitoringTab() : renderEnvironmentReclamationTab()
      )}
    `;
  }

  function renderEnvironmentWasteTab() {
    const logs = state.envWasteLogs || [];
    const stats = state.environmentOverview || {
      b3_stored_total: logs.filter(l => l.status === 'STORED').length,
      b3_deadline_alerts: 0,
      active_monitoring_points: (state.envPoints || []).length,
      exceeded_measurements_30d: 0,
      reclamation_realization_ha: 0,
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Limbah B3 di TPS</span>
          <span class="hse-stat-pill-val">${stats.b3_stored_total || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.b3_deadline_alerts > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.b3_deadline_alerts > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-danger);">Peringatan Tenggat Simpan (&le;14h / Overdue)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.b3_deadline_alerts || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-primary);">Titik Pantau Lingkungan Aktif</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-primary);font-weight:700;">${stats.active_monitoring_points || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.exceeded_measurements_30d > 0 ? 'var(--hse-fill-warning)' : 'var(--hse-border)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Melebihi Baku Mutu (30h)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);font-weight:700;">${stats.exceeded_measurements_30d || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Realisasi Reklamasi (Ha)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);font-weight:700;">${stats.reclamation_realization_ha || 0} Ha</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseWasteSearch" placeholder="Cari kode limbah, unit sumber, festronik..." value="${ESC(state.envWasteFilters.search)}">
          <select class="hse-filter-select" id="hseFilterWasteStatus">
            <option value="">Semua Status Pengelolaan</option>
            <option value="STORED" ${state.envWasteFilters.status === 'STORED' ? 'selected' : ''}>STORED (Tersimpan di TPS)</option>
            <option value="HAULED" ${state.envWasteFilters.status === 'HAULED' ? 'selected' : ''}>HAULED (Diangkut Pihak Ke-3)</option>
            <option value="PROCESSED" ${state.envWasteFilters.status === 'PROCESSED' ? 'selected' : ''}>PROCESSED (Selesai Dikelola)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddWasteB3">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat Log Limbah B3
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Tgl Masuk TPS</th>
              <th>Kode &amp; Nama Limbah B3</th>
              <th>Sumber / Workshop</th>
              <th>Jumlah Timbulan</th>
              <th>Batas Simpan TPS (90 Hari)</th>
              <th>Status Alur</th>
              <th>Manifes Festronik / Transporter</th>
            </tr>
          </thead>
          <tbody>
            ${logs.length === 0 ? `<tr><td colspan="7" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada catatan log limbah B3.</td></tr>` : logs.map(l => {
              let alertBadge = `<span class="hse-env-status complies"><i class="ti ti-check"></i> AMAN</span>`;
              if (l.is_overdue) {
                alertBadge = `<span class="hse-env-status exceeded"><i class="ti ti-alert-triangle"></i> OVERDUE (${Math.abs(l.days_to_deadline)} hr lewat)</span>`;
              } else if (l.is_deadline_alert) {
                alertBadge = `<span class="hse-env-status near"><i class="ti ti-clock"></i> SISA ${l.days_to_deadline} HARI</span>`;
              }

              let stBadge = `<span class="hse-badge hse-badge--warning">STORED DI TPS</span>`;
              if (l.status === 'HAULED') stBadge = `<span class="hse-badge hse-badge--success">HAULED DIANGKUT</span>`;
              if (l.status === 'PROCESSED') stBadge = `<span class="hse-badge hse-badge--secondary">PROCESSED</span>`;

              return `
                <tr>
                  <td>${l.log_date ? new Date(l.log_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td>
                    <strong>${ESC(l.waste_code)}</strong> - ${ESC(l.waste_name)}
                  </td>
                  <td>${ESC(l.source_location || '-')} ${l.source_unit ? `(${ESC(l.source_unit)})` : ''}</td>
                  <td><strong style="font-size:13px;">${l.quantity}</strong> ${ESC(l.unit)}</td>
                  <td>
                    <strong>${l.storage_deadline ? new Date(l.storage_deadline).toLocaleDateString('id-ID') : '-'}</strong>
                    <div style="margin-top:2px;">${l.status === 'STORED' ? alertBadge : '<span style="font-size:10px;color:var(--hse-text-muted);">Sudah dikeluarkan</span>'}</div>
                  </td>
                  <td>${stBadge}</td>
                  <td style="font-size:11px;">
                    <strong>${ESC(l.manifest_number || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(l.transporter_name || '-')}</div>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderEnvironmentMonitoringTab() {
    const points = state.envPoints || [];
    const meas = state.envMeasurements || [];

    return `
      <div style="margin-bottom:14px;">
        <div style="font-size:12px;font-weight:600;margin-bottom:8px;display:flex;align-items:center;justify-content:space-between;">
          <span>Titik Pantau Lingkungan Resmi (${points.length} Titik)</span>
          <button type="button" class="hse-btn hse-btn--secondary" style="padding:2px 8px;font-size:11px;" id="btnHseAddEnvPoint">
            <i class="ti ti-map-pin"></i> Tambah Titik Pantau
          </button>
        </div>
        <div class="hse-ctr-grid">
          ${points.map(pt => `
            <div class="hse-ctr-card">
              <div style="display:flex;justify-content:space-between;align-items:flex-start;">
                <strong>${ESC(pt.point_code)}</strong>
                <span class="hse-badge hse-badge--secondary" style="font-size:9px;">${ESC(pt.category)}</span>
              </div>
              <div style="font-size:12px;font-weight:500;margin-top:4px;">${ESC(pt.name)}</div>
              <div style="font-size:10px;color:var(--hse-text-muted);margin-top:2px;">${ESC(pt.location_description || '-')}</div>
            </div>
          `).join('')}
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseMeasSearch" placeholder="Cari titik pantau, lab..." value="${ESC(state.envMeasFilters.search)}">
          <select class="hse-filter-select" id="hseFilterMeasStatus">
            <option value="">Semua Status Kepatuhan</option>
            <option value="COMPLIES" ${state.envMeasFilters.status === 'COMPLIES' ? 'selected' : ''}>COMPLIES (Memenuhi Baku Mutu)</option>
            <option value="NEAR_LIMIT" ${state.envMeasFilters.status === 'NEAR_LIMIT' ? 'selected' : ''}>NEAR LIMIT (Mendekati Batas &ge; 85%)</option>
            <option value="EXCEEDED" ${state.envMeasFilters.status === 'EXCEEDED' ? 'selected' : ''}>EXCEEDED (Melebihi Baku Mutu)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddEnvMeasurement">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat Hasil Uji Kualitas
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Tgl Sampling</th>
              <th>Titik Pantau &amp; Media</th>
              <th>Parameter Diuji</th>
              <th>Hasil Terukur</th>
              <th>Baku Mutu Acuan</th>
              <th>Evaluasi Status</th>
              <th>Lab &amp; Penguji</th>
            </tr>
          </thead>
          <tbody>
            ${meas.length === 0 ? `<tr><td colspan="7" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada data pengukuran kualitas lingkungan.</td></tr>` : meas.map(m => {
              let evBadge = `<span class="hse-env-status complies"><i class="ti ti-check"></i> MEMENUHI</span>`;
              if (m.compliance_status === 'NEAR_LIMIT') {
                evBadge = `<span class="hse-env-status near"><i class="ti ti-alert-circle"></i> NEAR LIMIT</span>`;
              } else if (m.compliance_status === 'EXCEEDED') {
                evBadge = `<span class="hse-env-status exceeded"><i class="ti ti-x"></i> MELEBIHI BAKU MUTU</span>`;
              }

              let limitLabel = '-';
              if (m.param_min_val !== null && m.param_max_val !== null) {
                limitLabel = `${m.param_min_val} - ${m.param_max_val} ${m.param_unit}`;
              } else if (m.param_max_val !== null) {
                limitLabel = `Maks. ${m.param_max_val} ${m.param_unit}`;
              }

              return `
                <tr>
                  <td>${m.measurement_date ? new Date(m.measurement_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td>
                    <strong>${ESC(m.point_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(m.point_code || '')} · ${ESC(m.point_category || '')}</div>
                  </td>
                  <td><strong>${ESC(m.parameter_name || '-')}</strong> (${ESC(m.param_code || '')})</td>
                  <td><strong style="font-size:13px;">${m.measured_value}</strong> ${ESC(m.param_unit || '')}</td>
                  <td style="font-size:11px;">${limitLabel}</td>
                  <td>${evBadge}</td>
                  <td style="font-size:11px;">
                    <strong>${ESC(m.lab_name || '-')}</strong>
                    <div style="font-size:10px;color:var(--hse-text-muted);">${ESC(m.tested_by_name || '')}</div>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderEnvironmentReclamationTab() {
    const recs = state.envReclamations || [];

    return `
      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseRecSearch" placeholder="Cari lokasi, jenis bibit..." value="${ESC(state.envRecFilters.search)}">
          <select class="hse-filter-select" id="hseFilterRecActivity">
            <option value="">Semua Jenis Kegiatan</option>
            <option value="LANDSCAPING" ${state.envRecFilters.activity === 'LANDSCAPING' ? 'selected' : ''}>Penataan Lahan (Landscaping)</option>
            <option value="TOPSOIL" ${state.envRecFilters.activity === 'TOPSOIL' ? 'selected' : ''}>Penebaran Topsoil</option>
            <option value="PLANTING" ${state.envRecFilters.activity === 'PLANTING' ? 'selected' : ''}>Penanaman / Revegetasi</option>
            <option value="MAINTENANCE" ${state.envRecFilters.activity === 'MAINTENANCE' ? 'selected' : ''}>Pemeliharaan &amp; Penyulaman</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddReclamation">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat Kegiatan Reklamasi
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Tanggal</th>
              <th>Lokasi / Blok Reklamasi</th>
              <th>Jenis Kegiatan</th>
              <th>Rencana vs Realisasi (Ha)</th>
              <th>Jenis Bibit Ditanam</th>
              <th>Jumlah Pohon</th>
              <th>Tingkat Kematian (%)</th>
              <th>Pengawas / PIC</th>
            </tr>
          </thead>
          <tbody>
            ${recs.length === 0 ? `<tr><td colspan="8" style="text-align:center;padding:20px;color:var(--hse-text-muted);">Belum ada catatan kegiatan reklamasi &amp; revegetasi.</td></tr>` : recs.map(r => {
              const pct = r.plan_area_ha > 0 ? Math.min(100, Math.round((r.actual_area_ha / r.plan_area_ha) * 100)) : 100;
              return `
                <tr>
                  <td>${r.activity_date ? new Date(r.activity_date).toLocaleDateString('id-ID') : '-'}</td>
                  <td><strong>${ESC(r.location_name || '-')}</strong></td>
                  <td><span class="hse-badge hse-badge--secondary">${ESC(r.activity_type)}</span></td>
                  <td>
                    <div><strong>${r.actual_area_ha} Ha</strong> / ${r.plan_area_ha} Ha</div>
                    <div class="hse-progress-track">
                      <div class="hse-progress-fill" style="width:${pct}%;"></div>
                    </div>
                  </td>
                  <td>${ESC(r.seedling_types || '-')}</td>
                  <td><strong>${r.seedling_count || 0}</strong> bibit</td>
                  <td><span class="hse-badge ${r.mortality_rate_pct > 10 ? 'hse-badge--warning' : 'hse-badge--success'}">${r.mortality_rate_pct || 0}%</span></td>
                  <td style="font-size:11px;">${ESC(r.supervisor_name || '-')}</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  // ============================================================================
  // FASE 8: AUDIT, KEPATUHAN SMKP & DOKUMEN REGULASI RENDERERS
  // ============================================================================
  function renderAuditView() {
    const isAudits = state.auditSubTab === 'audits';
    const isFindings = state.auditSubTab === 'findings';
    const isSmkp = state.auditSubTab === 'smkp';

    return `
      <div class="hse-subnav">
        <button type="button" class="hse-subnav-btn ${isAudits ? 'is-active' : ''}" data-audit-tab="audits">
          <i class="ti ti-calendar-event" aria-hidden="true"></i> Program &amp; Jadwal Audit
        </button>
        <button type="button" class="hse-subnav-btn ${isFindings ? 'is-active' : ''}" data-audit-tab="findings">
          <i class="ti ti-alert-circle" aria-hidden="true"></i> Temuan Audit &amp; Tindakan (CAPA)
        </button>
        <button type="button" class="hse-subnav-btn ${isSmkp ? 'is-active' : ''}" data-audit-tab="smkp">
          <i class="ti ti-list-check" aria-hidden="true"></i> Evaluasi 7 Elemen SMKP Minerba
        </button>
      </div>

      ${isAudits ? renderAuditProgramTab() : (
        isFindings ? renderAuditFindingsTab() : renderAuditSmkpTab()
      )}
    `;
  }

  function renderAuditProgramTab() {
    const audits = state.audits || [];
    const stats = state.auditOverview || {
      total_audits: audits.length,
      audits_completed: audits.filter(a => ['REPORTED', 'CLOSED'].includes(a.status)).length,
      audits_planned: audits.filter(a => a.status === 'PLANNED').length,
      avg_compliance_score: 84.5,
      open_major_findings: 0,
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Program Audit</span>
          <span class="hse-stat-pill-val">${stats.total_audits || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Audit Selesai / Terlaksana</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);font-weight:700;">${stats.audits_completed || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-primary);">Audit Direncanakan</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-primary);font-weight:700;">${stats.audits_planned || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Rata-rata Skor Kesesuaian</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-info, #0284c7);font-weight:700;">
            ${stats.avg_compliance_score != null ? Number(stats.avg_compliance_score).toFixed(1) + '%' : '-'}
          </span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.open_major_findings > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.open_major_findings > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-danger);">Temuan Major Terbuka</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.open_major_findings || 0}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseAuditSearch" placeholder="Cari nomor audit, judul, auditor..." value="${ESC(state.auditFilters.search)}">
          <select class="hse-filter-select" id="hseFilterAuditType">
            <option value="">Semua Tipe Audit</option>
            <option value="INTERNAL" ${state.auditFilters.audit_type === 'INTERNAL' ? 'selected' : ''}>Internal SMKP</option>
            <option value="EXTERNAL" ${state.auditFilters.audit_type === 'EXTERNAL' ? 'selected' : ''}>Eksternal Sertifikasi</option>
            <option value="CONTRACTOR" ${state.auditFilters.audit_type === 'CONTRACTOR' ? 'selected' : ''}>Audit Kontraktor</option>
            <option value="REGULATOR" ${state.auditFilters.audit_type === 'REGULATOR' ? 'selected' : ''}>Inspeksi KAIT / ESDM</option>
          </select>
          <select class="hse-filter-select" id="hseFilterAuditStatus">
            <option value="">Semua Status Audit</option>
            <option value="PLANNED" ${state.auditFilters.status === 'PLANNED' ? 'selected' : ''}>PLANNED (Direncanakan)</option>
            <option value="IN_PROGRESS" ${state.auditFilters.status === 'IN_PROGRESS' ? 'selected' : ''}>IN_PROGRESS (Berjalan)</option>
            <option value="REPORTED" ${state.auditFilters.status === 'REPORTED' ? 'selected' : ''}>REPORTED (Laporan Terbit)</option>
            <option value="CLOSED" ${state.auditFilters.status === 'CLOSED' ? 'selected' : ''}>CLOSED (Selesai &amp; Ditutup)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddAudit">
          <i class="ti ti-plus" aria-hidden="true"></i> Jadwalkan Program Audit
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Nomor &amp; Judul Program</th>
              <th>Tipe</th>
              <th>Standar / Lingkup</th>
              <th>Jadwal Pelaksanaan</th>
              <th>Lead Auditor / Lembaga</th>
              <th>Skor Kepatuhan</th>
              <th>Status</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${audits.length === 0 ? `
              <tr>
                <td colspan="8" style="text-align:center;padding:32px;color:var(--hse-text-muted);">
                  Belum ada program audit yang terdaftar. Klik tombol di atas untuk menjadwalkan audit.
                </td>
              </tr>
            ` : audits.map(a => {
              const statusClass = a.status === 'CLOSED' ? 'closed' :
                                  a.status === 'REPORTED' ? 'verify' :
                                  a.status === 'IN_PROGRESS' ? 'in_action' : 'open';
              return `
                <tr>
                  <td>
                    <strong style="color:var(--hse-text-primary);font-size:12px;">${ESC(a.audit_no)}</strong>
                    <div style="font-size:11px;color:var(--hse-text-muted);">${ESC(a.audit_title)}</div>
                  </td>
                  <td><span class="hse-status-badge ${statusClass}">${ESC(a.audit_type)}</span></td>
                  <td style="font-size:11px;">${ESC(a.scope_standard || 'SMKP Minerba')}</td>
                  <td style="font-size:11px;">
                    ${ESC(String(a.start_date || '').slice(0, 10))} s/d ${ESC(String(a.end_date || '').slice(0, 10))}
                  </td>
                  <td style="font-size:11px;">
                    <div><strong>${ESC(a.lead_auditor || '-')}</strong></div>
                    <div style="color:var(--hse-text-muted);">${ESC(a.audit_body || '-')}</div>
                  </td>
                  <td>
                    ${a.compliance_score_pct != null ? `
                      <span style="font-weight:700;color:${a.compliance_score_pct >= 85 ? 'var(--hse-text-success)' : (a.compliance_score_pct >= 70 ? 'var(--hse-text-warning)' : 'var(--hse-text-danger)')};">
                        ${Number(a.compliance_score_pct).toFixed(1)}%
                      </span>
                    ` : '<span style="color:var(--hse-text-muted);">-</span>'}
                  </td>
                  <td><span class="hse-status-badge ${statusClass}">${ESC(a.status)}</span></td>
                  <td>
                    <button type="button" class="hse-btn hse-btn--sm" data-add-finding-audit-id="${a.id}" data-add-finding-audit-no="${ESC(a.audit_no)}" title="Tambah temuan untuk audit ini">
                      <i class="ti ti-plus" aria-hidden="true"></i> Temuan
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderAuditFindingsTab() {
    const findings = state.auditFindings || [];

    return `
      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseFindingSearch" placeholder="Cari klausul, uraian temuan, PIC..." value="${ESC(state.auditFindingFilters.search)}">
          <select class="hse-filter-select" id="hseFilterFindingCategory">
            <option value="">Semua Kategori Temuan</option>
            <option value="MAJOR" ${state.auditFindingFilters.category === 'MAJOR' ? 'selected' : ''}>MAJOR (Ketidaksesuaian Mayor)</option>
            <option value="MINOR" ${state.auditFindingFilters.category === 'MINOR' ? 'selected' : ''}>MINOR (Ketidaksesuaian Minor)</option>
            <option value="OBSERVATION" ${state.auditFindingFilters.category === 'OBSERVATION' ? 'selected' : ''}>OBSERVATION (Observasi)</option>
            <option value="OPPORTUNITY" ${state.auditFindingFilters.category === 'OPPORTUNITY' ? 'selected' : ''}>OPPORTUNITY (Peluang Peningkatan)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterFindingStatus">
            <option value="">Semua Status Temuan</option>
            <option value="OPEN" ${state.auditFindingFilters.status === 'OPEN' ? 'selected' : ''}>OPEN (Terbuka)</option>
            <option value="IN_ACTION" ${state.auditFindingFilters.status === 'IN_ACTION' ? 'selected' : ''}>IN_ACTION (Tindak Lanjut)</option>
            <option value="VERIFY" ${state.auditFindingFilters.status === 'VERIFY' ? 'selected' : ''}>VERIFY (Menunggu Verifikasi)</option>
            <option value="CLOSED" ${state.auditFindingFilters.status === 'CLOSED' ? 'selected' : ''}>CLOSED (Selesai Ditutup)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddAuditFinding">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat Temuan Audit
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>No. Temuan &amp; Audit</th>
              <th>Kategori</th>
              <th>Klausul / Elemen</th>
              <th>Uraian Ketidaksesuaian &amp; Bukti</th>
              <th>PIC &amp; Tenggat</th>
              <th>Link CAPA</th>
              <th>Status</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${findings.length === 0 ? `
              <tr>
                <td colspan="8" style="text-align:center;padding:32px;color:var(--hse-text-muted);">
                  Belum ada catatan temuan audit yang sesuai dengan filter.
                </td>
              </tr>
            ` : findings.map(f => {
              const catClass = (f.category || 'observation').toLowerCase();
              const statusClass = f.status === 'CLOSED' ? 'closed' :
                                  f.status === 'VERIFY' ? 'verify' :
                                  f.status === 'IN_ACTION' ? 'in_action' : 'open';
              return `
                <tr>
                  <td>
                    <strong style="color:var(--hse-text-primary);font-size:12px;">${ESC(f.finding_no)}</strong>
                    <div style="font-size:11px;color:var(--hse-text-muted);">${ESC(f.audit_no || '-')}</div>
                  </td>
                  <td>
                    <span class="hse-finding-pill ${catClass}">
                      ${ESC(f.category)}
                    </span>
                  </td>
                  <td style="font-size:11px;">
                    <div><strong>${ESC(f.clause_reference || '-')}</strong></div>
                    <div style="color:var(--hse-text-muted);">${f.smkp_element_no ? 'Elemen ' + f.smkp_element_no : ''}</div>
                  </td>
                  <td style="max-width:280px;">
                    <div style="font-size:12px;font-weight:500;">${ESC(f.description)}</div>
                    ${f.evidence_summary ? `<div style="font-size:11px;color:var(--hse-text-muted);margin-top:2px;"><em>Bukti: ${ESC(f.evidence_summary)}</em></div>` : ''}
                  </td>
                  <td style="font-size:11px;">
                    <div><strong>${ESC(f.pic_name || '-')}</strong></div>
                    <div style="color:var(--hse-text-muted);">${ESC(String(f.due_date || '').slice(0, 10))}</div>
                  </td>
                  <td style="font-size:11px;">
                    ${f.action_no ? `
                      <span class="hse-status-badge in_action" title="Terkoneksi ke modul CAPA">
                        <i class="ti ti-link" aria-hidden="true"></i> ${ESC(f.action_no)}
                      </span>
                    ` : '<span style="color:var(--hse-text-muted);">-</span>'}
                  </td>
                  <td><span class="hse-status-badge ${statusClass}">${ESC(f.status)}</span></td>
                  <td>
                    ${f.status !== 'CLOSED' ? `
                      <button type="button" class="hse-btn hse-btn--sm" data-resolve-audit-finding-id="${f.id}" data-resolve-finding-no="${ESC(f.finding_no)}" title="Verifikasi &amp; tutup temuan">
                        <i class="ti ti-check" aria-hidden="true"></i> Verifikasi
                      </button>
                    ` : `
                      <span style="font-size:11px;color:var(--hse-text-success);"><i class="ti ti-circle-check" aria-hidden="true"></i> Closed</span>
                    `}
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderAuditSmkpTab() {
    const elements = state.smkpElements || [];

    return `
      <div style="margin-bottom:16px;padding:12px 16px;background:var(--hse-surface-2);border-radius:6px;border:1px solid var(--hse-border);display:flex;align-items:center;justify-content:space-between;">
        <div>
          <strong style="font-size:13px;color:var(--hse-text-primary);"><i class="ti ti-certificate" aria-hidden="true"></i> Standar Evaluasi SMKP Minerba (Permen ESDM No. 26/2018)</strong>
          <div style="font-size:11px;color:var(--hse-text-muted);margin-top:2px;">
            Sistem Manajemen Keselamatan Pertambangan Minerba mencakup 7 elemen penilaian kepatuhan wajib bagi pemegang IUP/IUPK.
          </div>
        </div>
        <div style="font-size:12px;font-weight:600;color:var(--hse-text-success);">
          Total Bobot: 100%
        </div>
      </div>

      <div class="hse-smkp-grid">
        ${elements.length === 0 ? `
          <div style="grid-column: 1 / -1;text-align:center;padding:32px;color:var(--hse-text-muted);">
            Data elemen SMKP belum tersedia.
          </div>
        ` : elements.map(el => {
          return `
            <div class="hse-smkp-card">
              <div class="hse-smkp-card-title">
                <span>Elemen ${ESC(el.element_no)}: ${ESC(el.element_name)}</span>
                <span style="background:var(--hse-surface-1);border:1px solid var(--hse-border);padding:2px 6px;border-radius:4px;font-size:10px;font-weight:700;">
                  ${Number(el.weight_percentage)}%
                </span>
              </div>
              <p style="font-size:11px;color:var(--hse-text-muted);margin:0 0 10px 0;line-height:1.4;">
                ${ESC(el.description || 'Penerapan standar elemen keselamatan pertambangan minerba.')}
              </p>
              <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:4px;">
                <span>Total Klausul Wajib:</span>
                <strong>${ESC(el.clause_count || 0)} Klausul</strong>
              </div>
              <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:6px;">
                <span>Target Minimal:</span>
                <strong style="color:var(--hse-text-success);">${Number(el.target_compliance_pct || 85)}%</strong>
              </div>
              <div class="hse-progress-bar-bg" style="height:6px;background:var(--hse-surface-2);border-radius:3px;overflow:hidden;">
                <div style="width:${Math.min(100, Number(el.target_compliance_pct || 85))}%;background:var(--hse-fill-success, #16a34a);height:100%;"></div>
              </div>
            </div>
          `;
        }).join('')}
      </div>
    `;
  }

  function renderDocumentsView() {
    const isDocs = state.documentsSubTab === 'docs';
    const isRegs = state.documentsSubTab === 'regulations';
    const isReports = state.documentsSubTab === 'reports';

    return `
      <div class="hse-subnav">
        <button type="button" class="hse-subnav-btn ${isDocs ? 'is-active' : ''}" data-documents-tab="docs">
          <i class="ti ti-file-text" aria-hidden="true"></i> Dokumen &amp; Prosedur HSE
        </button>
        <button type="button" class="hse-subnav-btn ${isRegs ? 'is-active' : ''}" data-documents-tab="regulations">
          <i class="ti ti-scale" aria-hidden="true"></i> Daftar Regulasi (Legal Register)
        </button>
        <button type="button" class="hse-subnav-btn ${isReports ? 'is-active' : ''}" data-documents-tab="reports">
          <i class="ti ti-send" aria-hidden="true"></i> Pelaporan Wajib Instansi
        </button>
      </div>

      ${isDocs ? renderDocumentsTab() : (
        isRegs ? renderRegulationsTab() : renderMandatoryReportsTab()
      )}
    `;
  }

  function renderDocumentsTab() {
    const docs = state.documents || [];
    const stats = state.documentsOverview || {
      total_active_docs: docs.filter(d => d.status === 'ACTIVE').length,
      review_alerts: 0,
      in_review_docs: docs.filter(d => ['DRAFT', 'UNDER_REVIEW'].includes(d.status)).length,
      fully_compliant_regulations: 0,
      pending_reports: 0,
    };

    return `
      <div class="hse-incident-stats">
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label">Total Dokumen Aktif</span>
          <span class="hse-stat-pill-val">${stats.total_active_docs || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.review_alerts > 0 ? 'var(--hse-fill-warning)' : 'var(--hse-border)'}; background:${stats.review_alerts > 0 ? 'var(--hse-bg-warning)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-warning);">Perlu Tinjauan Segera (&le;30h)</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-warning);font-weight:700;">${stats.review_alerts || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-primary);">Dokumen Draft / Review</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-primary);font-weight:700;">${stats.in_review_docs || 0}</span>
        </div>
        <div class="hse-stat-pill">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-success);">Regulasi Patuh Penuh</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-success);font-weight:700;">${stats.fully_compliant_regulations || 0}</span>
        </div>
        <div class="hse-stat-pill" style="border-color:${stats.pending_reports > 0 ? 'var(--hse-fill-danger)' : 'var(--hse-border)'}; background:${stats.pending_reports > 0 ? 'var(--hse-bg-danger)' : 'var(--hse-surface-2)'};">
          <span class="hse-stat-pill-label" style="color:var(--hse-text-danger);">Pelaporan Instansi Pending</span>
          <span class="hse-stat-pill-val" style="color:var(--hse-text-danger);font-weight:700;">${stats.pending_reports || 0}</span>
        </div>
      </div>

      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseDocSearch" placeholder="Cari nomor dokumen, judul, departemen..." value="${ESC(state.documentFilters.search)}">
          <select class="hse-filter-select" id="hseFilterDocType">
            <option value="">Semua Tipe Dokumen</option>
            <option value="POLICY" ${state.documentFilters.doc_type === 'POLICY' ? 'selected' : ''}>Policy (Kebijakan)</option>
            <option value="MANUAL" ${state.documentFilters.doc_type === 'MANUAL' ? 'selected' : ''}>Manual SMKP</option>
            <option value="SOP" ${state.documentFilters.doc_type === 'SOP' ? 'selected' : ''}>SOP (Prosedur Operasi)</option>
            <option value="WI" ${state.documentFilters.doc_type === 'WI' ? 'selected' : ''}>WI (Instruksi Kerja)</option>
            <option value="JSA" ${state.documentFilters.doc_type === 'JSA' ? 'selected' : ''}>JSA (Analisis Keselamatan Pekerjaan)</option>
            <option value="FORM" ${state.documentFilters.doc_type === 'FORM' ? 'selected' : ''}>Formulir / Checklist</option>
            <option value="ERP" ${state.documentFilters.doc_type === 'ERP' ? 'selected' : ''}>ERP (Rencana Tanggap Darurat)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterDocStatus">
            <option value="">Semua Status Dokumen</option>
            <option value="ACTIVE" ${state.documentFilters.status === 'ACTIVE' ? 'selected' : ''}>ACTIVE (Berlaku)</option>
            <option value="UNDER_REVIEW" ${state.documentFilters.status === 'UNDER_REVIEW' ? 'selected' : ''}>UNDER_REVIEW (Sedang Ditinjau)</option>
            <option value="DRAFT" ${state.documentFilters.status === 'DRAFT' ? 'selected' : ''}>DRAFT (Konsep)</option>
            <option value="OBSOLETE" ${state.documentFilters.status === 'OBSOLETE' ? 'selected' : ''}>OBSOLETE (Kedaluwarsa)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddDocument">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Dokumen HSE
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Nomor &amp; Judul Dokumen</th>
              <th>Tipe</th>
              <th>Revisi</th>
              <th>Berlaku Efektif</th>
              <th>Jadwal Tinjau Berkala</th>
              <th>Pemilik / Pengesah</th>
              <th>Status</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${docs.length === 0 ? `
              <tr>
                <td colspan="8" style="text-align:center;padding:32px;color:var(--hse-text-muted);">
                  Belum ada dokumen HSE yang sesuai dengan kriteria filter.
                </td>
              </tr>
            ` : docs.map(d => {
              const statusClass = d.status === 'ACTIVE' ? 'closed' :
                                  d.status === 'UNDER_REVIEW' ? 'verify' :
                                  d.status === 'DRAFT' ? 'in_action' : 'open';
              const isUrgentReview = d.next_review_date && new Date(d.next_review_date) <= new Date(Date.now() + 30 * 86400000);
              return `
                <tr>
                  <td>
                    <strong style="color:var(--hse-text-primary);font-size:12px;">${ESC(d.doc_number)}</strong>
                    <div style="font-size:11px;color:var(--hse-text-muted);">${ESC(d.title)}</div>
                  </td>
                  <td><span class="hse-status-badge in_action">${ESC(d.doc_type)}</span></td>
                  <td><span class="hse-doc-rev-badge">Rev ${ESC(d.revision_no ?? 0)}</span></td>
                  <td style="font-size:11px;">${ESC(String(d.effective_date || '').slice(0, 10))}</td>
                  <td style="font-size:11px;">
                    <span style="${isUrgentReview ? 'color:var(--hse-text-warning);font-weight:700;' : ''}">
                      ${ESC(String(d.next_review_date || '').slice(0, 10))}
                      ${isUrgentReview ? ' <i class="ti ti-alert-triangle" title="Jadwal tinjauan berkala sudah dekat"></i>' : ''}
                    </span>
                  </td>
                  <td style="font-size:11px;">
                    <div>${ESC(d.owner_dept || '-')}</div>
                    <div style="color:var(--hse-text-muted);">${ESC(d.approved_by || '-')}</div>
                  </td>
                  <td><span class="hse-status-badge ${statusClass}">${ESC(d.status)}</span></td>
                  <td>
                    <button type="button" class="hse-btn hse-btn--sm" data-revise-doc-id="${d.id}" data-revise-doc-number="${ESC(d.doc_number)}" title="Buat revisi dokumen baru">
                      <i class="ti ti-history" aria-hidden="true"></i> Revisi
                    </button>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderRegulationsTab() {
    const regs = state.legalRegisters || [];

    return `
      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseLegalSearch" placeholder="Cari nomor regulasi, judul, pasal..." value="${ESC(state.legalFilters.search)}">
          <select class="hse-filter-select" id="hseFilterLegalIssuer">
            <option value="">Semua Instansi Penerbit</option>
            <option value="ESDM_MINERBA" ${state.legalFilters.issuer === 'ESDM_MINERBA' ? 'selected' : ''}>Kementerian ESDM (Ditjen Minerba)</option>
            <option value="KEMENAKER" ${state.legalFilters.issuer === 'KEMENAKER' ? 'selected' : ''}>Kementerian Ketenagakerjaan</option>
            <option value="KLHK" ${state.legalFilters.issuer === 'KLHK' ? 'selected' : ''}>Kementerian LHK</option>
            <option value="PEMDA" ${state.legalFilters.issuer === 'PEMDA' ? 'selected' : ''}>Pemerintah Daerah (Provinsi/Kabupaten)</option>
          </select>
          <select class="hse-filter-select" id="hseFilterLegalStatus">
            <option value="">Semua Status Kepatuhan</option>
            <option value="COMPLIANT" ${state.legalFilters.compliance_status === 'COMPLIANT' ? 'selected' : ''}>COMPLIANT (Patuh Penuh)</option>
            <option value="PARTIAL" ${state.legalFilters.compliance_status === 'PARTIAL' ? 'selected' : ''}>PARTIAL (Sebagian)</option>
            <option value="NON_COMPLIANT" ${state.legalFilters.compliance_status === 'NON_COMPLIANT' ? 'selected' : ''}>NON_COMPLIANT (Belum Patuh)</option>
            <option value="NOT_ASSESSED" ${state.legalFilters.compliance_status === 'NOT_ASSESSED' ? 'selected' : ''}>NOT_ASSESSED (Belum Dievaluasi)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddLegalRegister">
          <i class="ti ti-plus" aria-hidden="true"></i> Tambah Inventarisasi Regulasi
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Nomor &amp; Judul Peraturan</th>
              <th>Instansi</th>
              <th>Ringkasan Kewajiban &amp; Pasal</th>
              <th>Status Kepatuhan</th>
              <th>Bukti Pemenuhan</th>
              <th>Evaluator &amp; Terakhir Evaluasi</th>
            </tr>
          </thead>
          <tbody>
            ${regs.length === 0 ? `
              <tr>
                <td colspan="6" style="text-align:center;padding:32px;color:var(--hse-text-muted);">
                  Belum ada inventarisasi regulasi hukum yang terdaftar.
                </td>
              </tr>
            ` : regs.map(r => {
              const statusClass = (r.compliance_status || 'not_assessed').toLowerCase();
              return `
                <tr>
                  <td>
                    <strong style="color:var(--hse-text-primary);font-size:12px;">${ESC(r.reg_number)}</strong>
                    <div style="font-size:11px;color:var(--hse-text-muted);">${ESC(r.title)}</div>
                  </td>
                  <td><span class="hse-status-badge in_action">${ESC(r.issuing_body)}</span></td>
                  <td style="max-width:280px;">
                    <div style="font-size:11px;">${ESC(r.compliance_requirements || '-')}</div>
                    ${r.relevant_articles ? `<div style="font-size:10px;color:var(--hse-text-muted);margin-top:2px;">Pasal: ${ESC(r.relevant_articles)}</div>` : ''}
                  </td>
                  <td>
                    <span class="hse-legal-status ${statusClass}">
                      ${ESC(r.compliance_status)}
                    </span>
                  </td>
                  <td style="font-size:11px;">${ESC(r.evidence_records || '-')}</td>
                  <td style="font-size:11px;">
                    <div><strong>${ESC(r.evaluator_name || '-')}</strong></div>
                    <div style="color:var(--hse-text-muted);">${ESC(String(r.last_evaluated_date || '').slice(0, 10))}</div>
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

  function renderMandatoryReportsTab() {
    const reports = state.mandatoryReports || [];

    return `
      <div class="hse-filter-bar">
        <div class="hse-filter-row">
          <input type="text" class="hse-filter-input" id="hseReportSearch" placeholder="Cari nama laporan, no receipt..." value="${ESC(state.mandatoryReportFilters.search)}">
          <select class="hse-filter-select" id="hseFilterReportAgency">
            <option value="">Semua Instansi Tujuan</option>
            <option value="ESDM_KAIT" ${state.mandatoryReportFilters.agency === 'ESDM_KAIT' ? 'selected' : ''}>Inspektur Tambang / Ditjen Minerba ESDM</option>
            <option value="DLH_KLHK" ${state.mandatoryReportFilters.agency === 'DLH_KLHK' ? 'selected' : ''}>Dinas LH / Kementerian LHK</option>
            <option value="DISNAKER" ${state.mandatoryReportFilters.agency === 'DISNAKER' ? 'selected' : ''}>Dinas Ketenagakerjaan</option>
            <option value="INTERNAL" ${state.mandatoryReportFilters.agency === 'INTERNAL' ? 'selected' : ''}>Manajemen Internal</option>
          </select>
          <select class="hse-filter-select" id="hseFilterReportStatus">
            <option value="">Semua Status Pelaporan</option>
            <option value="PENDING" ${state.mandatoryReportFilters.status === 'PENDING' ? 'selected' : ''}>PENDING (Menunggu Pengiriman)</option>
            <option value="SUBMITTED" ${state.mandatoryReportFilters.status === 'SUBMITTED' ? 'selected' : ''}>SUBMITTED (Terkirim)</option>
            <option value="OVERDUE" ${state.mandatoryReportFilters.status === 'OVERDUE' ? 'selected' : ''}>OVERDUE (Terlambat)</option>
            <option value="VERIFIED" ${state.mandatoryReportFilters.status === 'VERIFIED' ? 'selected' : ''}>VERIFIED (Diterima &amp; Selesai)</option>
          </select>
        </div>
        <button type="button" class="hse-btn hse-btn--primary" id="btnHseAddMandatoryReport">
          <i class="ti ti-plus" aria-hidden="true"></i> Catat Jadwal Pelaporan Wajib
        </button>
      </div>

      <div class="hse-table-wrap">
        <table class="hse-table">
          <thead>
            <tr>
              <th>Nama Laporan &amp; Dasar Hukum</th>
              <th>Instansi Tujuan</th>
              <th>Periode</th>
              <th>Tenggat Waktu</th>
              <th>Status</th>
              <th>Tgl Kirim &amp; Tanda Terima</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            ${reports.length === 0 ? `
              <tr>
                <td colspan="7" style="text-align:center;padding:32px;color:var(--hse-text-muted);">
                  Belum ada jadwal pelaporan instansi yang terdaftar.
                </td>
              </tr>
            ` : reports.map(r => {
              const statusClass = r.status === 'VERIFIED' ? 'closed' :
                                  r.status === 'SUBMITTED' ? 'verify' :
                                  r.status === 'OVERDUE' ? 'open' : 'in_action';
              return `
                <tr>
                  <td>
                    <strong style="color:var(--hse-text-primary);font-size:12px;">${ESC(r.report_name)}</strong>
                    <div style="font-size:11px;color:var(--hse-text-muted);">${ESC(r.legal_basis || '-')}</div>
                  </td>
                  <td><span class="hse-status-badge in_action">${ESC(r.recipient_agency)}</span></td>
                  <td style="font-size:11px;">
                    <div><strong>${ESC(r.period_label || r.period_type)}</strong></div>
                    <div style="color:var(--hse-text-muted);">${ESC(r.period_type)}</div>
                  </td>
                  <td style="font-size:11px;">
                    <strong>${ESC(String(r.deadline_date || '').slice(0, 10))}</strong>
                  </td>
                  <td><span class="hse-status-badge ${statusClass}">${ESC(r.status)}</span></td>
                  <td style="font-size:11px;">
                    <div>${r.submission_date ? ESC(String(r.submission_date).slice(0, 10)) : '-'}</div>
                    ${r.receipt_no ? `<div style="color:var(--hse-text-muted);">No: ${ESC(r.receipt_no)}</div>` : ''}
                  </td>
                  <td>
                    ${r.status === 'PENDING' || r.status === 'OVERDUE' ? `
                      <button type="button" class="hse-btn hse-btn--sm" data-submit-report-id="${r.id}" data-submit-report-name="${ESC(r.report_name)}" title="Perbarui status pengiriman dan bukti tanda terima">
                        <i class="ti ti-send" aria-hidden="true"></i> Kirim Lapor
                      </button>
                    ` : `
                      <span style="font-size:11px;color:var(--hse-text-success);"><i class="ti ti-check" aria-hidden="true"></i> Submitted</span>
                    `}
                  </td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    `;
  }

