  function openCreatePpeIssuanceModal() {
    const employees = state.masters.employees || [];
    const items = state.ppeItems || [];
    const today = new Date().toISOString().slice(0, 10);

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">Penyerahan & Distribusi APD ke Karyawan</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseCreatePpeIssuance" style="margin-top:12px;">
        <div class="hse-form-group">
          <label class="hse-form-label">Pilih Karyawan Penerima *</label>
          <select class="hse-form-select" id="inIssEmpId" required>
            <option value="">Pilih Karyawan...</option>
            ${employees.map(e => `<option value="${e.id}" data-nama="${ESC(e.nama)}" data-nrp="${ESC(e.nrp || '')}" data-dept="${ESC(e.departemen || '')}" data-pos="${ESC(e.jabatan || '')}">${ESC(e.nama)} (${ESC(e.nrp || '-')}) - ${ESC(e.jabatan || '-')}</option>`).join('')}
          </select>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Pilih Item APD *</label>
          <select class="hse-form-select" id="inIssItemId" required>
            <option value="">Pilih APD...</option>
            ${items.map(it => `<option value="${it.id}" data-nama="${ESC(it.name)}" data-cat="${ESC(it.category)}" data-interval="${it.replace_interval_months}">[${ESC(it.category)}] ${ESC(it.name)} (Stok: ${it.current_stock})</option>`).join('')}
          </select>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Ukuran APD (Bila Ada)</label>
            <input type="text" class="hse-form-input" id="inIssSize" placeholder="S, M, L, XL, 41, 42, dsb.">
          </div>
          <div>
            <label class="hse-form-label">Jumlah Diberikan *</label>
            <input type="number" class="hse-form-input" id="inIssQty" value="1" min="1" required>
          </div>
        </div>

        <div class="hse-form-row">
          <div>
            <label class="hse-form-label">Tanggal Penyerahan *</label>
            <input type="date" class="hse-form-input" id="inIssDate" value="${today}" required>
          </div>
          <div>
            <label class="hse-form-label">Alasan Distribusi *</label>
            <select class="hse-form-select" id="inIssReason" required>
              <option value="NEW_HIRE">Karyawan Baru (New Hire)</option>
              <option value="REPLACEMENT">Penggantian Berkala (Expired)</option>
              <option value="DAMAGED">Rusak Saat Tugas (Damaged)</option>
              <option value="LOST">Hilang / Penggantian Khusus</option>
              <option value="ADDITIONAL">Tambahan APD Khusus Area</option>
            </select>
          </div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Petugas Penyerah (Logistik HSE)</label>
          <input type="text" class="hse-form-input" id="inIssOfficer" placeholder="Nama Petugas Logistik / Admin HSE">
        </div>

        <div id="hseIssFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitIss">Konfirmasi Penyerahan APD</button>
        </div>
      </form>
    `;

    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const form = document.getElementById('formHseCreatePpeIssuance');
    const submitBtn = document.getElementById('btnSubmitIss');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseIssFormError');
        if (errEl) errEl.hidden = true;

        const empSel = document.getElementById('inIssEmpId');
        const empOpt = empSel?.options[empSel.selectedIndex];

        const itemSel = document.getElementById('inIssItemId');
        const itemOpt = itemSel?.options[itemSel.selectedIndex];

        const payload = {
          employee_id: empSel?.value,
          employee_name: empOpt?.dataset.nama || '',
          employee_nrp: empOpt?.dataset.nrp || null,
          department_name: empOpt?.dataset.dept || null,
          position_name: empOpt?.dataset.pos || null,
          ppe_item_id: itemSel?.value,
          ppe_item_name: itemOpt?.dataset.nama || '',
          ppe_category: itemOpt?.dataset.cat || '',
          size: document.getElementById('inIssSize')?.value.trim() || null,
          quantity: parseInt(document.getElementById('inIssQty')?.value, 10) || 1,
          issued_date: document.getElementById('inIssDate')?.value,
          reason: document.getElementById('inIssReason')?.value,
          issued_by_name: document.getElementById('inIssOfficer')?.value.trim() || null,
        };

        const work = async () => {
          await api('/ppe/issuances', { method: 'POST', body: payload });
          state.activeModal = null;
          await loadPpeData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

