  function openResolveAuditFindingModal(findingId) {
    const finding = (state.auditFindings || []).find(f => f.id === findingId);
    if (!finding) return;

    state.activeModal = `
      <div class="hse-modal-header">
        <div class="hse-modal-title">Verifikasi &amp; Pembaruan Temuan Audit #${ESC(finding.finding_no)}</div>
        <button type="button" class="hse-modal-close" id="btnHseCloseModal2">&times;</button>
      </div>
      <form id="formHseResolveFinding" style="margin-top:12px;">
        <div style="font-size:12px;margin-bottom:12px;background:var(--hse-surface-2);padding:10px;border-radius:4px;">
          <div><strong>Uraian:</strong> ${ESC(finding.description)}</div>
          <div style="margin-top:4px;"><strong>Kategori:</strong> ${ESC(finding.category)} | <strong>PIC:</strong> ${ESC(finding.pic_name || '-')}</div>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Status Tindak Lanjut *</label>
          <select class="hse-form-select" id="inResolveStatus" required>
            <option value="IN_ACTION" ${finding.status === 'IN_ACTION' ? 'selected' : ''}>IN_ACTION (Sedang Ditindaklanjuti)</option>
            <option value="VERIFY" ${finding.status === 'VERIFY' ? 'selected' : ''}>VERIFY (Selesai Tindakan, Menunggu Verifikasi Auditor)</option>
            <option value="CLOSED" ${finding.status === 'CLOSED' ? 'selected' : ''}>CLOSED (Terverifikasi Efektif &amp; Ditutup)</option>
          </select>
        </div>

        <div class="hse-form-group">
          <label class="hse-form-label">Catatan Hasil Verifikasi / Tindakan Korektif *</label>
          <textarea class="hse-form-textarea" id="inResolveNotes" placeholder="Uraikan bukti implementasi tindakan korektif dan hasil verifikasi auditor..." required></textarea>
        </div>

        <div id="hseResolveFormError" style="color:var(--hse-text-danger);font-size:11px;margin-bottom:8px;" hidden></div>
        <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px;">
          <button type="button" class="hse-btn" id="btnHseCloseModal2">Batal</button>
          <button type="submit" class="hse-btn hse-btn--primary" id="btnSubmitResolveFinding">Simpan Status</button>
        </div>
      </form>
    `;

    render();

    document.getElementById('btnHseCloseModal2')?.addEventListener('click', () => {
      state.activeModal = null;
      render();
    });

    const form = document.getElementById('formHseResolveFinding');
    const submitBtn = document.getElementById('btnSubmitResolveFinding');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const errEl = document.getElementById('hseResolveFormError');
        if (errEl) errEl.hidden = true;

        const payload = {
          status: document.getElementById('inResolveStatus')?.value,
          resolution_notes: document.getElementById('inResolveNotes')?.value.trim(),
        };

        const work = async () => {
          await api(`/audits/findings/${findingId}/resolve`, { method: 'PUT', body: payload });
          state.activeModal = null;
          await loadAuditData();
          render();
        };

        if (global.OMOSActionFeedback?.run) {
          await global.OMOSActionFeedback.run(submitBtn, work).catch(err => {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          });
        } else {
          try {
            await work();
          } catch (err) {
            if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
          }
        }
      });
    }
  }

