  async function load(targetEl) {
    rootEl = targetEl || document.getElementById('hseRoot');
    if (!rootEl) return;
    await loadData();
    render();
  }

  function setSubView(viewKey) {
    if (SUBPAGE_METADATA[viewKey]) {
      state.view = viewKey;
      render();
    }
  }

  function toggleBigScreenMode(active) {
    state.isBigScreenMode = (active !== undefined) ? !!active : !state.isBigScreenMode;
    if (!state.isBigScreenMode) {
      stopBigScreenTimers();
    }
    render();
  }

  if (typeof window !== 'undefined') {
    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && state.isBigScreenMode) {
        toggleBigScreenMode(false);
      }
    });
  }

